INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u6-C1','math',5,1,'u6',2,'둘레와 넓이의 뜻 — 둘레는 가장자리를 따라 잰 길이, 넓이는 같은 크기의 칸으로 덮은 칸의 수임을 알고, 둘레가 같아도 넓이는 다를 수 있음을 알기',ARRAY['6수03-07']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u6-C2','math',5,1,'u6',2,'다각형의 둘레 — 모든 변의 길이를 더해 구하고, 직사각형·평행사변형은 마주 보는 두 변이 같아 (이웃한 두 변의 합) × 2로 구하기(높이는 변이 아님)',ARRAY['6수03-07']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u6-C3','math',5,1,'u6',3,'마름모·정다각형의 둘레 — 변의 길이가 모두 같으므로 (한 변의 길이) × (변의 수)로 구하고, 둘레에서 한 변의 길이를 거꾸로 구하기',ARRAY['6수03-07']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u6-C4','math',5,1,'u6',5,'넓이의 단위 1 cm² — 한 변이 1 cm인 정사각형의 넓이를 1 cm²(1 제곱센티미터)로 약속한 까닭을 알고, 1 cm² 칸의 수로 넓이를 세기',ARRAY['6수03-08']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u6-C5','math',5,1,'u6',5,'직사각형·정사각형의 넓이 — 한 줄의 칸 수 × 줄의 수로 (가로) × (세로), (한 변) × (한 변)을 이해하고 넓이에서 변의 길이를 거꾸로 구하기',ARRAY['6수03-09']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u6-C6','math',5,1,'u6',6,'넓이의 단위 m²·km² — 1 m² = 10000 cm², 1 km² = 1000000 m²임을 가로·세로 두 방향의 배로 이해하고, 단위를 맞추어 넓이를 구하기',ARRAY['6수03-08']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u6-C7','math',5,1,'u6',7,'평행사변형의 넓이 — 밑변과 높이(두 밑변 사이의 수직 거리)를 알고, 잘라 옮겨 직사각형으로 바꾸어 (밑변의 길이) × (높이)로 구하기(이웃한 변이 아님)',ARRAY['6수03-09']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u6-C8','math',5,1,'u6',8,'삼각형의 넓이 — 밑변과 높이를 알고(높이가 삼각형 밖에 있을 수도 있음), 똑같은 삼각형 두 개로 평행사변형·직사각형을 만들어 (밑변의 길이) × (높이) ÷ 2로 구하기',ARRAY['6수03-09']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u6-C9','math',5,1,'u6',9,'사다리꼴의 넓이 — 윗변·아랫변·높이를 알고, 똑같은 사다리꼴 두 개로 평행사변형을 만들어 ((윗변) + (아랫변)) × (높이) ÷ 2로 구하며 나누어 구한 값과 같음을 알기',ARRAY['6수03-09']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u6-C10','math',5,1,'u6',10,'마름모의 넓이 — 마름모를 감싸는 직사각형의 가로·세로가 두 대각선임을 알고 그 절반인 (한 대각선) × (다른 대각선) ÷ 2로 구하기(둘레는 한 변, 넓이는 대각선)',ARRAY['6수03-09']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-1-u6-C11','math',5,1,'u6',11,'여러 가지 방법으로 넓이 구하기 — 반듯하지 않은 도형을 아는 도형으로 나누어 더하거나 큰 도형에서 빼어 구하고, 겹치거나 빠뜨리지 않으면 어느 방법이든 답이 같음을 알기',ARRAY['6수03-09']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X01','math',5,'u6',ARRAY['M5-1-u6-C1','M5-1-u6-C2','M5-1-u6-C5','M5-1-u6-C11']::text[],'둘레와 넓이를 섞는다 — 넓이를 (가로 + 세로) × 2로 구하거나 둘레를 가로 × 세로로 구하고, cm와 cm²를 가리지 않는다','가장자리 길이인지, 덮은 칸 수인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X02','math',5,'u6',ARRAY['M5-1-u6-C1','M5-1-u6-C4','M5-1-u6-C5']::text[],'둘레가 같으면 넓이도 같다고, 또는 둘레가 길면 넓이도 반드시 넓다고 여긴다','둘레가 같은 두 도형의 칸 세어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X03','math',5,'u6',ARRAY['M5-1-u6-C2','M5-1-u6-C3']::text[],'직사각형·평행사변형의 둘레에서 이웃한 두 변만 더하고 × 2를 빠뜨리거나, 둘레에서 한 변을 구할 때 2로 나누지 않는다','네 변을 손가락으로 하나씩 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X04','math',5,'u6',ARRAY['M5-1-u6-C2']::text[],'평행사변형의 둘레에 높이를 넣는다 — 높이는 변이 아니다','둘레는 가장자리만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X05','math',5,'u6',ARRAY['M5-1-u6-C3']::text[],'정다각형의 둘레에서 변의 수를 잘못 쓴다 — 언제나 4를 곱하거나, 정오각형의 변을 4개·6개로 센다','이름 속 변의 수 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X06','math',5,'u6',ARRAY['M5-1-u6-C4']::text[],'1 cm²를 둘레가 1 cm인 도형이나 가로가 1 cm인 도형의 넓이로 알거나, 크기가 다른 칸의 수로 넓이를 견준다','한 변 1 cm 정사각형 한 칸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X07','math',5,'u6',ARRAY['M5-1-u6-C5','M5-1-u6-C6','M5-1-u6-C7','M5-1-u6-C10']::text[],'길이가 몇 배가 되면 넓이도 그만큼만 커진다고 여긴다 — 1 m² = 100 cm², 1 km² = 1000 m², 가로·세로를 2배 하면 넓이도 2배','가로도 세로도 늘어남') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X08','math',5,'u6',ARRAY['M5-1-u6-C6']::text[],'단위를 맞추지 않고 곱한다 — 200 cm × 1 m를 200 m²로','곱하기 전에 단위부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X09','math',5,'u6',ARRAY['M5-1-u6-C7']::text[],'평행사변형의 넓이를 밑변과 이웃한 변을 곱해 구한다','잘라 옮기면 세로는 높이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X10','math',5,'u6',ARRAY['M5-1-u6-C8','M5-1-u6-C9','M5-1-u6-C10']::text[],'삼각형·사다리꼴·마름모의 넓이에서 ÷ 2를 빠뜨리거나, 평행사변형·직사각형에도 ÷ 2를 붙인다','둘을 붙였는지 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X11','math',5,'u6',ARRAY['M5-1-u6-C7','M5-1-u6-C8','M5-1-u6-C9']::text[],'높이를 밑변에 수직이 아닌 선분(이웃한 변·대각선·빗변)으로 안다','밑변과 직각인 선분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X12','math',5,'u6',ARRAY['M5-1-u6-C9']::text[],'사다리꼴의 넓이에서 윗변이나 아랫변 하나만 쓰거나, 윗변 + 아랫변 + 높이처럼 모두 더한다','윗변과 아랫변을 먼저 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X13','math',5,'u6',ARRAY['M5-1-u6-C10']::text[],'마름모의 넓이를 한 변 × 한 변이나 한 변 × 4로 구하거나, 두 대각선을 더한다','넓이는 두 대각선으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X14','math',5,'u6',ARRAY['M5-1-u6-C3','M5-1-u6-C5','M5-1-u6-C7','M5-1-u6-C8','M5-1-u6-C9','M5-1-u6-C10']::text[],'넓이·둘레에서 변이나 높이를 거꾸로 구할 때 곱셈과 나눗셈을 바꾸거나 ÷ 2를 되돌리지 않는다','공식에 □를 넣고 거꾸로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X15','math',5,'u6',ARRAY['M5-1-u6-C2','M5-1-u6-C11']::text[],'나누어 더할 때 겹친 부분을 두 번 세거나 빠뜨리고, 빼야 할 부분을 더한다 — 붙인 변을 둘레에 넣기도 한다','겹침·빠짐 색칠해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X16','math',5,'u6',ARRAY['M5-1-u6-C1','M5-1-u6-C2','M5-1-u6-C3','M5-1-u6-C4','M5-1-u6-C5','M5-1-u6-C6','M5-1-u6-C7','M5-1-u6-C8','M5-1-u6-C9','M5-1-u6-C10','M5-1-u6-C11']::text[],'한 걸음의 셈(곱셈·나눗셈·덧셈)을 잘못한다','곱셈을 한 번 더 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-1-u6-X17','math',5,'u6',ARRAY['M5-1-u6-C1','M5-1-u6-C2','M5-1-u6-C3','M5-1-u6-C4','M5-1-u6-C5','M5-1-u6-C6','M5-1-u6-C7','M5-1-u6-C8','M5-1-u6-C9','M5-1-u6-C10','M5-1-u6-C11']::text[],'묻는 말을 거꾸로 읽는다 — 잘못된↔옳은, 가장 넓은↔가장 좁은, 둘레↔넓이','물음의 「잘못·가장·둘레·넓이」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_basic#1','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C1',1,'mc','auto','둘레는 무엇을 뜻하나요?',ARRAY['M5-1-u6-X01','M5-1-u6-X03','M5-1-u6-X16']::text[],true,'{"seq":1,"concept":"M5-1-u6-C1","difficulty":1,"kind":"mc","stem":"둘레는 무엇을 뜻하나요?","options":[{"t":"도형의 가장자리를 따라 잰 길이","correct":true},{"t":"도형 안쪽을 덮은 칸의 수","mis":"M5-1-u6-X01"},{"t":"가장 긴 변 하나의 길이","mis":"M5-1-u6-X03"},{"t":"변의 수","mis":"M5-1-u6-X16"}],"explanation":["게시판 가장자리에 두르는 색 띠지의 길이를 떠올려 봐요.","가장자리를 따라 한 바퀴 잰 길이가 둘레예요.","안쪽을 덮은 칸의 수는 넓이예요 — 둘은 다른 양이에요."],"variant_rule":{"alt":[{"stem":"넓이는 무엇을 뜻하나요?","options":[{"t":"같은 크기의 칸으로 안쪽을 덮은 칸의 수","correct":true},{"t":"가장자리를 따라 잰 길이","mis":"M5-1-u6-X01"},{"t":"가장 긴 변의 길이","mis":"M5-1-u6-X01"},{"t":"변의 수","mis":"M5-1-u6-X16"}],"explanation":["게시판 안쪽을 도화지로 덮는 것을 떠올려 봐요.","같은 크기의 칸으로 덮었을 때 칸이 몇 개인지가 넓이예요.","가장자리를 따라 잰 길이는 둘레예요."]},{"stem":"게시판 가장자리에 색 띠지를 두르려고 해요. 띠지가 얼마나 필요한지 알려면 무엇을 구해야 하나요?","options":[{"t":"게시판의 둘레","correct":true},{"t":"게시판의 넓이","mis":"M5-1-u6-X01"},{"t":"게시판 안쪽 칸의 수","mis":"M5-1-u6-X01"},{"t":"게시판 한 변의 길이","mis":"M5-1-u6-X03"}],"explanation":["띠지는 가장자리를 따라 둘러요.","가장자리를 따라 잰 길이가 둘레예요.","그래서 게시판의 둘레를 구해야 해요 — 넓이는 도화지로 덮을 때 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_basic#2','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',1,'sa','auto','가로 7 cm, 세로 3 cm인 직사각형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C2","difficulty":1,"kind":"sa","stem":"가로 7 cm, 세로 3 cm인 직사각형의 둘레는 몇 cm인가요?","answer":["20"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","7 + 3 + 7 + 3 = 20이에요.","(7 + 3) × 2 = 20으로 구해도 돼요 — 둘레는 20 cm예요."],"variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 4 cm인 직사각형의 둘레는 몇 cm인가요?","answer":["26"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","9 + 4 + 9 + 4 = 26이에요.","(9 + 4) × 2 = 26으로 구해도 돼요 — 둘레는 26 cm예요."]},{"stem":"가로 12 m, 세로 5 m인 직사각형의 둘레는 몇 m인가요?","answer":["34"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","12 + 5 + 12 + 5 = 34예요.","(12 + 5) × 2 = 34로 구해도 돼요 — 둘레는 34 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_basic#3','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',1,'mc','auto','다각형의 둘레를 구하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X01','M5-1-u6-X16']::text[],true,'{"seq":3,"concept":"M5-1-u6-C2","difficulty":1,"kind":"mc","stem":"다각형의 둘레를 구하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"각 변의 길이를 모두 더한다","correct":true},{"t":"가장 긴 변을 변의 수만큼 곱한다","mis":"M5-1-u6-X05"},{"t":"가로와 세로를 곱한다","mis":"M5-1-u6-X01"},{"t":"변의 수를 센다","mis":"M5-1-u6-X16"}],"explanation":["둘레는 가장자리를 따라 잰 길이예요.","가장자리는 변들로 이어져 있어요.","그래서 각 변의 길이를 모두 더하면 둘레예요."],"variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 3 cm인 직사각형의 둘레를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(7 + 3) × 2","correct":true},{"t":"7 × 3","mis":"M5-1-u6-X01"},{"t":"7 + 3","mis":"M5-1-u6-X03"},{"t":"7 × 3 ÷ 2","mis":"M5-1-u6-X10"}],"explanation":["직사각형은 가로와 세로가 각각 두 번씩 있어요.","7 + 3 + 7 + 3은 이웃한 두 변의 합을 2번 더한 것과 같아요.","그래서 (7 + 3) × 2 = 20으로 구해요."]},{"stem":"밑변 9 cm, 이웃한 변 4 cm인 평행사변형의 둘레를 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"(9 + 4) × 2","correct":true},{"t":"9 × 4","mis":"M5-1-u6-X01"},{"t":"9 + 4","mis":"M5-1-u6-X03"},{"t":"9 × 2 + 4","mis":"M5-1-u6-X03"}],"explanation":["평행사변형도 마주 보는 두 변의 길이가 같아요.","네 변은 9 cm, 4 cm, 9 cm, 4 cm예요.","그래서 (9 + 4) × 2 = 26으로 구해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_basic#4','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',1,'sa','auto','체험 학습 깃발의 삼각형 부분이에요. 세 변의 길이가 30 cm, 22 cm, 30 cm일 때 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C2","difficulty":1,"kind":"sa","stem":"체험 학습 깃발의 삼각형 부분이에요. 세 변의 길이가 30 cm, 22 cm, 30 cm일 때 둘레는 몇 cm인가요?","answer":["82"],"explanation":["다각형의 둘레는 모든 변의 길이의 합이에요.","30 + 22 + 30 = 82예요.","그래서 둘레는 82 cm예요."],"variant_rule":{"alt":[{"stem":"체험 학습 깃발의 삼각형 부분이에요. 세 변의 길이가 25 cm, 18 cm, 25 cm일 때 둘레는 몇 cm인가요?","answer":["68"],"explanation":["다각형의 둘레는 모든 변의 길이의 합이에요.","25 + 18 + 25 = 68이에요.","그래서 둘레는 68 cm예요."]},{"stem":"체험 학습 깃발의 사각형 부분이에요. 네 변의 길이가 22 cm, 16 cm, 22 cm, 16 cm일 때 둘레는 몇 cm인가요?","answer":["76"],"explanation":["다각형의 둘레는 모든 변의 길이의 합이에요.","22 + 16 + 22 + 16 = 76이에요.","그래서 둘레는 76 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_basic#5','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C1',2,'mc','auto','모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 그림의 직사각형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X16']::text[],true,'{"seq":5,"concept":"M5-1-u6-C1","difficulty":2,"kind":"mc","stem":"모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 그림의 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"21 cm²","correct":true},{"t":"20 cm²","mis":"M5-1-u6-X01"},{"t":"10 cm²","mis":"M5-1-u6-X01"},{"t":"28 cm²","mis":"M5-1-u6-X16"}],"explanation":["한 줄에 7칸씩, 그런 줄이 3줄 있어요.","7 × 3 = 21 — 모두 21칸이에요.","한 칸이 1 cm²니 넓이는 21 cm²예요. 20 cm는 둘레예요."],"asset":{"type":"geo","items":[{"w":135,"h":75,"grid":15,"poly":[[[15,15],[120,15],[120,60],[15,60]]],"show":[]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 그림의 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"20 cm²","correct":true},{"t":"18 cm²","mis":"M5-1-u6-X01"},{"t":"9 cm²","mis":"M5-1-u6-X01"},{"t":"25 cm²","mis":"M5-1-u6-X16"}],"explanation":["한 줄에 5칸씩, 그런 줄이 4줄 있어요.","5 × 4 = 20 — 모두 20칸이에요.","한 칸이 1 cm²니 넓이는 20 cm²예요. 18 cm는 둘레예요."],"asset":{"type":"geo","items":[{"w":105,"h":90,"grid":15,"poly":[[[15,15],[90,15],[90,75],[15,75]]],"show":[]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 그림의 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"12 cm²","correct":true},{"t":"16 cm²","mis":"M5-1-u6-X01"},{"t":"8 cm²","mis":"M5-1-u6-X01"},{"t":"18 cm²","mis":"M5-1-u6-X16"}],"explanation":["한 줄에 6칸씩, 그런 줄이 2줄 있어요.","6 × 2 = 12 — 모두 12칸이에요.","한 칸이 1 cm²니 넓이는 12 cm²예요. 16 cm는 둘레예요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"grid":15,"poly":[[[15,15],[105,15],[105,45],[15,45]]],"show":[]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_basic#6','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',2,'sa','auto','평행사변형의 밑변이 8 cm, 이웃한 변이 4 cm예요. 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-1-u6-C2","difficulty":2,"kind":"sa","stem":"평행사변형의 밑변이 8 cm, 이웃한 변이 4 cm예요. 둘레는 몇 cm인가요?","answer":["24"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","8 + 4 + 8 + 4 = 24예요.","(8 + 4) × 2 = 24 — 둘레는 24 cm예요."],"variant_rule":{"alt":[{"stem":"평행사변형의 밑변이 12 m, 이웃한 변이 3 m예요. 둘레는 몇 m인가요?","answer":["30"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","12 + 3 + 12 + 3 = 30이에요.","(12 + 3) × 2 = 30 — 둘레는 30 m예요."]},{"stem":"평행사변형의 밑변이 9 cm, 이웃한 변이 5 cm예요. 둘레는 몇 cm인가요?","answer":["28"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","9 + 5 + 9 + 5 = 28이에요.","(9 + 5) × 2 = 28 — 둘레는 28 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_basic#7','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',2,'mc','auto','밑변 8 cm, 이웃한 변 5 cm, 높이 3 cm인 평행사변형이에요. 둘레를 구하는 식으로 잘못된 것은 어느 것인가요?',ARRAY['M5-1-u6-X17']::text[],true,'{"seq":7,"concept":"M5-1-u6-C2","difficulty":2,"kind":"mc","stem":"밑변 8 cm, 이웃한 변 5 cm, 높이 3 cm인 평행사변형이에요. 둘레를 구하는 식으로 잘못된 것은 어느 것인가요?","options":[{"t":"(8 + 3) × 2","correct":true},{"t":"8 + 5 + 8 + 5","mis":"M5-1-u6-X17"},{"t":"(8 + 5) × 2","mis":"M5-1-u6-X17"},{"t":"8 × 2 + 5 × 2","mis":"M5-1-u6-X17"}],"explanation":["둘레는 가장자리를 이루는 네 변의 길이의 합이에요.","높이 3 cm는 두 밑변 사이의 거리라 가장자리가 아니에요.","그래서 높이를 넣은 (8 + 3) × 2가 잘못된 식이에요 — 바른 둘레는 26 cm예요."],"variant_rule":{"alt":[{"stem":"밑변 10 cm, 이웃한 변 6 cm, 높이 4 cm인 평행사변형이에요. 둘레를 구하는 식으로 잘못된 것은 어느 것인가요?","options":[{"t":"(10 + 4) × 2","correct":true},{"t":"10 + 6 + 10 + 6","mis":"M5-1-u6-X17"},{"t":"(10 + 6) × 2","mis":"M5-1-u6-X17"},{"t":"10 × 2 + 6 × 2","mis":"M5-1-u6-X17"}],"explanation":["둘레는 가장자리를 이루는 네 변의 길이의 합이에요.","높이 4 cm는 두 밑변 사이의 거리라 가장자리가 아니에요.","그래서 높이를 넣은 (10 + 4) × 2가 잘못된 식이에요 — 바른 둘레는 32 cm예요."]},{"stem":"밑변 7 cm, 이웃한 변 4 cm, 높이 3 cm인 평행사변형이에요. 둘레를 구하는 식으로 잘못된 것은 어느 것인가요?","options":[{"t":"(7 + 3) × 2","correct":true},{"t":"7 + 4 + 7 + 4","mis":"M5-1-u6-X17"},{"t":"(7 + 4) × 2","mis":"M5-1-u6-X17"},{"t":"7 × 2 + 4 × 2","mis":"M5-1-u6-X17"}],"explanation":["둘레는 가장자리를 이루는 네 변의 길이의 합이에요.","높이 3 cm는 두 밑변 사이의 거리라 가장자리가 아니에요.","그래서 높이를 넣은 (7 + 3) × 2가 잘못된 식이에요 — 바른 둘레는 22 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_basic#8','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C1',2,'ox','auto','둘레가 같은 두 직사각형은 넓이도 반드시 같아요.',ARRAY['M5-1-u6-X02']::text[],true,'{"seq":8,"concept":"M5-1-u6-C1","difficulty":2,"kind":"ox","stem":"둘레가 같은 두 직사각형은 넓이도 반드시 같아요.","answer":"X","reason_options":[{"t":"둘레가 20 cm로 같아도 5 × 5 = 25, 9 × 1 = 9로 넓이가 다르므로","correct":true},{"t":"둘레가 같으면 가로와 세로도 같으므로","mis":"M5-1-u6-X02"}],"mis":"M5-1-u6-X02","explanation":["가로 5 cm, 세로 5 cm인 정사각형과 가로 9 cm, 세로 1 cm인 직사각형은 둘레가 모두 20 cm예요.","넓이는 5 × 5 = 25, 9 × 1 = 9예요.","둘레가 같아도 넓이는 다를 수 있어요."],"variant_rule":{"alt":[{"stem":"둘레가 더 긴 도형이 넓이도 언제나 더 넓어요.","answer":"X","reason_options":[{"t":"둘레 20 cm인 9 × 1 직사각형은 둘레 16 cm인 5 × 3 직사각형보다 좁으므로","correct":true},{"t":"가장자리가 길면 안쪽도 늘 넓어지므로","mis":"M5-1-u6-X02"}],"explanation":["가로 9 cm, 세로 1 cm인 직사각형은 둘레 20 cm, 넓이 9 cm²예요.","가로 5 cm, 세로 3 cm인 직사각형은 둘레 16 cm, 넓이 15 cm²예요.","둘레가 더 긴 쪽이 오히려 좁아요 — 둘레와 넓이는 다른 양이에요."]},{"stem":"둘레는 cm로, 넓이는 cm²로 나타내요.","answer":"O","reason_options":[{"t":"둘레는 길이이고 넓이는 칸의 수라 재는 것이 다르므로","correct":true},{"t":"둘레가 넓이보다 늘 작으므로","mis":"M5-1-u6-X01"}],"explanation":["둘레는 가장자리를 따라 잰 길이예요.","넓이는 한 변이 1 cm인 칸이 몇 개인지예요.","재는 것이 달라 단위도 cm와 cm²로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_basic#9','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',2,'mc','auto','둘레가 더 긴 것은 어느 것인가요? ㉠ 가로 9 cm, 세로 4 cm인 직사각형 ㉡ 밑변 7 cm, 이웃한 변 5 cm인 평행사변형',ARRAY['M5-1-u6-X16','M5-1-u6-X02','M5-1-u6-X04']::text[],true,'{"seq":9,"concept":"M5-1-u6-C2","difficulty":2,"kind":"mc","stem":"둘레가 더 긴 것은 어느 것인가요? ㉠ 가로 9 cm, 세로 4 cm인 직사각형 ㉡ 밑변 7 cm, 이웃한 변 5 cm인 평행사변형","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M5-1-u6-X16"},{"t":"두 둘레가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X04"}],"explanation":["㉠의 둘레는 (9 + 4) × 2 = 26이에요.","㉡의 둘레는 (7 + 5) × 2 = 24예요.","26 cm와 24 cm를 견주면 ㉠의 둘레가 더 길어요."],"variant_rule":{"alt":[{"stem":"둘레가 더 긴 것은 어느 것인가요? ㉠ 가로 6 cm, 세로 6 cm인 직사각형 ㉡ 밑변 8 cm, 이웃한 변 3 cm인 평행사변형","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M5-1-u6-X16"},{"t":"두 둘레가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X04"}],"explanation":["㉠의 둘레는 (6 + 6) × 2 = 24예요.","㉡의 둘레는 (8 + 3) × 2 = 22예요.","24 cm와 22 cm를 견주면 ㉠의 둘레가 더 길어요."]},{"stem":"둘레가 더 긴 것은 어느 것인가요? ㉠ 가로 10 cm, 세로 2 cm인 직사각형 ㉡ 밑변 7 cm, 이웃한 변 4 cm인 평행사변형","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M5-1-u6-X16"},{"t":"두 둘레가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X04"}],"explanation":["㉠의 둘레는 (10 + 2) × 2 = 24예요.","㉡의 둘레는 (7 + 4) × 2 = 22예요.","24 cm와 22 cm를 견주면 ㉠의 둘레가 더 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_basic#10','math',5,1,'u6','L02','g5_1_math_u6_L02_basic','lesson_basic','M5-1-u6-C2',3,'sa','auto','둘레가 34 cm인 직사각형의 가로가 11 cm예요. 세로는 몇 cm인가요?','{}'::text[],true,'{"seq":10,"concept":"M5-1-u6-C2","difficulty":3,"kind":"sa","stem":"둘레가 34 cm인 직사각형의 가로가 11 cm예요. 세로는 몇 cm인가요?","answer":["6"],"explanation":["직사각형의 둘레는 (가로 + 세로) × 2예요.","가로 + 세로 = 34 ÷ 2 = 17이에요.","세로 = 17 − 11 = 6 — 세로는 6 cm예요."],"mis":"M5-1-u6-X03","variant_rule":{"alt":[{"stem":"둘레가 40 cm인 직사각형의 가로가 12 cm예요. 세로는 몇 cm인가요?","answer":["8"],"explanation":["직사각형의 둘레는 (가로 + 세로) × 2예요.","가로 + 세로 = 40 ÷ 2 = 20이에요.","세로 = 20 − 12 = 8 — 세로는 8 cm예요."]},{"stem":"둘레가 26 cm인 직사각형의 가로가 8 cm예요. 세로는 몇 cm인가요?","answer":["5"],"explanation":["직사각형의 둘레는 (가로 + 세로) × 2예요.","가로 + 세로 = 26 ÷ 2 = 13이에요.","세로 = 13 − 8 = 5 — 세로는 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_challenge#1','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C2',2,'error','auto','가로 7 cm, 세로 3 cm인 직사각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u6-X03','M5-1-u6-X17']::text[],true,'{"seq":1,"concept":"M5-1-u6-C2","difficulty":2,"kind":"error","stem":"가로 7 cm, 세로 3 cm인 직사각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「가로와 세로를 더한 10 cm가 둘레야.」","correct":true,"mis_target":"M5-1-u6-X03"},{"t":"도현 — 「7 + 3 + 7 + 3으로 구하면 돼.」","mis":"M5-1-u6-X17"},{"t":"하은 — 「(7 + 3) × 2로 구해도 같아.」","mis":"M5-1-u6-X17"}],"explanation":["직사각형의 변은 네 개예요.","가로와 세로를 한 번씩만 더하면 두 변의 길이뿐이에요.","서윤은 두 변만 더해 잘못 말했어요 — 둘레는 (7 + 3) × 2 = 20이에요."],"variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 5 cm인 직사각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「가로와 세로를 더한 14 cm가 둘레야.」","correct":true,"mis_target":"M5-1-u6-X03"},{"t":"라온 — 「9 + 5 + 9 + 5로 구하면 돼.」","mis":"M5-1-u6-X17"},{"t":"예준 — 「(9 + 5) × 2로 구해도 같아.」","mis":"M5-1-u6-X17"}],"explanation":["직사각형의 변은 네 개예요.","가로와 세로를 한 번씩만 더하면 두 변의 길이뿐이에요.","지민은 두 변만 더해 잘못 말했어요 — 둘레는 (9 + 5) × 2 = 28이에요."]},{"stem":"가로 8 cm, 세로 6 cm인 직사각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤아 — 「가로와 세로를 더한 14 cm가 둘레야.」","correct":true,"mis_target":"M5-1-u6-X03"},{"t":"시우 — 「8 + 6 + 8 + 6으로 구하면 돼.」","mis":"M5-1-u6-X17"},{"t":"나린 — 「(8 + 6) × 2로 구해도 같아.」","mis":"M5-1-u6-X17"}],"explanation":["직사각형의 변은 네 개예요.","가로와 세로를 한 번씩만 더하면 두 변의 길이뿐이에요.","윤아는 두 변만 더해 잘못 말했어요 — 둘레는 (8 + 6) × 2 = 28이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_challenge#2','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C1',2,'mc','auto','둘레가 모두 20 cm인 직사각형들이에요. 넓이가 가장 넓은 것은 어느 것인가요?',ARRAY['M5-1-u6-X02']::text[],true,'{"seq":2,"concept":"M5-1-u6-C1","difficulty":2,"kind":"mc","stem":"둘레가 모두 20 cm인 직사각형들이에요. 넓이가 가장 넓은 것은 어느 것인가요?","options":[{"t":"가로 5 cm · 세로 5 cm","correct":true},{"t":"가로 6 cm · 세로 4 cm","mis":"M5-1-u6-X02"},{"t":"가로 9 cm · 세로 1 cm","mis":"M5-1-u6-X02"},{"t":"가로 7 cm · 세로 3 cm","mis":"M5-1-u6-X02"}],"explanation":["네 직사각형은 모두 가로 + 세로 = 10이라 둘레가 20 cm예요.","넓이는 6 × 4 = 24, 9 × 1 = 9, 7 × 3 = 21, 5 × 5 = 25예요.","둘레가 같아도 넓이는 달라요 — 가장 넓은 것은 가로 5 cm · 세로 5 cm예요."],"variant_rule":{"alt":[{"stem":"둘레가 모두 20 cm인 직사각형들이에요. 넓이가 가장 좁은 것은 어느 것인가요?","options":[{"t":"가로 9 cm · 세로 1 cm","correct":true},{"t":"가로 6 cm · 세로 4 cm","mis":"M5-1-u6-X02"},{"t":"가로 7 cm · 세로 3 cm","mis":"M5-1-u6-X02"},{"t":"가로 5 cm · 세로 5 cm","mis":"M5-1-u6-X02"}],"explanation":["네 직사각형은 모두 가로 + 세로 = 10이라 둘레가 20 cm예요.","넓이는 6 × 4 = 24, 9 × 1 = 9, 7 × 3 = 21, 5 × 5 = 25예요.","둘레가 같아도 넓이는 달라요 — 가장 좁은 것은 가로 9 cm · 세로 1 cm예요."]},{"stem":"둘레가 모두 24 cm인 직사각형들이에요. 넓이가 가장 넓은 것은 어느 것인가요?","options":[{"t":"가로 6 cm · 세로 6 cm","correct":true},{"t":"가로 7 cm · 세로 5 cm","mis":"M5-1-u6-X02"},{"t":"가로 11 cm · 세로 1 cm","mis":"M5-1-u6-X02"},{"t":"가로 9 cm · 세로 3 cm","mis":"M5-1-u6-X02"}],"explanation":["네 직사각형은 모두 가로 + 세로 = 12라 둘레가 24 cm예요.","넓이는 7 × 5 = 35, 11 × 1 = 11, 9 × 3 = 27, 6 × 6 = 36이에요.","둘레가 같아도 넓이는 달라요 — 가장 넓은 것은 가로 6 cm · 세로 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_challenge#3','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C1',3,'sa','auto','둘레가 20 cm인 직사각형의 가로가 9 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":3,"concept":"M5-1-u6-C1","difficulty":3,"kind":"sa","stem":"둘레가 20 cm인 직사각형의 가로가 9 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?","answer":["9"],"explanation":["가로 + 세로 = 20 ÷ 2 = 10이에요.","세로 = 10 − 9 = 1이에요.","넓이는 9 × 1 = 9 — 9 cm²예요."],"mis":"M5-1-u6-X01","variant_rule":{"alt":[{"stem":"둘레가 24 cm인 직사각형의 가로가 10 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?","answer":["20"],"explanation":["가로 + 세로 = 24 ÷ 2 = 12예요.","세로 = 12 − 10 = 2예요.","넓이는 10 × 2 = 20 — 20 cm²예요."]},{"stem":"둘레가 18 cm인 직사각형의 가로가 7 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?","answer":["14"],"explanation":["가로 + 세로 = 18 ÷ 2 = 9예요.","세로 = 9 − 7 = 2예요.","넓이는 7 × 2 = 14 — 14 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_challenge#4','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C2',3,'sa','auto','가로가 세로보다 4 cm 더 긴 직사각형의 둘레가 32 cm예요. 세로는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C2","difficulty":3,"kind":"sa","stem":"가로가 세로보다 4 cm 더 긴 직사각형의 둘레가 32 cm예요. 세로는 몇 cm인가요?","answer":["6"],"explanation":["가로 + 세로 = 32 ÷ 2 = 16이에요.","세로를 □라 하면 □ + □ + 4 = 16이라 □ + □ = 12예요.","□ = 12 ÷ 2 = 6 — 세로는 6 cm, 가로는 10 cm예요."],"mis":"M5-1-u6-X03","variant_rule":{"alt":[{"stem":"가로가 세로보다 2 cm 더 긴 직사각형의 둘레가 28 cm예요. 세로는 몇 cm인가요?","answer":["6"],"explanation":["가로 + 세로 = 28 ÷ 2 = 14예요.","세로를 □라 하면 □ + □ + 2 = 14라 □ + □ = 12예요.","□ = 12 ÷ 2 = 6 — 세로는 6 cm, 가로는 8 cm예요."]},{"stem":"가로가 세로보다 6 cm 더 긴 직사각형의 둘레가 40 cm예요. 세로는 몇 cm인가요?","answer":["7"],"explanation":["가로 + 세로 = 40 ÷ 2 = 20이에요.","세로를 □라 하면 □ + □ + 6 = 20이라 □ + □ = 14예요.","□ = 14 ÷ 2 = 7 — 세로는 7 cm, 가로는 13 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_challenge#5','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C2',3,'mc','auto','가로 8 cm, 세로 5 cm인 직사각형 카드 2장을 가로로 겹치지 않게 나란히 이어 붙여 큰 직사각형을 만들었어요. 큰 직사각형의 둘레는 몇 cm인가요?',ARRAY['M5-1-u6-X15','M5-1-u6-X16','M5-1-u6-X03']::text[],true,'{"seq":5,"concept":"M5-1-u6-C2","difficulty":3,"kind":"mc","stem":"가로 8 cm, 세로 5 cm인 직사각형 카드 2장을 가로로 겹치지 않게 나란히 이어 붙여 큰 직사각형을 만들었어요. 큰 직사각형의 둘레는 몇 cm인가요?","options":[{"t":"42 cm","correct":true},{"t":"52 cm","mis":"M5-1-u6-X15"},{"t":"26 cm","mis":"M5-1-u6-X16"},{"t":"21 cm","mis":"M5-1-u6-X03"}],"explanation":["이어 붙이면 큰 직사각형의 가로는 8 × 2 = 16, 세로는 5예요.","맞붙은 변은 안쪽으로 들어가 가장자리가 아니에요.","(16 + 5) × 2 = 42 — 둘레는 42 cm예요."],"variant_rule":{"alt":[{"stem":"가로 6 cm, 세로 4 cm인 직사각형 카드 3장을 가로로 겹치지 않게 나란히 이어 붙여 큰 직사각형을 만들었어요. 큰 직사각형의 둘레는 몇 cm인가요?","options":[{"t":"44 cm","correct":true},{"t":"60 cm","mis":"M5-1-u6-X15"},{"t":"20 cm","mis":"M5-1-u6-X16"},{"t":"22 cm","mis":"M5-1-u6-X03"}],"explanation":["이어 붙이면 큰 직사각형의 가로는 6 × 3 = 18, 세로는 4예요.","맞붙은 변은 안쪽으로 들어가 가장자리가 아니에요.","(18 + 4) × 2 = 44 — 둘레는 44 cm예요."]},{"stem":"가로 5 cm, 세로 3 cm인 직사각형 카드 2장을 가로로 겹치지 않게 나란히 이어 붙여 큰 직사각형을 만들었어요. 큰 직사각형의 둘레는 몇 cm인가요?","options":[{"t":"26 cm","correct":true},{"t":"32 cm","mis":"M5-1-u6-X15"},{"t":"16 cm","mis":"M5-1-u6-X16"},{"t":"13 cm","mis":"M5-1-u6-X03"}],"explanation":["이어 붙이면 큰 직사각형의 가로는 5 × 2 = 10, 세로는 3이에요.","맞붙은 변은 안쪽으로 들어가 가장자리가 아니에요.","(10 + 3) × 2 = 26 — 둘레는 26 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_challenge#6','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C1',3,'mc','auto','모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮와 ㉯ 가운데 넓이가 더 넓은 것은 어느 것인가요?',ARRAY['M5-1-u6-X02','M5-1-u6-X06']::text[],true,'{"seq":6,"concept":"M5-1-u6-C1","difficulty":3,"kind":"mc","stem":"모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮와 ㉯ 가운데 넓이가 더 넓은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-1-u6-X02"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X06"}],"explanation":["㉮는 가로 6칸, 세로 2칸 — 둘레 (6 + 2) × 2 = 16, 넓이 6 × 2 = 12예요.","㉯는 가로 4칸, 세로 4칸 — 둘레 (4 + 4) × 2 = 16, 넓이 4 × 4 = 16이에요.","둘레는 16 cm로 같지만 넓이는 달라요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[15,15],[105,15],[105,45],[15,45]]],"show":[]},{"w":120,"h":90,"grid":15,"poly":[[[15,15],[75,15],[75,75],[15,75]]],"show":[]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮와 ㉯ 가운데 넓이가 더 넓은 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-1-u6-X02"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X06"}],"explanation":["㉮는 가로 7칸, 세로 1칸 — 둘레 (7 + 1) × 2 = 16, 넓이 7 × 1 = 7이에요.","㉯는 가로 5칸, 세로 3칸 — 둘레 (5 + 3) × 2 = 16, 넓이 5 × 3 = 15예요.","둘레는 16 cm로 같지만 넓이는 달라요."],"asset":{"type":"geo","items":[{"w":135,"h":75,"grid":15,"poly":[[[15,15],[120,15],[120,30],[15,30]]],"show":[]},{"w":135,"h":75,"grid":15,"poly":[[[15,15],[90,15],[90,60],[15,60]]],"show":[]}]}},{"stem":"모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮와 ㉯의 둘레를 견주면 어떠한가요?","options":[{"t":"두 둘레가 같다","correct":true},{"t":"㉮의 둘레가 더 길다","mis":"M5-1-u6-X02"},{"t":"㉯의 둘레가 더 길다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X06"}],"explanation":["㉮는 가로 6칸, 세로 3칸 — 둘레 (6 + 3) × 2 = 18, 넓이 6 × 3 = 18이에요.","㉯는 가로 5칸, 세로 4칸 — 둘레 (5 + 4) × 2 = 18, 넓이 5 × 4 = 20이에요.","둘레는 18 cm로 같지만 넓이는 달라요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[15,15],[105,15],[105,60],[15,60]]],"show":[]},{"w":120,"h":90,"grid":15,"poly":[[[15,15],[90,15],[90,75],[15,75]]],"show":[]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_challenge#7','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C2',3,'sa','auto','둘레가 30 cm인 평행사변형의 밑변이 9 cm예요. 이웃한 변은 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C2","difficulty":3,"kind":"sa","stem":"둘레가 30 cm인 평행사변형의 밑변이 9 cm예요. 이웃한 변은 몇 cm인가요?","answer":["6"],"explanation":["평행사변형의 둘레는 (밑변 + 이웃한 변) × 2예요.","밑변 + 이웃한 변 = 30 ÷ 2 = 15예요.","이웃한 변 = 15 − 9 = 6 — 6 cm예요."],"mis":"M5-1-u6-X03","variant_rule":{"alt":[{"stem":"둘레가 36 cm인 평행사변형의 밑변이 11 cm예요. 이웃한 변은 몇 cm인가요?","answer":["7"],"explanation":["평행사변형의 둘레는 (밑변 + 이웃한 변) × 2예요.","밑변 + 이웃한 변 = 36 ÷ 2 = 18이에요.","이웃한 변 = 18 − 11 = 7 — 7 cm예요."]},{"stem":"둘레가 44 cm인 평행사변형의 밑변이 15 cm예요. 이웃한 변은 몇 cm인가요?","answer":["7"],"explanation":["평행사변형의 둘레는 (밑변 + 이웃한 변) × 2예요.","밑변 + 이웃한 변 = 44 ÷ 2 = 22예요.","이웃한 변 = 22 − 15 = 7 — 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_challenge#8','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C1',4,'sa','auto','둘레가 20 cm인 직사각형 가운데 가로와 세로가 자연수(cm)인 것을 모두 생각해요. 넓이가 가장 넓은 것의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C1","difficulty":4,"kind":"sa","stem":"둘레가 20 cm인 직사각형 가운데 가로와 세로가 자연수(cm)인 것을 모두 생각해요. 넓이가 가장 넓은 것의 넓이는 몇 cm²인가요?","answer":["25"],"explanation":["가로 + 세로 = 20 ÷ 2 = 10이에요.","가로와 세로가 가까울수록 넓이가 넓어져요 — 1 × 9 = 9, 2 × 8 = 16, 3 × 7 = 21, 5 × 5 = 25예요.","가장 넓은 것은 가로와 세로가 같은 5 × 5 = 25 — 25 cm²예요."],"mis":"M5-1-u6-X02","variant_rule":{"alt":[{"stem":"둘레가 24 cm인 직사각형 가운데 가로와 세로가 자연수(cm)인 것을 모두 생각해요. 넓이가 가장 넓은 것의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["가로 + 세로 = 24 ÷ 2 = 12예요.","가로와 세로가 가까울수록 넓이가 넓어져요 — 1 × 11 = 11, 2 × 10 = 20, 3 × 9 = 27, 6 × 6 = 36이에요.","가장 넓은 것은 가로와 세로가 같은 6 × 6 = 36 — 36 cm²예요."]},{"stem":"둘레가 28 cm인 직사각형 가운데 가로와 세로가 자연수(cm)인 것을 모두 생각해요. 넓이가 가장 넓은 것의 넓이는 몇 cm²인가요?","answer":["49"],"explanation":["가로 + 세로 = 28 ÷ 2 = 14예요.","가로와 세로가 가까울수록 넓이가 넓어져요 — 1 × 13 = 13, 2 × 12 = 24, 3 × 11 = 33, 7 × 7 = 49예요.","가장 넓은 것은 가로와 세로가 같은 7 × 7 = 49 — 49 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_challenge#9','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C2',4,'mc','auto','한 변이 6 cm인 정사각형 색종이를 똑같은 직사각형 두 개가 되도록 반으로 잘랐어요. 잘라 낸 직사각형 한 개의 둘레는 몇 cm인가요?',ARRAY['M5-1-u6-X15','M5-1-u6-X03']::text[],true,'{"seq":9,"concept":"M5-1-u6-C2","difficulty":4,"kind":"mc","stem":"한 변이 6 cm인 정사각형 색종이를 똑같은 직사각형 두 개가 되도록 반으로 잘랐어요. 잘라 낸 직사각형 한 개의 둘레는 몇 cm인가요?","options":[{"t":"18 cm","correct":true},{"t":"12 cm","mis":"M5-1-u6-X15"},{"t":"24 cm","mis":"M5-1-u6-X15"},{"t":"15 cm","mis":"M5-1-u6-X03"}],"explanation":["반으로 자른 직사각형은 가로 6 cm, 세로 3 cm예요.","자른 자리도 새 변이 되어 둘레에 들어가요.","(6 + 3) × 2 = 18 — 둘레는 18 cm예요. 정사각형 둘레 24의 절반이 아니에요."],"variant_rule":{"alt":[{"stem":"한 변이 8 cm인 정사각형 색종이를 똑같은 직사각형 두 개가 되도록 반으로 잘랐어요. 잘라 낸 직사각형 한 개의 둘레는 몇 cm인가요?","options":[{"t":"24 cm","correct":true},{"t":"16 cm","mis":"M5-1-u6-X15"},{"t":"32 cm","mis":"M5-1-u6-X15"},{"t":"20 cm","mis":"M5-1-u6-X03"}],"explanation":["반으로 자른 직사각형은 가로 8 cm, 세로 4 cm예요.","자른 자리도 새 변이 되어 둘레에 들어가요.","(8 + 4) × 2 = 24 — 둘레는 24 cm예요. 정사각형 둘레 32의 절반이 아니에요."]},{"stem":"한 변이 10 cm인 정사각형 색종이를 똑같은 직사각형 두 개가 되도록 반으로 잘랐어요. 잘라 낸 직사각형 한 개의 둘레는 몇 cm인가요?","options":[{"t":"30 cm","correct":true},{"t":"20 cm","mis":"M5-1-u6-X15"},{"t":"40 cm","mis":"M5-1-u6-X15"},{"t":"25 cm","mis":"M5-1-u6-X03"}],"explanation":["반으로 자른 직사각형은 가로 10 cm, 세로 5 cm예요.","자른 자리도 새 변이 되어 둘레에 들어가요.","(10 + 5) × 2 = 30 — 둘레는 30 cm예요. 정사각형 둘레 40의 절반이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L02_challenge#10','math',5,1,'u6','L02','g5_1_math_u6_L02_challenge','lesson_challenge','M5-1-u6-C1',4,'essay','teacher','둘레가 같은 두 직사각형은 넓이도 같을까요? 예를 들어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u6-C1","difficulty":4,"kind":"essay","stem":"둘레가 같은 두 직사각형은 넓이도 같을까요? 예를 들어 설명하세요.","answer_guide":{"answer":"예: 같지 않을 수 있다. 가로 5 cm, 세로 5 cm인 정사각형과 가로 9 cm, 세로 1 cm인 직사각형은 둘레가 모두 20 cm이지만 넓이는 25 cm²와 9 cm²로 다르다. 둘레는 가장자리의 길이이고 넓이는 덮은 칸의 수라 서로 다른 양이기 때문이다.","scoring_points":["같지 않을 수 있다고 답했는가","둘레가 같고 넓이가 다른 두 직사각형의 예를 바르게 셈했는가","둘레는 길이, 넓이는 칸의 수라 다른 양이라고 설명했는가"]},"explanation":["둘레가 20 cm인 직사각형은 5 × 5, 9 × 1처럼 여러 가지예요.","넓이는 5 × 5 = 25, 9 × 1 = 9로 달라요.","둘레가 같아도 넓이는 다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_basic#1','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',1,'mc','auto','마름모의 둘레를 구하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-1-u6-X13','M5-1-u6-X03']::text[],true,'{"seq":1,"concept":"M5-1-u6-C3","difficulty":1,"kind":"mc","stem":"마름모의 둘레를 구하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 변의 길이를 4배 한다","correct":true},{"t":"두 대각선의 길이를 더한다","mis":"M5-1-u6-X13"},{"t":"한 변의 길이를 2배 한다","mis":"M5-1-u6-X03"},{"t":"두 대각선의 길이를 곱한다","mis":"M5-1-u6-X13"}],"explanation":["마름모는 네 변의 길이가 모두 같아요.","같은 길이를 네 번 더하는 것은 4배 하는 것과 같아요.","그래서 마름모의 둘레는 (한 변의 길이) × 4예요."],"variant_rule":{"alt":[{"stem":"정다각형의 둘레를 구하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"(한 변의 길이) × (변의 수)","correct":true},{"t":"(한 변의 길이) × 4","mis":"M5-1-u6-X05"},{"t":"(변의 수) ÷ (한 변의 길이)","mis":"M5-1-u6-X14"},{"t":"(한 변의 길이) + (변의 수)","mis":"M5-1-u6-X16"}],"explanation":["정다각형은 변의 길이가 모두 같아요.","같은 길이를 변의 수만큼 거듭 더하는 것이 곱셈이에요.","그래서 (한 변의 길이) × (변의 수)예요."]},{"stem":"정오각형의 둘레를 구하는 식으로 알맞은 것은 어느 것인가요? (한 변 6 cm)","options":[{"t":"6 × 5","correct":true},{"t":"6 × 4","mis":"M5-1-u6-X05"},{"t":"6 × 6","mis":"M5-1-u6-X05"},{"t":"6 + 5","mis":"M5-1-u6-X16"}],"explanation":["정오각형은 변이 5개이고 길이가 모두 같아요.","6 cm를 5번 더하는 것과 같아요.","그래서 6 × 5 = 30으로 구해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_basic#2','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',1,'sa','auto','한 변의 길이가 7 cm인 마름모 모양 타일이 있어요. 타일의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C3","difficulty":1,"kind":"sa","stem":"한 변의 길이가 7 cm인 마름모 모양 타일이 있어요. 타일의 둘레는 몇 cm인가요?","answer":["28"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","7 + 7 + 7 + 7 = 28이에요.","7 × 4 = 28 — 둘레는 28 cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 9 cm인 마름모 모양 타일이 있어요. 타일의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","9 + 9 + 9 + 9 = 36이에요.","9 × 4 = 36 — 둘레는 36 cm예요."]},{"stem":"한 변의 길이가 12 m인 마름모 모양 화단이 있어요. 화단의 둘레는 몇 m인가요?","answer":["48"],"explanation":["마름모는 네 변의 길이가 모두 같아요.","12 + 12 + 12 + 12 = 48이에요.","12 × 4 = 48 — 둘레는 48 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_basic#3','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',1,'mc','auto','한 변의 길이가 4 cm인 정오각형의 둘레는 몇 cm인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X16']::text[],true,'{"seq":3,"concept":"M5-1-u6-C3","difficulty":1,"kind":"mc","stem":"한 변의 길이가 4 cm인 정오각형의 둘레는 몇 cm인가요?","options":[{"t":"20 cm","correct":true},{"t":"16 cm","mis":"M5-1-u6-X05"},{"t":"24 cm","mis":"M5-1-u6-X05"},{"t":"9 cm","mis":"M5-1-u6-X16"}],"explanation":["정오각형은 변이 5개이고 길이가 모두 같아요.","4 cm를 5번 더하는 것과 같아요.","4 × 5 = 20 — 둘레는 20 cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 5 cm인 정육각형의 둘레는 몇 cm인가요?","options":[{"t":"30 cm","correct":true},{"t":"20 cm","mis":"M5-1-u6-X05"},{"t":"35 cm","mis":"M5-1-u6-X05"},{"t":"25 cm","mis":"M5-1-u6-X05"}],"explanation":["정육각형은 변이 6개이고 길이가 모두 같아요.","5 cm를 6번 더하는 것과 같아요.","5 × 6 = 30 — 둘레는 30 cm예요."]},{"stem":"한 변의 길이가 8 cm인 정삼각형의 둘레는 몇 cm인가요?","options":[{"t":"24 cm","correct":true},{"t":"32 cm","mis":"M5-1-u6-X05"},{"t":"16 cm","mis":"M5-1-u6-X05"},{"t":"11 cm","mis":"M5-1-u6-X16"}],"explanation":["정삼각형은 변이 3개이고 길이가 모두 같아요.","8 cm를 3번 더하는 것과 같아요.","8 × 3 = 24 — 둘레는 24 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_basic#4','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',1,'sa','auto','한 변의 길이가 12 m인 정칠각형의 둘레는 몇 m인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C3","difficulty":1,"kind":"sa","stem":"한 변의 길이가 12 m인 정칠각형의 둘레는 몇 m인가요?","answer":["84"],"explanation":["정칠각형은 변이 7개예요.","변의 길이가 모두 12 m로 같아요.","12 × 7 = 84 — 둘레는 84 m예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 9 cm인 정팔각형의 둘레는 몇 cm인가요?","answer":["72"],"explanation":["정팔각형은 변이 8개예요.","변의 길이가 모두 9 cm로 같아요.","9 × 8 = 72 — 둘레는 72 cm예요."]},{"stem":"한 변의 길이가 6 cm인 정구각형의 둘레는 몇 cm인가요?","answer":["54"],"explanation":["정구각형은 변이 9개예요.","변의 길이가 모두 6 cm로 같아요.","6 × 9 = 54 — 둘레는 54 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_basic#5','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',2,'sa','auto','둘레가 45 cm인 정구각형의 한 변의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M5-1-u6-C3","difficulty":2,"kind":"sa","stem":"둘레가 45 cm인 정구각형의 한 변의 길이는 몇 cm인가요?","answer":["5"],"explanation":["정구각형의 둘레는 (한 변의 길이) × 9예요.","□ × 9 = 45니 □ = 45 ÷ 9예요.","45 ÷ 9 = 5 — 한 변은 5 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"둘레가 42 cm인 정육각형의 한 변의 길이는 몇 cm인가요?","answer":["7"],"explanation":["정육각형의 둘레는 (한 변의 길이) × 6이에요.","□ × 6 = 42니 □ = 42 ÷ 6이에요.","42 ÷ 6 = 7 — 한 변은 7 cm예요."]},{"stem":"둘레가 96 cm인 정팔각형의 한 변의 길이는 몇 cm인가요?","answer":["12"],"explanation":["정팔각형의 둘레는 (한 변의 길이) × 8이에요.","□ × 8 = 96이니 □ = 96 ÷ 8이에요.","96 ÷ 8 = 12 — 한 변은 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_basic#6','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',2,'mc','auto','둘레가 가장 짧은 것은 어느 것인가요? ㉠ 한 변 7 cm인 마름모 ㉡ 한 변 5 cm인 정육각형 ㉢ 한 변 3 cm인 정팔각형',ARRAY['M5-1-u6-X05','M5-1-u6-X17','M5-1-u6-X16']::text[],true,'{"seq":6,"concept":"M5-1-u6-C3","difficulty":2,"kind":"mc","stem":"둘레가 가장 짧은 것은 어느 것인가요? ㉠ 한 변 7 cm인 마름모 ㉡ 한 변 5 cm인 정육각형 ㉢ 한 변 3 cm인 정팔각형","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-1-u6-X05"},{"t":"㉡","mis":"M5-1-u6-X17"},{"t":"세 둘레가 같다","mis":"M5-1-u6-X16"}],"explanation":["둘레는 (한 변의 길이) × (변의 수)예요.","㉠ 7 × 4 = 28, ㉡ 5 × 6 = 30, ㉢ 3 × 8 = 24예요.","가장 짧은 것은 ㉢이에요."],"variant_rule":{"alt":[{"stem":"둘레가 가장 긴 것은 어느 것인가요? ㉠ 한 변 9 cm인 정삼각형 ㉡ 한 변 6 cm인 정오각형 ㉢ 한 변 8 cm인 정사각형","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-1-u6-X17"},{"t":"㉡","mis":"M5-1-u6-X05"},{"t":"세 둘레가 같다","mis":"M5-1-u6-X16"}],"explanation":["둘레는 (한 변의 길이) × (변의 수)예요.","㉠ 9 × 3 = 27, ㉡ 6 × 5 = 30, ㉢ 8 × 4 = 32예요.","가장 긴 것은 ㉢이에요."]},{"stem":"둘레가 가장 짧은 것은 어느 것인가요? ㉠ 한 변 4 cm인 정육각형 ㉡ 한 변 5 cm인 마름모 ㉢ 한 변 3 cm인 정오각형","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-1-u6-X17"},{"t":"㉡","mis":"M5-1-u6-X05"},{"t":"세 둘레가 같다","mis":"M5-1-u6-X16"}],"explanation":["둘레는 (한 변의 길이) × (변의 수)예요.","㉠ 4 × 6 = 24, ㉡ 5 × 4 = 20, ㉢ 3 × 5 = 15예요.","가장 짧은 것은 ㉢이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_basic#7','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',2,'ox','auto','마름모의 둘레는 두 대각선의 길이를 더해서 구해요.',ARRAY['M5-1-u6-X13']::text[],true,'{"seq":7,"concept":"M5-1-u6-C3","difficulty":2,"kind":"ox","stem":"마름모의 둘레는 두 대각선의 길이를 더해서 구해요.","answer":"X","reason_options":[{"t":"마름모의 둘레는 가장자리인 네 변의 길이의 합이므로","correct":true},{"t":"대각선이 마름모를 가로지르는 가장 긴 선이므로","mis":"M5-1-u6-X13"}],"mis":"M5-1-u6-X13","explanation":["둘레는 가장자리를 따라 잰 길이예요.","대각선은 안쪽을 가로지르는 선이라 가장자리가 아니에요.","마름모의 둘레는 (한 변의 길이) × 4예요."],"variant_rule":{"alt":[{"stem":"변의 수가 많은 정다각형일수록 둘레가 반드시 길어요.","answer":"X","reason_options":[{"t":"한 변 3 cm 정팔각형(24 cm)가 한 변 7 cm 마름모(28 cm)보다 짧으므로","correct":true},{"t":"변이 많으면 늘 더 많이 더하므로","mis":"M5-1-u6-X05"}],"explanation":["둘레는 변의 수뿐 아니라 한 변의 길이에도 달려 있어요.","정팔각형 3 × 8 = 24, 마름모 7 × 4 = 28이에요.","변이 더 많은 정팔각형이 오히려 짧아요."]},{"stem":"한 변의 길이와 변의 수만 알면 정다각형의 둘레를 구할 수 있어요.","answer":"O","reason_options":[{"t":"변의 길이가 모두 같아 (한 변) × (변의 수)로 구하므로","correct":true},{"t":"정다각형은 변이 언제나 4개이므로","mis":"M5-1-u6-X05"}],"explanation":["정다각형은 모든 변의 길이가 같아요.","그래서 한 변을 변의 수만큼 거듭 더하면 둘레예요.","(한 변의 길이) × (변의 수)로 구해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_basic#8','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',2,'match','auto','한 변의 길이가 6 cm인 도형과 그 둘레를 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C3","difficulty":2,"kind":"match","stem":"한 변의 길이가 6 cm인 도형과 그 둘레를 알맞게 이으세요.","pairs":[{"l":"정삼각형","r":"18 cm"},{"l":"마름모","r":"24 cm"},{"l":"정육각형","r":"36 cm"}],"mis":"M5-1-u6-X05","explanation":["정삼각형은 변이 3개 — 6 × 3 = 18이에요.","마름모는 변이 4개 — 6 × 4 = 24예요.","정육각형은 변이 6개 — 6 × 6 = 36이에요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 5 cm인 도형과 그 둘레를 알맞게 이으세요.","pairs":[{"l":"정오각형","r":"25 cm"},{"l":"정팔각형","r":"40 cm"},{"l":"정사각형","r":"20 cm"}],"explanation":["정오각형은 변이 5개 — 5 × 5 = 25예요.","정팔각형은 변이 8개 — 5 × 8 = 40이에요.","정사각형은 변이 4개 — 5 × 4 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_basic#9','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',2,'mc','auto','길이가 60 cm인 철사를 남김없이 모두 써서 정오각형 하나를 만들었어요. 한 변의 길이는 몇 cm인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X14']::text[],true,'{"seq":9,"concept":"M5-1-u6-C3","difficulty":2,"kind":"mc","stem":"길이가 60 cm인 철사를 남김없이 모두 써서 정오각형 하나를 만들었어요. 한 변의 길이는 몇 cm인가요?","options":[{"t":"12 cm","correct":true},{"t":"15 cm","mis":"M5-1-u6-X05"},{"t":"10 cm","mis":"M5-1-u6-X05"},{"t":"55 cm","mis":"M5-1-u6-X14"}],"explanation":["철사의 길이가 곧 정오각형의 둘레예요.","정오각형은 변이 5개라 □ × 5 = 60이에요.","60 ÷ 5 = 12 — 한 변은 12 cm예요."],"variant_rule":{"alt":[{"stem":"길이가 54 cm인 철사를 남김없이 모두 써서 정육각형 하나를 만들었어요. 한 변의 길이는 몇 cm인가요?","options":[{"t":"9 cm","correct":true},{"t":"48 cm","mis":"M5-1-u6-X14"},{"t":"324 cm","mis":"M5-1-u6-X14"},{"t":"10 cm","mis":"M5-1-u6-X16"}],"explanation":["철사의 길이가 곧 정육각형의 둘레예요.","정육각형은 변이 6개라 □ × 6 = 54예요.","54 ÷ 6 = 9 — 한 변은 9 cm예요."]},{"stem":"길이가 56 cm인 철사를 남김없이 모두 써서 정팔각형 하나를 만들었어요. 한 변의 길이는 몇 cm인가요?","options":[{"t":"7 cm","correct":true},{"t":"14 cm","mis":"M5-1-u6-X05"},{"t":"8 cm","mis":"M5-1-u6-X05"},{"t":"48 cm","mis":"M5-1-u6-X14"}],"explanation":["철사의 길이가 곧 정팔각형의 둘레예요.","정팔각형은 변이 8개라 □ × 8 = 56이에요.","56 ÷ 8 = 7 — 한 변은 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_basic#10','math',5,1,'u6','L03','g5_1_math_u6_L03_basic','lesson_basic','M5-1-u6-C3',3,'sa','auto','한 변이 12 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 2 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?','{}'::text[],true,'{"seq":10,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"한 변이 12 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 2 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?","answer":["32"],"explanation":["양쪽에서 2 m씩 들어가니 한 변은 12 − 2 − 2 = 8이에요.","경기 지역도 정사각형이라 네 변이 같아요.","8 × 4 = 32 — 둘레는 32 m예요."],"variant_rule":{"alt":[{"stem":"한 변이 15 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 2 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?","answer":["44"],"explanation":["양쪽에서 2 m씩 들어가니 한 변은 15 − 2 − 2 = 11이에요.","경기 지역도 정사각형이라 네 변이 같아요.","11 × 4 = 44 — 둘레는 44 m예요."]},{"stem":"한 변이 13 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 3 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?","answer":["28"],"explanation":["양쪽에서 3 m씩 들어가니 한 변은 13 − 3 − 3 = 7이에요.","경기 지역도 정사각형이라 네 변이 같아요.","7 × 4 = 28 — 둘레는 28 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_challenge#1','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',2,'error','auto','한 변의 길이가 3 cm인 정팔각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X17']::text[],true,'{"seq":1,"concept":"M5-1-u6-C3","difficulty":2,"kind":"error","stem":"한 변의 길이가 3 cm인 정팔각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「한 변을 4배 한 12 cm야.」","correct":true,"mis_target":"M5-1-u6-X05"},{"t":"도현 — 「변이 8개라 3 × 8로 구해.」","mis":"M5-1-u6-X17"},{"t":"하은 — 「3 cm를 8번 더한 것과 같아.」","mis":"M5-1-u6-X17"}],"explanation":["정팔각형은 변이 8개예요.","4를 곱하는 것은 변이 4개인 마름모·정사각형일 때예요.","서윤은 변의 수를 잘못 써서 틀렸어요 — 둘레는 3 × 8 = 24예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 5 cm인 정육각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「한 변을 4배 한 20 cm야.」","correct":true,"mis_target":"M5-1-u6-X05"},{"t":"라온 — 「변이 6개라 5 × 6으로 구해.」","mis":"M5-1-u6-X17"},{"t":"예준 — 「5 cm를 6번 더한 것과 같아.」","mis":"M5-1-u6-X17"}],"explanation":["정육각형은 변이 6개예요.","4를 곱하는 것은 변이 4개인 마름모·정사각형일 때예요.","지민은 변의 수를 잘못 써서 틀렸어요 — 둘레는 5 × 6 = 30이에요."]},{"stem":"한 변의 길이가 7 cm인 정오각형의 둘레를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤아 — 「한 변을 4배 한 28 cm야.」","correct":true,"mis_target":"M5-1-u6-X05"},{"t":"시우 — 「변이 5개라 7 × 5로 구해.」","mis":"M5-1-u6-X17"},{"t":"나린 — 「7 cm를 5번 더한 것과 같아.」","mis":"M5-1-u6-X17"}],"explanation":["정오각형은 변이 5개예요.","4를 곱하는 것은 변이 4개인 마름모·정사각형일 때예요.","윤아는 변의 수를 잘못 써서 틀렸어요 — 둘레는 7 × 5 = 35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_challenge#2','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',2,'sa','auto','한 변이 8 cm인 정삼각형과 둘레가 같은 정사각형이 있어요. 정사각형의 한 변의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C3","difficulty":2,"kind":"sa","stem":"한 변이 8 cm인 정삼각형과 둘레가 같은 정사각형이 있어요. 정사각형의 한 변의 길이는 몇 cm인가요?","answer":["6"],"explanation":["정삼각형의 둘레는 8 × 3 = 24예요.","정사각형의 둘레도 24 cm니 □ × 4 = 24예요.","24 ÷ 4 = 6 — 한 변은 6 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"한 변이 4 cm인 정오각형과 둘레가 같은 정사각형이 있어요. 정사각형의 한 변의 길이는 몇 cm인가요?","answer":["5"],"explanation":["정오각형의 둘레는 4 × 5 = 20이에요.","정사각형의 둘레도 20 cm니 □ × 4 = 20이에요.","20 ÷ 4 = 5 — 한 변은 5 cm예요."]},{"stem":"한 변이 4 cm인 정육각형과 둘레가 같은 정팔각형이 있어요. 정팔각형의 한 변의 길이는 몇 cm인가요?","answer":["3"],"explanation":["정육각형의 둘레는 4 × 6 = 24예요.","정팔각형의 둘레도 24 cm니 □ × 8 = 24예요.","24 ÷ 8 = 3 — 한 변은 3 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_challenge#3','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',3,'mc','auto','둘레에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X13']::text[],true,'{"seq":3,"concept":"M5-1-u6-C3","difficulty":3,"kind":"mc","stem":"둘레에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"정다각형은 한 변의 길이와 변의 수만 알면 둘레를 구할 수 있다","correct":true},{"t":"정다각형의 둘레는 언제나 한 변의 4배다","mis":"M5-1-u6-X05"},{"t":"마름모의 둘레는 대각선의 길이로 구한다","mis":"M5-1-u6-X13"},{"t":"변의 수가 많을수록 둘레가 반드시 길다","mis":"M5-1-u6-X05"}],"explanation":["정다각형은 변의 길이가 모두 같아요.","그래서 (한 변) × (변의 수)면 둘레예요.","4배는 변이 4개일 때만, 대각선은 둘레와 상관없어요."],"variant_rule":{"alt":[{"stem":"둘레에 대한 설명으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"정육각형의 둘레는 한 변의 길이를 4배 하여 구한다","correct":true},{"t":"마름모의 둘레는 한 변의 길이를 4배 하여 구한다","mis":"M5-1-u6-X17"},{"t":"정삼각형의 둘레는 한 변의 길이를 3배 하여 구한다","mis":"M5-1-u6-X17"},{"t":"정팔각형의 둘레는 한 변의 길이를 8배 하여 구한다","mis":"M5-1-u6-X17"}],"explanation":["정육각형은 변이 6개예요.","그래서 한 변을 6배 해야 둘레예요.","옳지 않은 것은 「정육각형 … 4배」예요."]},{"stem":"한 변의 길이가 같은 마름모와 정사각형의 둘레를 견주면 어떠한가요?","options":[{"t":"두 둘레가 같다","correct":true},{"t":"마름모의 둘레가 더 길다","mis":"M5-1-u6-X13"},{"t":"정사각형의 둘레가 더 길다","mis":"M5-1-u6-X13"},{"t":"알 수 없다","mis":"M5-1-u6-X13"}],"explanation":["마름모도 정사각형도 네 변의 길이가 모두 같아요.","둘 다 (한 변) × 4예요.","한 변이 같으면 둘레도 같아요 — 모양이 달라도요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_challenge#4','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',3,'sa','auto','한 변이 9 cm인 정사각형과 둘레가 같은 정육각형이 있어요. 정육각형의 한 변의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"한 변이 9 cm인 정사각형과 둘레가 같은 정육각형이 있어요. 정육각형의 한 변의 길이는 몇 cm인가요?","answer":["6"],"explanation":["정사각형의 둘레는 9 × 4 = 36이에요.","정육각형의 둘레도 36 cm니 □ × 6 = 36이에요.","36 ÷ 6 = 6 — 한 변은 6 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"한 변이 6 cm인 정오각형과 둘레가 같은 정삼각형이 있어요. 정삼각형의 한 변의 길이는 몇 cm인가요?","answer":["10"],"explanation":["정오각형의 둘레는 6 × 5 = 30이에요.","정삼각형의 둘레도 30 cm니 □ × 3 = 30이에요.","30 ÷ 3 = 10 — 한 변은 10 cm예요."]},{"stem":"한 변이 3 cm인 정팔각형과 둘레가 같은 정사각형이 있어요. 정사각형의 한 변의 길이는 몇 cm인가요?","answer":["6"],"explanation":["정팔각형의 둘레는 3 × 8 = 24예요.","정사각형의 둘레도 24 cm니 □ × 4 = 24예요.","24 ÷ 4 = 6 — 한 변은 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_challenge#5','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',3,'sa','auto','한 변이 5 cm인 정삼각형 4개를 겹치지 않게 변끼리 맞붙여 한 줄로 이었어요. 만든 도형의 둘레는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"한 변이 5 cm인 정삼각형 4개를 겹치지 않게 변끼리 맞붙여 한 줄로 이었어요. 만든 도형의 둘레는 몇 cm인가요?","answer":["30"],"explanation":["정삼각형 4개의 변은 모두 3 × 4 = 12개예요.","맞붙은 곳 3군데에서 변이 2개씩 안쪽으로 들어가 가장자리 변은 12 − 6 = 6개예요.","5 × 6 = 30 — 둘레는 30 cm예요."],"mis":"M5-1-u6-X15","variant_rule":{"alt":[{"stem":"한 변이 7 cm인 정삼각형 3개를 겹치지 않게 변끼리 맞붙여 한 줄로 이었어요. 만든 도형의 둘레는 몇 cm인가요?","answer":["35"],"explanation":["정삼각형 3개의 변은 모두 3 × 3 = 9개예요.","맞붙은 곳 2군데에서 변이 2개씩 안쪽으로 들어가 가장자리 변은 9 − 4 = 5개예요.","7 × 5 = 35 — 둘레는 35 cm예요."]},{"stem":"한 변이 9 cm인 정삼각형 2개를 겹치지 않게 변끼리 맞붙여 한 줄로 이었어요. 만든 도형의 둘레는 몇 cm인가요?","answer":["36"],"explanation":["정삼각형 2개의 변은 모두 3 × 2 = 6개예요.","맞붙은 곳 1군데에서 변이 2개씩 안쪽으로 들어가 가장자리 변은 6 − 2 = 4개예요.","9 × 4 = 36 — 둘레는 36 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_challenge#6','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',3,'sa','auto','한 변의 길이가 8 cm로 같은 정오각형과 정사각형이 있어요. 두 도형의 둘레의 차는 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"한 변의 길이가 8 cm로 같은 정오각형과 정사각형이 있어요. 두 도형의 둘레의 차는 몇 cm인가요?","answer":["8"],"explanation":["정오각형의 둘레는 8 × 5 = 40이에요.","정사각형의 둘레는 8 × 4 = 32예요.","40 − 32 = 8 — 차는 8 cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 7 cm로 같은 정육각형과 정삼각형이 있어요. 두 도형의 둘레의 차는 몇 cm인가요?","answer":["21"],"explanation":["정육각형의 둘레는 7 × 6 = 42예요.","정삼각형의 둘레는 7 × 3 = 21이에요.","42 − 21 = 21 — 차는 21 cm예요."]},{"stem":"한 변의 길이가 9 cm로 같은 정팔각형과 정육각형이 있어요. 두 도형의 둘레의 차는 몇 cm인가요?","answer":["18"],"explanation":["정팔각형의 둘레는 9 × 8 = 72예요.","정육각형의 둘레는 9 × 6 = 54예요.","72 − 54 = 18 — 차는 18 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_challenge#7','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',3,'sa','auto','한 변이 14 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 3 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"한 변이 14 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 3 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?","answer":["32"],"explanation":["양쪽에서 3 m씩 들어가니 한 변은 14 − 3 − 3 = 8이에요.","경기 지역도 정사각형이라 네 변이 같아요.","8 × 4 = 32 — 둘레는 32 m예요."],"variant_rule":{"alt":[{"stem":"한 변이 16 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 2 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?","answer":["48"],"explanation":["양쪽에서 2 m씩 들어가니 한 변은 16 − 2 − 2 = 12예요.","경기 지역도 정사각형이라 네 변이 같아요.","12 × 4 = 48 — 둘레는 48 m예요."]},{"stem":"한 변이 11 m인 정사각형 태권도 경기장이에요. 가장자리에서 안쪽으로 1 m씩 들어간 정사각형 경기 지역의 둘레는 몇 m인가요?","answer":["36"],"explanation":["양쪽에서 1 m씩 들어가니 한 변은 11 − 1 − 1 = 9예요.","경기 지역도 정사각형이라 네 변이 같아요.","9 × 4 = 36 — 둘레는 36 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_challenge#8','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',4,'sa','auto','길이가 100 cm인 철사로 한 변이 7 cm인 정육각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C3","difficulty":4,"kind":"sa","stem":"길이가 100 cm인 철사로 한 변이 7 cm인 정육각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?","answer":["58"],"explanation":["정육각형을 만드는 데 쓴 철사는 둘레만큼이에요.","7 × 6 = 42예요.","100 − 42 = 58 — 남은 철사는 58 cm예요."],"variant_rule":{"alt":[{"stem":"길이가 100 cm인 철사로 한 변이 9 cm인 정팔각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?","answer":["28"],"explanation":["정팔각형을 만드는 데 쓴 철사는 둘레만큼이에요.","9 × 8 = 72예요.","100 − 72 = 28 — 남은 철사는 28 cm예요."]},{"stem":"길이가 90 cm인 철사로 한 변이 13 cm인 정오각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?","answer":["25"],"explanation":["정오각형을 만드는 데 쓴 철사는 둘레만큼이에요.","13 × 5 = 65예요.","90 − 65 = 25 — 남은 철사는 25 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_challenge#9','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',4,'mc','auto','둘레가 72 cm이고 한 변의 길이가 8 cm인 정다각형이 있어요. 이 정다각형의 이름은 무엇인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X14']::text[],true,'{"seq":9,"concept":"M5-1-u6-C3","difficulty":4,"kind":"mc","stem":"둘레가 72 cm이고 한 변의 길이가 8 cm인 정다각형이 있어요. 이 정다각형의 이름은 무엇인가요?","options":[{"t":"정구각형","correct":true},{"t":"정팔각형","mis":"M5-1-u6-X05"},{"t":"정십각형","mis":"M5-1-u6-X05"},{"t":"정십일각형","mis":"M5-1-u6-X14"}],"explanation":["정다각형의 둘레는 (한 변의 길이) × (변의 수)예요.","8 × □ = 72니 □ = 72 ÷ 8 = 9예요.","변이 9개인 정다각형은 정구각형이에요."],"variant_rule":{"alt":[{"stem":"둘레가 60 cm이고 한 변의 길이가 12 cm인 정다각형이 있어요. 이 정다각형의 이름은 무엇인가요?","options":[{"t":"정오각형","correct":true},{"t":"정사각형","mis":"M5-1-u6-X05"},{"t":"정육각형","mis":"M5-1-u6-X05"},{"t":"정칠각형","mis":"M5-1-u6-X14"}],"explanation":["정다각형의 둘레는 (한 변의 길이) × (변의 수)예요.","12 × □ = 60이니 □ = 60 ÷ 12 = 5예요.","변이 5개인 정다각형은 정오각형이에요."]},{"stem":"둘레가 84 cm이고 한 변의 길이가 12 cm인 정다각형이 있어요. 이 정다각형의 이름은 무엇인가요?","options":[{"t":"정칠각형","correct":true},{"t":"정육각형","mis":"M5-1-u6-X05"},{"t":"정팔각형","mis":"M5-1-u6-X05"},{"t":"정구각형","mis":"M5-1-u6-X14"}],"explanation":["정다각형의 둘레는 (한 변의 길이) × (변의 수)예요.","12 × □ = 84니 □ = 84 ÷ 12 = 7이에요.","변이 7개인 정다각형은 정칠각형이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L03_challenge#10','math',5,1,'u6','L03','g5_1_math_u6_L03_challenge','lesson_challenge','M5-1-u6-C3',4,'essay','teacher','정다각형의 둘레를 (한 변의 길이) × (변의 수)로 구할 수 있는 까닭을 설명하고, 한 변이 4 cm인 정육각형의 둘레를 구하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u6-C3","difficulty":4,"kind":"essay","stem":"정다각형의 둘레를 (한 변의 길이) × (변의 수)로 구할 수 있는 까닭을 설명하고, 한 변이 4 cm인 정육각형의 둘레를 구하세요.","answer_guide":{"answer":"예: 정다각형은 모든 변의 길이가 같으므로 한 변의 길이를 변의 수만큼 거듭 더하면 둘레가 되고, 같은 수를 거듭 더하는 것은 곱셈이다. 정육각형은 변이 6개이므로 4 × 6 = 24, 둘레는 24 cm이다.","scoring_points":["모든 변의 길이가 같다고 썼는가","거듭 더하기가 곱셈이라고 설명했는가","정육각형의 둘레 24 cm를 바르게 구했는가"]},"explanation":["정다각형은 변의 길이가 모두 같아요.","같은 길이를 변의 수만큼 더하는 것이 곱셈이에요.","정육각형: 4 × 6 = 24 — 둘레는 24 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_basic#1','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C4',1,'mc','auto','1 cm²는 어떤 넓이인가요?',ARRAY['M5-1-u6-X06']::text[],true,'{"seq":1,"concept":"M5-1-u6-C4","difficulty":1,"kind":"mc","stem":"1 cm²는 어떤 넓이인가요?","options":[{"t":"한 변의 길이가 1 cm인 정사각형의 넓이","correct":true},{"t":"둘레가 1 cm인 도형의 넓이","mis":"M5-1-u6-X06"},{"t":"가로가 1 cm인 직사각형의 넓이","mis":"M5-1-u6-X06"},{"t":"네 변의 길이의 합이 4 cm인 아무 도형의 넓이","mis":"M5-1-u6-X06"}],"explanation":["넓이를 견주려면 모두가 같은 크기의 칸을 써야 해요.","그래서 한 변이 1 cm인 정사각형 한 칸의 넓이를 1 cm²로 약속했어요.","둘레나 가로 하나만으로는 칸의 크기가 정해지지 않아요."],"variant_rule":{"alt":[{"stem":"1 cm²를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 제곱센티미터","correct":true},{"t":"1 센티미터","mis":"M5-1-u6-X01"},{"t":"1 센티미터 이","mis":"M5-1-u6-X06"},{"t":"1 사각센티미터","mis":"M5-1-u6-X06"}],"explanation":["cm² 오른쪽 위의 작은 2는 제곱이라고 읽어요.","1 cm²는 1 제곱센티미터라고 읽어요.","1 센티미터는 길이의 단위예요."]},{"stem":"넓이를 1 cm² 같은 표준 단위로 재는 까닭은 무엇인가요?","options":[{"t":"같은 크기의 칸으로 세어야 넓이를 비교할 수 있어서","correct":true},{"t":"칸의 수가 적어져서","mis":"M5-1-u6-X06"},{"t":"둘레를 쉽게 구할 수 있어서","mis":"M5-1-u6-X01"},{"t":"도형의 모양을 알 수 있어서","mis":"M5-1-u6-X06"}],"explanation":["친구는 큰 칸, 나는 작은 칸으로 세면 칸의 수를 견주어도 넓이를 견준 게 아니에요.","모두가 같은 칸을 써야 칸의 수로 넓이를 비교할 수 있어요.","그래서 한 변 1 cm 정사각형을 1 cm²로 약속했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_basic#2','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C4',1,'sa','auto','도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 4칸씩 3줄이었어요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C4","difficulty":1,"kind":"sa","stem":"도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 4칸씩 3줄이었어요. 넓이는 몇 cm²인가요?","answer":["12"],"explanation":["한 줄에 4칸, 그런 줄이 3줄이에요.","4 × 3 = 12 — 칸은 모두 12개예요.","한 칸이 1 cm²니 넓이는 12 cm²예요."],"variant_rule":{"alt":[{"stem":"도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 5칸씩 3줄이었어요. 넓이는 몇 cm²인가요?","answer":["15"],"explanation":["한 줄에 5칸, 그런 줄이 3줄이에요.","5 × 3 = 15 — 칸은 모두 15개예요.","한 칸이 1 cm²니 넓이는 15 cm²예요."]},{"stem":"도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 6칸씩 4줄이었어요. 넓이는 몇 cm²인가요?","answer":["24"],"explanation":["한 줄에 6칸, 그런 줄이 4줄이에요.","6 × 4 = 24 — 칸은 모두 24개예요.","한 칸이 1 cm²니 넓이는 24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_basic#3','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C5',1,'mc','auto','직사각형의 넓이를 구하는 식은 어느 것인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X10']::text[],true,'{"seq":3,"concept":"M5-1-u6-C5","difficulty":1,"kind":"mc","stem":"직사각형의 넓이를 구하는 식은 어느 것인가요?","options":[{"t":"(가로) × (세로)","correct":true},{"t":"(가로 + 세로) × 2","mis":"M5-1-u6-X01"},{"t":"(가로) + (세로)","mis":"M5-1-u6-X01"},{"t":"(가로) × (세로) ÷ 2","mis":"M5-1-u6-X10"}],"explanation":["한 줄에 가로만큼 칸이 있어요.","그런 줄이 세로만큼 있어요.","그래서 직사각형의 넓이는 (가로) × (세로)예요."],"variant_rule":{"alt":[{"stem":"정사각형의 넓이를 구하는 식은 어느 것인가요?","options":[{"t":"(한 변) × (한 변)","correct":true},{"t":"(한 변) × 4","mis":"M5-1-u6-X01"},{"t":"(한 변) × 2","mis":"M5-1-u6-X07"},{"t":"(한 변) + (한 변)","mis":"M5-1-u6-X01"}],"explanation":["정사각형은 가로와 세로가 같은 직사각형이에요.","(가로) × (세로)에서 가로와 세로가 모두 한 변이에요.","그래서 (한 변) × (한 변)이에요 — (한 변) × 4는 둘레예요."]},{"stem":"넓이를 구하는 식으로 잘못된 것은 어느 것인가요?","options":[{"t":"직사각형: (가로 + 세로) × 2","correct":true},{"t":"직사각형: (가로) × (세로)","mis":"M5-1-u6-X17"},{"t":"정사각형: (한 변) × (한 변)","mis":"M5-1-u6-X17"},{"t":"직사각형: (세로) × (가로)","mis":"M5-1-u6-X17"}],"explanation":["(가로 + 세로) × 2는 가장자리 길이, 곧 둘레의 식이에요.","넓이는 칸의 수라 곱해서 구해요.","곱하는 차례를 바꾼 (세로) × (가로)도 같은 넓이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_basic#4','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C5',1,'sa','auto','가로 8 cm, 세로 5 cm인 직사각형 카드의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C5","difficulty":1,"kind":"sa","stem":"가로 8 cm, 세로 5 cm인 직사각형 카드의 넓이는 몇 cm²인가요?","answer":["40"],"explanation":["한 줄에 8칸씩 5줄이라고 생각해요.","넓이는 (가로) × (세로)예요.","8 × 5 = 40 — 넓이는 40 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 9 cm, 세로 6 cm인 직사각형 카드의 넓이는 몇 cm²인가요?","answer":["54"],"explanation":["한 줄에 9칸씩 6줄이라고 생각해요.","넓이는 (가로) × (세로)예요.","9 × 6 = 54 — 넓이는 54 cm²예요."]},{"stem":"가로 12 m, 세로 4 m인 직사각형 꽃밭의 넓이는 몇 m²인가요?","answer":["48"],"explanation":["한 줄에 12칸씩 4줄이라고 생각해요.","넓이는 (가로) × (세로)예요.","12 × 4 = 48 — 넓이는 48 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_basic#5','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C4',2,'sa','auto','모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":5,"concept":"M5-1-u6-C4","difficulty":2,"kind":"sa","stem":"모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["14"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 14칸이에요.","한 칸이 1 cm²니 넓이는 14 cm²예요."],"asset":{"type":"geo","items":[{"w":105,"h":105,"grid":15,"poly":[[[15,15],[75,15],[75,45],[45,45],[45,90],[15,90]]],"show":[]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["18"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 18칸이에요.","한 칸이 1 cm²니 넓이는 18 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,15],[105,15],[105,45],[60,45],[60,75],[15,75]]],"show":[]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["14"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 14칸이에요.","한 칸이 1 cm²니 넓이는 14 cm²예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[15,15],[45,15],[45,45],[90,45],[90,75],[15,75]]],"show":[]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_basic#6','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C5',2,'mc','auto','한 변의 길이가 6 cm인 정사각형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X07','M5-1-u6-X16']::text[],true,'{"seq":6,"concept":"M5-1-u6-C5","difficulty":2,"kind":"mc","stem":"한 변의 길이가 6 cm인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"36 cm²","correct":true},{"t":"24 cm²","mis":"M5-1-u6-X01"},{"t":"12 cm²","mis":"M5-1-u6-X07"},{"t":"30 cm²","mis":"M5-1-u6-X16"}],"explanation":["정사각형은 가로와 세로가 같아요.","넓이는 (한 변) × (한 변)이에요.","6 × 6 = 36 — 넓이는 36 cm²예요. 6 × 4 = 24는 둘레예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 9 cm인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"81 cm²","correct":true},{"t":"36 cm²","mis":"M5-1-u6-X01"},{"t":"18 cm²","mis":"M5-1-u6-X07"},{"t":"45 cm²","mis":"M5-1-u6-X16"}],"explanation":["정사각형은 가로와 세로가 같아요.","넓이는 (한 변) × (한 변)이에요.","9 × 9 = 81 — 넓이는 81 cm²예요. 9 × 4 = 36은 둘레예요."]},{"stem":"한 변의 길이가 7 cm인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"49 cm²","correct":true},{"t":"28 cm²","mis":"M5-1-u6-X01"},{"t":"14 cm²","mis":"M5-1-u6-X07"},{"t":"35 cm²","mis":"M5-1-u6-X16"}],"explanation":["정사각형은 가로와 세로가 같아요.","넓이는 (한 변) × (한 변)이에요.","7 × 7 = 49 — 넓이는 49 cm²예요. 7 × 4 = 28은 둘레예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_basic#7','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C5',2,'sa','auto','넓이가 48 cm²인 직사각형의 가로가 8 cm예요. 세로는 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C5","difficulty":2,"kind":"sa","stem":"넓이가 48 cm²인 직사각형의 가로가 8 cm예요. 세로는 몇 cm인가요?","answer":["6"],"explanation":["(가로) × (세로) = (넓이)예요.","8 × □ = 48이니 □ = 48 ÷ 8이에요.","48 ÷ 8 = 6 — 세로는 6 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"넓이가 63 cm²인 직사각형의 가로가 9 cm예요. 세로는 몇 cm인가요?","answer":["7"],"explanation":["(가로) × (세로) = (넓이)예요.","9 × □ = 63이니 □ = 63 ÷ 9예요.","63 ÷ 9 = 7 — 세로는 7 cm예요."]},{"stem":"넓이가 72 cm²인 직사각형의 가로가 8 cm예요. 세로는 몇 cm인가요?","answer":["9"],"explanation":["(가로) × (세로) = (넓이)예요.","8 × □ = 72니 □ = 72 ÷ 8이에요.","72 ÷ 8 = 9 — 세로는 9 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_basic#8','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C5',2,'mc','auto','넓이가 더 넓은 것은 어느 것인가요? ㉠ 가로 12 cm, 세로 5 cm인 직사각형 ㉡ 한 변이 8 cm인 정사각형',ARRAY['M5-1-u6-X16','M5-1-u6-X02','M5-1-u6-X06']::text[],true,'{"seq":8,"concept":"M5-1-u6-C5","difficulty":2,"kind":"mc","stem":"넓이가 더 넓은 것은 어느 것인가요? ㉠ 가로 12 cm, 세로 5 cm인 직사각형 ㉡ 한 변이 8 cm인 정사각형","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-1-u6-X16"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X06"}],"explanation":["㉠의 넓이는 12 × 5 = 60이에요.","㉡의 넓이는 8 × 8 = 64예요.","㉡의 넓이가 더 넓어요."],"variant_rule":{"alt":[{"stem":"넓이가 더 넓은 것은 어느 것인가요? ㉠ 가로 9 cm, 세로 4 cm인 직사각형 ㉡ 한 변이 7 cm인 정사각형","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-1-u6-X16"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X06"}],"explanation":["㉠의 넓이는 9 × 4 = 36이에요.","㉡의 넓이는 7 × 7 = 49예요.","㉡의 넓이가 더 넓어요."]},{"stem":"넓이가 더 넓은 것은 어느 것인가요? ㉠ 가로 10 cm, 세로 7 cm인 직사각형 ㉡ 한 변이 8 cm인 정사각형","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M5-1-u6-X16"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X06"}],"explanation":["㉠의 넓이는 10 × 7 = 70이에요.","㉡의 넓이는 8 × 8 = 64예요.","㉠의 넓이가 더 넓어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_basic#9','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C5',2,'ox','auto','직사각형의 넓이는 (가로 + 세로) × 2로 구해요.',ARRAY['M5-1-u6-X01']::text[],true,'{"seq":9,"concept":"M5-1-u6-C5","difficulty":2,"kind":"ox","stem":"직사각형의 넓이는 (가로 + 세로) × 2로 구해요.","answer":"X","reason_options":[{"t":"(가로 + 세로) × 2는 둘레의 식이고 넓이는 (가로) × (세로)이므로","correct":true},{"t":"가로와 세로를 모두 쓰는 식이므로","mis":"M5-1-u6-X01"}],"mis":"M5-1-u6-X01","explanation":["둘레는 가장자리의 길이라 더해서 구해요.","넓이는 칸의 수라 한 줄의 칸 수 × 줄의 수로 곱해요.","그래서 넓이는 (가로) × (세로)예요."],"variant_rule":{"alt":[{"stem":"정사각형의 넓이는 한 변의 길이의 2배예요.","answer":"X","reason_options":[{"t":"넓이는 (한 변) × (한 변)이라 한 변 6 cm면 36 cm²이므로","correct":true},{"t":"정사각형은 가로와 세로 두 변이 있으므로","mis":"M5-1-u6-X07"}],"explanation":["정사각형의 넓이는 (한 변) × (한 변)이에요.","한 변이 6 cm면 6 × 6 = 36이에요.","6 × 2 = 12는 넓이가 아니에요."]},{"stem":"가로와 세로를 바꾸어 곱해도 직사각형의 넓이는 같아요.","answer":"O","reason_options":[{"t":"한 줄 칸 수와 줄 수를 바꾸어 세어도 칸의 수는 그대로이므로","correct":true},{"t":"가로와 세로는 늘 같은 길이이므로","mis":"M5-1-u6-X01"}],"explanation":["가로 8 cm, 세로 5 cm면 8칸씩 5줄이에요.","돌려 보면 5칸씩 8줄이에요.","8 × 5 = 40, 5 × 8 = 40 — 넓이는 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_basic#10','math',5,1,'u6','L05','g5_1_math_u6_L05_basic','lesson_basic','M5-1-u6-C4',3,'mc','auto','모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮, ㉯에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M5-1-u6-X02','M5-1-u6-X16']::text[],true,'{"seq":10,"concept":"M5-1-u6-C4","difficulty":3,"kind":"mc","stem":"모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮, ㉯에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"㉮는 둘레가 더 길지만 넓이는 더 좁다","correct":true},{"t":"㉮가 둘레도 넓이도 더 크다","mis":"M5-1-u6-X02"},{"t":"㉯가 둘레도 넓이도 더 크다","mis":"M5-1-u6-X02"},{"t":"두 도형은 넓이가 같다","mis":"M5-1-u6-X16"}],"explanation":["㉮는 둘레 (9 + 1) × 2 = 20, 넓이 9 × 1 = 9예요.","㉯는 둘레 (5 + 3) × 2 = 16, 넓이 5 × 3 = 15예요.","둘레가 긴 ㉮가 오히려 좁아요 — 둘레와 넓이는 다른 양이에요."],"asset":{"type":"geo","items":[{"w":165,"h":75,"grid":15,"poly":[[[15,15],[150,15],[150,30],[15,30]]],"show":[]},{"w":165,"h":75,"grid":15,"poly":[[[15,15],[90,15],[90,60],[15,60]]],"show":[]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮, ㉯에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"㉮는 둘레가 더 길지만 넓이는 더 좁다","correct":true},{"t":"㉮가 둘레도 넓이도 더 크다","mis":"M5-1-u6-X02"},{"t":"㉯가 둘레도 넓이도 더 크다","mis":"M5-1-u6-X02"},{"t":"두 도형은 넓이가 같다","mis":"M5-1-u6-X16"}],"explanation":["㉮는 둘레 (8 + 1) × 2 = 18, 넓이 8 × 1 = 8이에요.","㉯는 둘레 (4 + 3) × 2 = 14, 넓이 4 × 3 = 12예요.","둘레가 긴 ㉮가 오히려 좁아요 — 둘레와 넓이는 다른 양이에요."],"asset":{"type":"geo","items":[{"w":150,"h":75,"grid":15,"poly":[[[15,15],[135,15],[135,30],[15,30]]],"show":[]},{"w":150,"h":75,"grid":15,"poly":[[[15,15],[75,15],[75,60],[15,60]]],"show":[]}]}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 한 변이 1 cm인 정사각형이에요. 두 직사각형 ㉮, ㉯에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"㉮는 둘레가 더 길지만 넓이는 더 좁다","correct":true},{"t":"㉮가 둘레도 넓이도 더 크다","mis":"M5-1-u6-X02"},{"t":"㉯가 둘레도 넓이도 더 크다","mis":"M5-1-u6-X02"},{"t":"두 도형은 넓이가 같다","mis":"M5-1-u6-X16"}],"explanation":["㉮는 둘레 (7 + 1) × 2 = 16, 넓이 7 × 1 = 7이에요.","㉯는 둘레 (4 + 3) × 2 = 14, 넓이 4 × 3 = 12예요.","둘레가 긴 ㉮가 오히려 좁아요 — 둘레와 넓이는 다른 양이에요."],"asset":{"type":"geo","items":[{"w":135,"h":75,"grid":15,"poly":[[[15,15],[120,15],[120,30],[15,30]]],"show":[]},{"w":135,"h":75,"grid":15,"poly":[[[15,15],[75,15],[75,60],[15,60]]],"show":[]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_challenge#1','math',5,1,'u6','L05','g5_1_math_u6_L05_challenge','lesson_challenge','M5-1-u6-C5',2,'error','auto','가로 8 cm, 세로 5 cm인 직사각형의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X17']::text[],true,'{"seq":1,"concept":"M5-1-u6-C5","difficulty":2,"kind":"error","stem":"가로 8 cm, 세로 5 cm인 직사각형의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「(8 + 5) × 2 = 26이니 넓이는 26 cm²야.」","correct":true,"mis_target":"M5-1-u6-X01"},{"t":"도현 — 「한 줄에 8칸씩 5줄이니 40칸이야.」","mis":"M5-1-u6-X17"},{"t":"하은 — 「5 × 8로 구해도 넓이는 같아.」","mis":"M5-1-u6-X17"}],"explanation":["(8 + 5) × 2 = 26은 가장자리 길이인 둘레예요.","넓이는 칸의 수라 8 × 5 = 40이에요.","서윤은 둘레의 식으로 넓이를 구해 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 6 cm인 직사각형의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「(7 + 6) × 2 = 26이니 넓이는 26 cm²야.」","correct":true,"mis_target":"M5-1-u6-X01"},{"t":"라온 — 「한 줄에 7칸씩 6줄이니 42칸이야.」","mis":"M5-1-u6-X17"},{"t":"예준 — 「6 × 7로 구해도 넓이는 같아.」","mis":"M5-1-u6-X17"}],"explanation":["(7 + 6) × 2 = 26은 가장자리 길이인 둘레예요.","넓이는 칸의 수라 7 × 6 = 42예요.","지민은 둘레의 식으로 넓이를 구해 잘못 말했어요."]},{"stem":"가로 9 cm, 세로 4 cm인 직사각형의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤아 — 「(9 + 4) × 2 = 26이니 넓이는 26 cm²야.」","correct":true,"mis_target":"M5-1-u6-X01"},{"t":"시우 — 「한 줄에 9칸씩 4줄이니 36칸이야.」","mis":"M5-1-u6-X17"},{"t":"나린 — 「4 × 9로 구해도 넓이는 같아.」","mis":"M5-1-u6-X17"}],"explanation":["(9 + 4) × 2 = 26은 가장자리 길이인 둘레예요.","넓이는 칸의 수라 9 × 4 = 36이에요.","윤아는 둘레의 식으로 넓이를 구해 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_challenge#2','math',5,1,'u6','L05','g5_1_math_u6_L05_challenge','lesson_challenge','M5-1-u6-C5',2,'sa','auto','넓이가 64 cm²인 정사각형의 한 변의 길이는 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C5","difficulty":2,"kind":"sa","stem":"넓이가 64 cm²인 정사각형의 한 변의 길이는 몇 cm인가요?","answer":["8"],"explanation":["정사각형의 넓이는 (한 변) × (한 변)이에요.","같은 수를 두 번 곱해 64가 되는 수를 찾아요.","8 × 8 = 64 — 한 변은 8 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"넓이가 81 cm²인 정사각형의 한 변의 길이는 몇 cm인가요?","answer":["9"],"explanation":["정사각형의 넓이는 (한 변) × (한 변)이에요.","같은 수를 두 번 곱해 81이 되는 수를 찾아요.","9 × 9 = 81 — 한 변은 9 cm예요."]},{"stem":"넓이가 49 cm²인 정사각형의 한 변의 길이는 몇 cm인가요?","answer":["7"],"explanation":["정사각형의 넓이는 (한 변) × (한 변)이에요.","같은 수를 두 번 곱해 49가 되는 수를 찾아요.","7 × 7 = 49 — 한 변은 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_challenge#3','math',5,1,'u6','L05','g5_1_math_u6_L05_challenge','lesson_challenge','M5-1-u6-C5',3,'sa','auto','가로 40 cm, 세로 30 cm인 게시판을 가로 8 cm, 세로 5 cm인 카드로 겹치지 않게 빈틈없이 채우려고 해요. 카드는 몇 장 필요한가요? (카드는 돌리지 않아요)','{}'::text[],true,'{"seq":3,"concept":"M5-1-u6-C5","difficulty":3,"kind":"sa","stem":"가로 40 cm, 세로 30 cm인 게시판을 가로 8 cm, 세로 5 cm인 카드로 겹치지 않게 빈틈없이 채우려고 해요. 카드는 몇 장 필요한가요? (카드는 돌리지 않아요)","answer":["30"],"explanation":["가로로는 40 ÷ 8 = 5장이 들어가요.","세로로는 30 ÷ 5 = 6줄이 들어가요.","5 × 6 = 30 — 카드는 30장이에요. 넓이로 셈해도 1200 ÷ 40 = 30이에요."],"variant_rule":{"alt":[{"stem":"가로 48 cm, 세로 30 cm인 게시판을 가로 8 cm, 세로 6 cm인 카드로 겹치지 않게 빈틈없이 채우려고 해요. 카드는 몇 장 필요한가요? (카드는 돌리지 않아요)","answer":["30"],"explanation":["가로로는 48 ÷ 8 = 6장이 들어가요.","세로로는 30 ÷ 6 = 5줄이 들어가요.","6 × 5 = 30 — 카드는 30장이에요. 넓이로 셈해도 1440 ÷ 48 = 30이에요."]},{"stem":"가로 60 cm, 세로 20 cm인 게시판을 가로 6 cm, 세로 5 cm인 카드로 겹치지 않게 빈틈없이 채우려고 해요. 카드는 몇 장 필요한가요? (카드는 돌리지 않아요)","answer":["40"],"explanation":["가로로는 60 ÷ 6 = 10장이 들어가요.","세로로는 20 ÷ 5 = 4줄이 들어가요.","10 × 4 = 40 — 카드는 40장이에요. 넓이로 셈해도 1200 ÷ 30 = 40이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_challenge#4','math',5,1,'u6','L05','g5_1_math_u6_L05_challenge','lesson_challenge','M5-1-u6-C5',3,'sa','auto','둘레가 24 cm인 정사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C5","difficulty":3,"kind":"sa","stem":"둘레가 24 cm인 정사각형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["정사각형은 네 변이 같으니 한 변은 24 ÷ 4 = 6이에요.","넓이는 (한 변) × (한 변)이에요.","6 × 6 = 36 — 넓이는 36 cm²예요."],"mis":"M5-1-u6-X01","variant_rule":{"alt":[{"stem":"둘레가 28 cm인 정사각형의 넓이는 몇 cm²인가요?","answer":["49"],"explanation":["정사각형은 네 변이 같으니 한 변은 28 ÷ 4 = 7이에요.","넓이는 (한 변) × (한 변)이에요.","7 × 7 = 49 — 넓이는 49 cm²예요."]},{"stem":"둘레가 36 cm인 정사각형의 넓이는 몇 cm²인가요?","answer":["81"],"explanation":["정사각형은 네 변이 같으니 한 변은 36 ÷ 4 = 9예요.","넓이는 (한 변) × (한 변)이에요.","9 × 9 = 81 — 넓이는 81 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_challenge#5','math',5,1,'u6','L05','g5_1_math_u6_L05_challenge','lesson_challenge','M5-1-u6-C5',3,'mc','auto','직사각형의 가로와 세로를 모두 2배로 늘리면 넓이는 몇 배가 되나요?',ARRAY['M5-1-u6-X07','M5-1-u6-X16','M5-1-u6-X02']::text[],true,'{"seq":5,"concept":"M5-1-u6-C5","difficulty":3,"kind":"mc","stem":"직사각형의 가로와 세로를 모두 2배로 늘리면 넓이는 몇 배가 되나요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M5-1-u6-X07"},{"t":"8배","mis":"M5-1-u6-X16"},{"t":"그대로","mis":"M5-1-u6-X02"}],"explanation":["가로 3 cm, 세로 2 cm면 넓이는 3 × 2 = 6이에요.","2배로 늘리면 가로 6 cm, 세로 4 cm — 6 × 4 = 24예요.","24는 6의 4배예요 — 가로로 2배, 세로로 2배라 2 × 2 = 4배예요."],"variant_rule":{"alt":[{"stem":"직사각형의 가로만 2배로 늘리고 세로는 그대로 두면 넓이는 몇 배가 되나요?","options":[{"t":"2배","correct":true},{"t":"4배","mis":"M5-1-u6-X07"},{"t":"그대로","mis":"M5-1-u6-X02"},{"t":"3배","mis":"M5-1-u6-X16"}],"explanation":["가로 5 cm, 세로 3 cm면 넓이는 5 × 3 = 15예요.","가로만 2배면 10 × 3 = 30이에요.","30은 15의 2배예요 — 한 방향만 늘었어요."]},{"stem":"정사각형의 한 변을 3배로 늘리면 넓이는 몇 배가 되나요?","options":[{"t":"9배","correct":true},{"t":"3배","mis":"M5-1-u6-X07"},{"t":"6배","mis":"M5-1-u6-X07"},{"t":"12배","mis":"M5-1-u6-X01"}],"explanation":["한 변이 2 cm면 넓이는 2 × 2 = 4예요.","3배로 늘리면 한 변 6 cm — 6 × 6 = 36이에요.","36은 4의 9배예요 — 가로도 세로도 3배라 3 × 3 = 9배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_challenge#6','math',5,1,'u6','L05','g5_1_math_u6_L05_challenge','lesson_challenge','M5-1-u6-C4',3,'sa','auto','모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-1-u6-C4","difficulty":3,"kind":"sa","stem":"모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["26"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 26칸이에요.","한 칸이 1 cm²니 넓이는 26 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"grid":15,"poly":[[[15,15],[120,15],[120,90],[90,90],[90,45],[45,45],[45,90],[15,90]]],"show":[]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["29"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 29칸이에요.","한 칸이 1 cm²니 넓이는 29 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"grid":15,"poly":[[[15,15],[45,15],[45,45],[90,45],[90,15],[120,15],[120,90],[15,90]]],"show":[]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["27"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 27칸이에요.","한 칸이 1 cm²니 넓이는 27 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"grid":15,"poly":[[[30,15],[75,15],[75,45],[120,45],[120,90],[15,90],[15,45],[30,45]]],"show":[]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_challenge#7','math',5,1,'u6','L05','g5_1_math_u6_L05_challenge','lesson_challenge','M5-1-u6-C5',3,'mc','auto','넓이가 24 cm²인 직사각형 가운데 가로와 세로가 자연수(cm)인 것을 모두 생각해요. 둘레가 가장 긴 것의 둘레는 몇 cm인가요?',ARRAY['M5-1-u6-X02']::text[],true,'{"seq":7,"concept":"M5-1-u6-C5","difficulty":3,"kind":"mc","stem":"넓이가 24 cm²인 직사각형 가운데 가로와 세로가 자연수(cm)인 것을 모두 생각해요. 둘레가 가장 긴 것의 둘레는 몇 cm인가요?","options":[{"t":"50 cm","correct":true},{"t":"28 cm","mis":"M5-1-u6-X02"},{"t":"22 cm","mis":"M5-1-u6-X02"},{"t":"20 cm","mis":"M5-1-u6-X02"}],"explanation":["넓이가 24인 직사각형은 1 × 24, 2 × 12, 3 × 8, 4 × 6이에요.","둘레는 (1 + 24) × 2 = 50, (2 + 12) × 2 = 28, (3 + 8) × 2 = 22, (4 + 6) × 2 = 20이에요.","넓이가 같아도 둘레는 달라요 — 가장 긴 둘레는 50 cm예요."],"variant_rule":{"alt":[{"stem":"넓이가 36 cm²인 직사각형 가운데 가로와 세로가 자연수(cm)인 것을 모두 생각해요. 둘레가 가장 긴 것의 둘레는 몇 cm인가요?","options":[{"t":"74 cm","correct":true},{"t":"40 cm","mis":"M5-1-u6-X02"},{"t":"30 cm","mis":"M5-1-u6-X02"},{"t":"26 cm","mis":"M5-1-u6-X02"}],"explanation":["넓이가 36인 직사각형은 1 × 36, 2 × 18, 3 × 12, 4 × 9, 6 × 6이에요.","둘레는 (1 + 36) × 2 = 74, (2 + 18) × 2 = 40, (3 + 12) × 2 = 30, (4 + 9) × 2 = 26, (6 + 6) × 2 = 24예요.","넓이가 같아도 둘레는 달라요 — 가장 긴 둘레는 74 cm예요."]},{"stem":"넓이가 18 cm²인 직사각형 가운데 가로와 세로가 자연수(cm)인 것을 모두 생각해요. 둘레가 가장 긴 것의 둘레는 몇 cm인가요?","options":[{"t":"38 cm","correct":true},{"t":"22 cm","mis":"M5-1-u6-X02"},{"t":"18 cm","mis":"M5-1-u6-X02"},{"t":"36 cm","mis":"M5-1-u6-X01"}],"explanation":["넓이가 18인 직사각형은 1 × 18, 2 × 9, 3 × 6이에요.","둘레는 (1 + 18) × 2 = 38, (2 + 9) × 2 = 22, (3 + 6) × 2 = 18이에요.","넓이가 같아도 둘레는 달라요 — 가장 긴 둘레는 38 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_challenge#8','math',5,1,'u6','L05','g5_1_math_u6_L05_challenge','lesson_challenge','M5-1-u6-C5',4,'sa','auto','가로 15 cm, 세로 6 cm인 직사각형에서 가로를 3 cm 줄였어요. 넓이는 몇 cm² 줄어드나요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C5","difficulty":4,"kind":"sa","stem":"가로 15 cm, 세로 6 cm인 직사각형에서 가로를 3 cm 줄였어요. 넓이는 몇 cm² 줄어드나요?","answer":["18"],"explanation":["처음 넓이는 15 × 6 = 90이에요.","줄인 뒤 넓이는 12 × 6 = 72예요.","90 − 72 = 18 — 줄어든 넓이는 잘라 낸 3 × 6 부분과 같아요."],"variant_rule":{"alt":[{"stem":"가로 12 cm, 세로 7 cm인 직사각형에서 가로를 4 cm 줄였어요. 넓이는 몇 cm² 줄어드나요?","answer":["28"],"explanation":["처음 넓이는 12 × 7 = 84예요.","줄인 뒤 넓이는 8 × 7 = 56이에요.","84 − 56 = 28 — 줄어든 넓이는 잘라 낸 4 × 7 부분과 같아요."]},{"stem":"가로 14 cm, 세로 5 cm인 직사각형에서 가로를 6 cm 줄였어요. 넓이는 몇 cm² 줄어드나요?","answer":["30"],"explanation":["처음 넓이는 14 × 5 = 70이에요.","줄인 뒤 넓이는 8 × 5 = 40이에요.","70 − 40 = 30 — 줄어든 넓이는 잘라 낸 6 × 5 부분과 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_challenge#9','math',5,1,'u6','L05','g5_1_math_u6_L05_challenge','lesson_challenge','M5-1-u6-C5',4,'sa','auto','가로 10 cm, 세로 8 cm인 직사각형 종이의 한 귀퉁이에서 가로 4 cm, 세로 3 cm인 직사각형을 잘라 냈어요. 남은 종이의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":9,"concept":"M5-1-u6-C5","difficulty":4,"kind":"sa","stem":"가로 10 cm, 세로 8 cm인 직사각형 종이의 한 귀퉁이에서 가로 4 cm, 세로 3 cm인 직사각형을 잘라 냈어요. 남은 종이의 넓이는 몇 cm²인가요?","answer":["68"],"explanation":["처음 종이의 넓이는 10 × 8 = 80이에요.","잘라 낸 부분의 넓이는 4 × 3 = 12예요.","80 − 12 = 68 — 남은 넓이는 68 cm²예요."],"mis":"M5-1-u6-X15","variant_rule":{"alt":[{"stem":"가로 12 cm, 세로 7 cm인 직사각형 종이의 한 귀퉁이에서 가로 5 cm, 세로 2 cm인 직사각형을 잘라 냈어요. 남은 종이의 넓이는 몇 cm²인가요?","answer":["74"],"explanation":["처음 종이의 넓이는 12 × 7 = 84예요.","잘라 낸 부분의 넓이는 5 × 2 = 10이에요.","84 − 10 = 74 — 남은 넓이는 74 cm²예요."]},{"stem":"가로 9 cm, 세로 9 cm인 직사각형 종이의 한 귀퉁이에서 가로 3 cm, 세로 4 cm인 직사각형을 잘라 냈어요. 남은 종이의 넓이는 몇 cm²인가요?","answer":["69"],"explanation":["처음 종이의 넓이는 9 × 9 = 81이에요.","잘라 낸 부분의 넓이는 3 × 4 = 12예요.","81 − 12 = 69 — 남은 넓이는 69 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L05_challenge#10','math',5,1,'u6','L05','g5_1_math_u6_L05_challenge','lesson_challenge','M5-1-u6-C5',4,'essay','teacher','가로 8 cm, 세로 5 cm인 직사각형의 넓이를 1 cm² 칸을 하나씩 세지 않고 구하는 방법을 설명하고, 그 방법이 왜 맞는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u6-C5","difficulty":4,"kind":"essay","stem":"가로 8 cm, 세로 5 cm인 직사각형의 넓이를 1 cm² 칸을 하나씩 세지 않고 구하는 방법을 설명하고, 그 방법이 왜 맞는지 쓰세요.","answer_guide":{"answer":"예: 가로가 8 cm이므로 한 줄에 1 cm² 칸이 8개 들어가고, 세로가 5 cm이므로 그런 줄이 5줄 있다. 8칸씩 5줄은 8 × 5 = 40칸이므로 넓이는 40 cm²이다. 그래서 직사각형의 넓이는 (가로) × (세로)로 구할 수 있다.","scoring_points":["한 줄의 칸 수가 가로와 같다고 썼는가","줄의 수가 세로와 같다고 썼는가","8 × 5 = 40, 넓이 40 cm²를 바르게 구했는가"]},"explanation":["한 줄에 가로만큼 8칸이 들어가요.","세로만큼 5줄이 있어요.","8 × 5 = 40 — 넓이는 40 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_basic#1','math',5,1,'u6','L06','g5_1_math_u6_L06_basic','lesson_basic','M5-1-u6-C6',1,'mc','auto','1 m²는 어떤 넓이인가요?',ARRAY['M5-1-u6-X06']::text[],true,'{"seq":1,"concept":"M5-1-u6-C6","difficulty":1,"kind":"mc","stem":"1 m²는 어떤 넓이인가요?","options":[{"t":"한 변의 길이가 1 m인 정사각형의 넓이","correct":true},{"t":"한 변의 길이가 1 cm인 정사각형의 넓이","mis":"M5-1-u6-X06"},{"t":"둘레가 1 m인 도형의 넓이","mis":"M5-1-u6-X06"},{"t":"가로가 1 m인 직사각형의 넓이","mis":"M5-1-u6-X06"}],"explanation":["1 cm²를 약속한 것처럼 더 큰 칸도 약속해요.","한 변이 1 m인 정사각형의 넓이가 1 m²(1 제곱미터)예요.","둘레나 가로 하나로는 칸이 정해지지 않아요."],"variant_rule":{"alt":[{"stem":"1 km²는 어떤 넓이인가요?","options":[{"t":"한 변의 길이가 1 km인 정사각형의 넓이","correct":true},{"t":"한 변의 길이가 1 m인 정사각형의 넓이","mis":"M5-1-u6-X06"},{"t":"둘레가 1 km인 도형의 넓이","mis":"M5-1-u6-X06"},{"t":"가로가 1 km인 직사각형의 넓이","mis":"M5-1-u6-X06"}],"explanation":["땅처럼 아주 넓은 곳은 더 큰 칸이 필요해요.","한 변이 1 km인 정사각형의 넓이를 1 km²(1 제곱킬로미터)라고 해요.","둘레나 가로 하나로는 칸이 정해지지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_basic#2','math',5,1,'u6','L06','g5_1_math_u6_L06_basic','lesson_basic','M5-1-u6-C6',1,'mc','auto','1 m²는 몇 cm²인가요?',ARRAY['M5-1-u6-X07','M5-1-u6-X16']::text[],true,'{"seq":2,"concept":"M5-1-u6-C6","difficulty":1,"kind":"mc","stem":"1 m²는 몇 cm²인가요?","options":[{"t":"10000 cm²","correct":true},{"t":"100 cm²","mis":"M5-1-u6-X07"},{"t":"1000 cm²","mis":"M5-1-u6-X07"},{"t":"1000000 cm²","mis":"M5-1-u6-X16"}],"explanation":["1 m = 100 cm예요.","한 변 1 m 정사각형은 가로 100 cm, 세로 100 cm예요.","100 × 100 = 10000 — 1 m² = 10000 cm²예요."],"variant_rule":{"alt":[{"stem":"1 km²는 몇 m²인가요?","options":[{"t":"1000000 m²","correct":true},{"t":"1000 m²","mis":"M5-1-u6-X07"},{"t":"10000 m²","mis":"M5-1-u6-X07"},{"t":"100 m²","mis":"M5-1-u6-X07"}],"explanation":["1 km = 1000 m예요.","한 변 1 km 정사각형은 가로 1000 m, 세로 1000 m예요.","1000 × 1000 = 1000000 — 1 km² = 1000000 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_basic#3','math',5,1,'u6','L06','g5_1_math_u6_L06_basic','lesson_basic','M5-1-u6-C6',1,'mc','auto','1 m²를 바르게 읽은 것은 어느 것인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X06']::text[],true,'{"seq":3,"concept":"M5-1-u6-C6","difficulty":1,"kind":"mc","stem":"1 m²를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 제곱미터","correct":true},{"t":"1 미터","mis":"M5-1-u6-X01"},{"t":"1 미터 이","mis":"M5-1-u6-X06"},{"t":"1 사각미터","mis":"M5-1-u6-X06"}],"explanation":["m² 오른쪽 위의 작은 2는 제곱이라고 읽어요.","1 m²는 1 제곱미터라고 읽어요.","1 미터는 길이의 단위예요."],"variant_rule":{"alt":[{"stem":"1 km²를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"1 제곱킬로미터","correct":true},{"t":"1 킬로미터","mis":"M5-1-u6-X01"},{"t":"1 킬로미터 이","mis":"M5-1-u6-X06"},{"t":"1 사각킬로미터","mis":"M5-1-u6-X06"}],"explanation":["km² 오른쪽 위의 작은 2는 제곱이라고 읽어요.","1 km²는 1 제곱킬로미터라고 읽어요.","1 킬로미터는 길이의 단위예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_basic#4','math',5,1,'u6','L06','g5_1_math_u6_L06_basic','lesson_basic','M5-1-u6-C6',1,'sa','auto','가로 200 cm, 세로 1 m인 직사각형이에요. 넓이는 몇 m²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C6","difficulty":1,"kind":"sa","stem":"가로 200 cm, 세로 1 m인 직사각형이에요. 넓이는 몇 m²인가요?","answer":["2"],"explanation":["곱하기 전에 단위를 맞춰요 — 200 cm = 2 m예요.","가로 2 m, 세로 1 m예요.","2 × 1 = 2 — 넓이는 2 m²예요."],"mis":"M5-1-u6-X08","variant_rule":{"alt":[{"stem":"가로 300 cm, 세로 2 m인 직사각형이에요. 넓이는 몇 m²인가요?","answer":["6"],"explanation":["곱하기 전에 단위를 맞춰요 — 300 cm = 3 m예요.","가로 3 m, 세로 2 m예요.","3 × 2 = 6 — 넓이는 6 m²예요."]},{"stem":"가로 500 cm, 세로 2 m인 직사각형이에요. 넓이는 몇 m²인가요?","answer":["10"],"explanation":["곱하기 전에 단위를 맞춰요 — 500 cm = 5 m예요.","가로 5 m, 세로 2 m예요.","5 × 2 = 10 — 넓이는 10 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_basic#5','math',5,1,'u6','L06','g5_1_math_u6_L06_basic','lesson_basic','M5-1-u6-C6',2,'sa','auto','120000 cm²는 몇 m²인가요?','{}'::text[],true,'{"seq":5,"concept":"M5-1-u6-C6","difficulty":2,"kind":"sa","stem":"120000 cm²는 몇 m²인가요?","answer":["12"],"explanation":["1 m² = 10000 cm²예요.","120000 안에 10000이 몇 번 들어가는지 봐요.","120000 ÷ 10000 = 12 — 120000 cm² = 12 m²예요."],"mis":"M5-1-u6-X07","variant_rule":{"alt":[{"stem":"50000 cm²는 몇 m²인가요?","answer":["5"],"explanation":["1 m² = 10000 cm²예요.","50000 안에 10000이 몇 번 들어가는지 봐요.","50000 ÷ 10000 = 5 — 50000 cm² = 5 m²예요."]},{"stem":"230000 cm²는 몇 m²인가요?","answer":["23"],"explanation":["1 m² = 10000 cm²예요.","230000 안에 10000이 몇 번 들어가는지 봐요.","230000 ÷ 10000 = 23 — 230000 cm² = 23 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_basic#6','math',5,1,'u6','L06','g5_1_math_u6_L06_basic','lesson_basic','M5-1-u6-C6',2,'mc','auto','한 변의 길이가 5000 m인 정사각형 모양 땅의 넓이는 몇 km²인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X07']::text[],true,'{"seq":6,"concept":"M5-1-u6-C6","difficulty":2,"kind":"mc","stem":"한 변의 길이가 5000 m인 정사각형 모양 땅의 넓이는 몇 km²인가요?","options":[{"t":"25 km²","correct":true},{"t":"20 km²","mis":"M5-1-u6-X01"},{"t":"5 km²","mis":"M5-1-u6-X07"},{"t":"25000 km²","mis":"M5-1-u6-X07"}],"explanation":["5000 m = 5 km예요.","넓이는 (한 변) × (한 변)이에요.","5 × 5 = 25 — 넓이는 25 km²예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 3000 m인 정사각형 모양 땅의 넓이는 몇 km²인가요?","options":[{"t":"9 km²","correct":true},{"t":"12 km²","mis":"M5-1-u6-X01"},{"t":"3 km²","mis":"M5-1-u6-X07"},{"t":"9000 km²","mis":"M5-1-u6-X07"}],"explanation":["3000 m = 3 km예요.","넓이는 (한 변) × (한 변)이에요.","3 × 3 = 9 — 넓이는 9 km²예요."]},{"stem":"한 변의 길이가 4 km인 정사각형 모양 땅의 넓이는 몇 km²인가요?","options":[{"t":"16 km²","correct":true},{"t":"4 km²","mis":"M5-1-u6-X07"},{"t":"4000 km²","mis":"M5-1-u6-X07"},{"t":"160 km²","mis":"M5-1-u6-X16"}],"explanation":["한 변이 4 km예요.","넓이는 (한 변) × (한 변)이에요.","4 × 4 = 16 — 넓이는 16 km²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_basic#7','math',5,1,'u6','L06','g5_1_math_u6_L06_basic','lesson_basic','M5-1-u6-C6',2,'mc','auto','넓이 단위의 관계로 잘못된 것은 어느 것인가요?',ARRAY['M5-1-u6-X17']::text[],true,'{"seq":7,"concept":"M5-1-u6-C6","difficulty":2,"kind":"mc","stem":"넓이 단위의 관계로 잘못된 것은 어느 것인가요?","options":[{"t":"1 m² = 100 cm²","correct":true},{"t":"1 m² = 10000 cm²","mis":"M5-1-u6-X17"},{"t":"1 km² = 1000000 m²","mis":"M5-1-u6-X17"},{"t":"1 m = 100 cm","mis":"M5-1-u6-X17"}],"explanation":["1 m = 100 cm는 길이의 관계예요.","넓이는 가로도 세로도 100배라 100 × 100 = 10000배예요.","그래서 1 m² = 100 cm²는 잘못이에요."],"variant_rule":{"alt":[{"stem":"넓이 단위의 관계로 옳은 것은 어느 것인가요?","options":[{"t":"1 km² = 1000000 m²","correct":true},{"t":"1 km² = 1000 m²","mis":"M5-1-u6-X07"},{"t":"1 m² = 1000 cm²","mis":"M5-1-u6-X07"},{"t":"1 km² = 10000 cm²","mis":"M5-1-u6-X07"}],"explanation":["1 km = 1000 m예요.","가로 1000배, 세로 1000배예요.","1000 × 1000 = 1000000 — 1 km² = 1000000 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_basic#8','math',5,1,'u6','L06','g5_1_math_u6_L06_basic','lesson_basic','M5-1-u6-C6',2,'sa','auto','가로 6 km, 세로 4 km인 직사각형 모양 공원의 넓이는 몇 km²인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C6","difficulty":2,"kind":"sa","stem":"가로 6 km, 세로 4 km인 직사각형 모양 공원의 넓이는 몇 km²인가요?","answer":["24"],"explanation":["가로도 세로도 km라 단위가 같아요.","넓이는 (가로) × (세로)예요.","6 × 4 = 24 — 넓이는 24 km²예요."],"variant_rule":{"alt":[{"stem":"가로 5 km, 세로 3 km인 직사각형 모양 공원의 넓이는 몇 km²인가요?","answer":["15"],"explanation":["가로도 세로도 km라 단위가 같아요.","넓이는 (가로) × (세로)예요.","5 × 3 = 15 — 넓이는 15 km²예요."]},{"stem":"가로 8 km, 세로 7 km인 직사각형 모양 공원의 넓이는 몇 km²인가요?","answer":["56"],"explanation":["가로도 세로도 km라 단위가 같아요.","넓이는 (가로) × (세로)예요.","8 × 7 = 56 — 넓이는 56 km²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_basic#9','math',5,1,'u6','L06','g5_1_math_u6_L06_basic','lesson_basic','M5-1-u6-C6',2,'match','auto','넓이를 나타내기에 알맞은 단위를 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M5-1-u6-C6","difficulty":2,"kind":"match","stem":"넓이를 나타내기에 알맞은 단위를 이으세요.","pairs":[{"l":"교실 바닥의 넓이","r":"m²"},{"l":"수첩 표지의 넓이","r":"cm²"},{"l":"서울특별시의 넓이","r":"km²"}],"mis":"M5-1-u6-X06","explanation":["수첩처럼 손바닥만 한 넓이는 cm²가 알맞아요.","교실 바닥은 한 변 1 m 칸으로 세기 좋아 m²예요.","도시처럼 아주 넓은 땅은 km²로 나타내요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 넓이를 나타내기에 알맞은 단위를 이으세요.","pairs":[{"l":"운동장의 넓이","r":"m²"},{"l":"우표의 넓이","r":"cm²"},{"l":"제주도의 넓이","r":"km²"}],"explanation":["우표는 작아서 cm²예요.","운동장은 m²로 나타내기 좋아요.","섬 하나처럼 아주 넓은 땅은 km²예요."]},{"stem":"이번에는 다른 보기예요. 넓이를 나타내기에 알맞은 단위를 이으세요.","pairs":[{"l":"현관 신발장 문의 넓이","r":"m²"},{"l":"색종이 한 장의 넓이","r":"cm²"},{"l":"한강 공원 전체의 넓이","r":"km²"}],"explanation":["색종이는 cm²로 나타내요.","신발장 문은 1 m² 안팎이라 m²가 알맞아요.","아주 넓은 공원 전체는 km²로 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_basic#10','math',5,1,'u6','L06','g5_1_math_u6_L06_basic','lesson_basic','M5-1-u6-C6',3,'sa','auto','가로 4 m, 세로 3 m인 바닥에 한 변이 50 cm인 정사각형 타일을 빈틈없이 깔려고 해요. 타일은 몇 장 필요한가요?','{}'::text[],true,'{"seq":10,"concept":"M5-1-u6-C6","difficulty":3,"kind":"sa","stem":"가로 4 m, 세로 3 m인 바닥에 한 변이 50 cm인 정사각형 타일을 빈틈없이 깔려고 해요. 타일은 몇 장 필요한가요?","answer":["48"],"explanation":["1 m = 100 cm니 1 m² 칸 한 줄에 타일이 100 ÷ 50 = 2장, 2줄 — 1 m²에 2 × 2 = 4장이에요.","바닥의 넓이는 4 × 3 = 12예요 — 12 m²예요.","12 × 4 = 48 — 타일은 48장이에요."],"mis":"M5-1-u6-X07","variant_rule":{"alt":[{"stem":"가로 3 m, 세로 3 m인 바닥에 한 변이 50 cm인 정사각형 타일을 빈틈없이 깔려고 해요. 타일은 몇 장 필요한가요?","answer":["36"],"explanation":["1 m = 100 cm니 1 m² 칸 한 줄에 타일이 100 ÷ 50 = 2장, 2줄 — 1 m²에 2 × 2 = 4장이에요.","바닥의 넓이는 3 × 3 = 9예요 — 9 m²예요.","9 × 4 = 36 — 타일은 36장이에요."]},{"stem":"가로 2 m, 세로 2 m인 바닥에 한 변이 25 cm인 정사각형 타일을 빈틈없이 깔려고 해요. 타일은 몇 장 필요한가요?","answer":["64"],"explanation":["1 m = 100 cm니 1 m² 칸 한 줄에 타일이 100 ÷ 25 = 4장, 4줄 — 1 m²에 4 × 4 = 16장이에요.","바닥의 넓이는 2 × 2 = 4예요 — 4 m²예요.","4 × 16 = 64 — 타일은 64장이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_challenge#1','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',2,'error','auto','3 m²를 cm²로 바꾸는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u6-X07','M5-1-u6-X17']::text[],true,'{"seq":1,"concept":"M5-1-u6-C6","difficulty":2,"kind":"error","stem":"3 m²를 cm²로 바꾸는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「1 m = 100 cm니까 3 × 100 = 300 cm²야.」","correct":true,"mis_target":"M5-1-u6-X07"},{"t":"도현 — 「1 m²는 100 × 100 = 10000 cm²야.」","mis":"M5-1-u6-X17"},{"t":"하은 — 「그래서 3 × 10000 = 30000 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["넓이는 가로도 세로도 100배가 돼요.","그래서 1 m² = 100 × 100 = 10000 cm²예요.","서윤은 길이처럼 100배만 해서 잘못 말했어요 — 3 m² = 30000 cm²예요."],"variant_rule":{"alt":[{"stem":"5 m²를 cm²로 바꾸는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「1 m = 100 cm니까 5 × 100 = 500 cm²야.」","correct":true,"mis_target":"M5-1-u6-X07"},{"t":"라온 — 「1 m²는 100 × 100 = 10000 cm²야.」","mis":"M5-1-u6-X17"},{"t":"예준 — 「그래서 5 × 10000 = 50000 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["넓이는 가로도 세로도 100배가 돼요.","그래서 1 m² = 100 × 100 = 10000 cm²예요.","지민은 길이처럼 100배만 해서 잘못 말했어요 — 5 m² = 50000 cm²예요."]},{"stem":"4 m²를 cm²로 바꾸는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤아 — 「1 m = 100 cm니까 4 × 100 = 400 cm²야.」","correct":true,"mis_target":"M5-1-u6-X07"},{"t":"시우 — 「1 m²는 100 × 100 = 10000 cm²야.」","mis":"M5-1-u6-X17"},{"t":"나린 — 「그래서 4 × 10000 = 40000 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["넓이는 가로도 세로도 100배가 돼요.","그래서 1 m² = 100 × 100 = 10000 cm²예요.","윤아는 길이처럼 100배만 해서 잘못 말했어요 — 4 m² = 40000 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_challenge#2','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',2,'sa','auto','가로 800 cm, 세로 150 cm인 현수막이 있어요. 넓이는 몇 m²인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C6","difficulty":2,"kind":"sa","stem":"가로 800 cm, 세로 150 cm인 현수막이 있어요. 넓이는 몇 m²인가요?","answer":["12"],"explanation":["cm로 곱하면 800 × 150 = 120000이에요 — 120000 cm²예요.","1 m² = 10000 cm²예요.","120000 ÷ 10000 = 12 — 넓이는 12 m²예요."],"mis":"M5-1-u6-X07","variant_rule":{"alt":[{"stem":"가로 600 cm, 세로 200 cm인 현수막이 있어요. 넓이는 몇 m²인가요?","answer":["12"],"explanation":["cm로 곱하면 600 × 200 = 120000이에요 — 120000 cm²예요.","1 m² = 10000 cm²니 120000 ÷ 10000 = 12예요.","m로 바꾸어 곱해도 6 × 2 = 12 — 넓이는 12 m²예요."]},{"stem":"가로 900 cm, 세로 200 cm인 현수막이 있어요. 넓이는 몇 m²인가요?","answer":["18"],"explanation":["cm로 곱하면 900 × 200 = 180000이에요 — 180000 cm²예요.","1 m² = 10000 cm²니 180000 ÷ 10000 = 18이에요.","m로 바꾸어 곱해도 9 × 2 = 18 — 넓이는 18 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_challenge#3','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',3,'mc','auto','넓이가 가장 넓은 것은 어느 것인가요? ㉠ 3 m² ㉡ 25000 cm² ㉢ 가로 2 m, 세로 160 cm인 직사각형',ARRAY['M5-1-u6-X07','M5-1-u6-X08']::text[],true,'{"seq":3,"concept":"M5-1-u6-C6","difficulty":3,"kind":"mc","stem":"넓이가 가장 넓은 것은 어느 것인가요? ㉠ 3 m² ㉡ 25000 cm² ㉢ 가로 2 m, 세로 160 cm인 직사각형","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-1-u6-X07"},{"t":"㉡","mis":"M5-1-u6-X07"},{"t":"모두 같다","mis":"M5-1-u6-X08"}],"explanation":["모두 cm²로 맞추어 견주어요.","㉠ 3 × 10000 = 30000, ㉡ 25000, ㉢ 200 × 160 = 32000이에요.","가장 넓은 것은 ㉢이에요."],"variant_rule":{"alt":[{"stem":"넓이가 가장 넓은 것은 어느 것인가요? ㉠ 2 m² ㉡ 30000 cm² ㉢ 가로 3 m, 세로 90 cm인 직사각형","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-1-u6-X07"},{"t":"㉢","mis":"M5-1-u6-X07"},{"t":"모두 같다","mis":"M5-1-u6-X08"}],"explanation":["모두 cm²로 맞추어 견주어요.","㉠ 2 × 10000 = 20000, ㉡ 30000, ㉢ 300 × 90 = 27000이에요.","가장 넓은 것은 ㉡이에요."]},{"stem":"넓이가 가장 넓은 것은 어느 것인가요? ㉠ 4 m² ㉡ 35000 cm² ㉢ 가로 2 m, 세로 180 cm인 직사각형","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M5-1-u6-X07"},{"t":"㉢","mis":"M5-1-u6-X07"},{"t":"모두 같다","mis":"M5-1-u6-X08"}],"explanation":["모두 cm²로 맞추어 견주어요.","㉠ 4 × 10000 = 40000, ㉡ 35000, ㉢ 200 × 180 = 36000이에요.","가장 넓은 것은 ㉠이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_challenge#4','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',3,'sa','auto','가로 2000 m, 세로 3 km인 직사각형 모양 땅의 넓이는 몇 km²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C6","difficulty":3,"kind":"sa","stem":"가로 2000 m, 세로 3 km인 직사각형 모양 땅의 넓이는 몇 km²인가요?","answer":["6"],"explanation":["단위를 km로 맞춰요 — 2000 m = 2 km예요.","가로 2 km, 세로 3 km예요.","2 × 3 = 6 — 넓이는 6 km²예요."],"mis":"M5-1-u6-X08","variant_rule":{"alt":[{"stem":"가로 4000 m, 세로 2 km인 직사각형 모양 땅의 넓이는 몇 km²인가요?","answer":["8"],"explanation":["단위를 km로 맞춰요 — 4000 m = 4 km예요.","가로 4 km, 세로 2 km예요.","4 × 2 = 8 — 넓이는 8 km²예요."]},{"stem":"가로 3000 m, 세로 5 km인 직사각형 모양 땅의 넓이는 몇 km²인가요?","answer":["15"],"explanation":["단위를 km로 맞춰요 — 3000 m = 3 km예요.","가로 3 km, 세로 5 km예요.","3 × 5 = 15 — 넓이는 15 km²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_challenge#5','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',3,'mc','auto','4 m²는 몇 cm²인가요?',ARRAY['M5-1-u6-X07','M5-1-u6-X16']::text[],true,'{"seq":5,"concept":"M5-1-u6-C6","difficulty":3,"kind":"mc","stem":"4 m²는 몇 cm²인가요?","options":[{"t":"40000 cm²","correct":true},{"t":"400 cm²","mis":"M5-1-u6-X07"},{"t":"4000 cm²","mis":"M5-1-u6-X07"},{"t":"400000 cm²","mis":"M5-1-u6-X16"}],"explanation":["1 m² = 10000 cm²예요.","4 m²는 1 m²가 4개예요.","4 × 10000 = 40000 — 40000 cm²예요."],"variant_rule":{"alt":[{"stem":"7 m²는 몇 cm²인가요?","options":[{"t":"70000 cm²","correct":true},{"t":"700 cm²","mis":"M5-1-u6-X07"},{"t":"7000 cm²","mis":"M5-1-u6-X07"},{"t":"700000 cm²","mis":"M5-1-u6-X16"}],"explanation":["1 m² = 10000 cm²예요.","7 m²는 1 m²가 7개예요.","7 × 10000 = 70000 — 70000 cm²예요."]},{"stem":"12 m²는 몇 cm²인가요?","options":[{"t":"120000 cm²","correct":true},{"t":"1200 cm²","mis":"M5-1-u6-X07"},{"t":"12000 cm²","mis":"M5-1-u6-X07"},{"t":"1200000 cm²","mis":"M5-1-u6-X16"}],"explanation":["1 m² = 10000 cm²예요.","12 m²는 1 m²가 12개예요.","12 × 10000 = 120000 — 120000 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_challenge#6','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',3,'mc','auto','넓이 단위에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M5-1-u6-X07']::text[],true,'{"seq":6,"concept":"M5-1-u6-C6","difficulty":3,"kind":"mc","stem":"넓이 단위에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"1 m²는 1 cm²의 10000배다","correct":true},{"t":"1 m²는 1 cm²의 100배다","mis":"M5-1-u6-X07"},{"t":"1 km²는 1 m²의 1000배다","mis":"M5-1-u6-X07"},{"t":"넓이 단위는 길이 단위와 같은 배율로 커진다","mis":"M5-1-u6-X07"}],"explanation":["1 m = 100 cm라 가로 100배, 세로 100배예요.","그래서 1 m² = 10000 cm²예요.","1 km²도 1000 × 1000 = 1000000배예요."],"variant_rule":{"alt":[{"stem":"넓이 단위의 관계로 옳은 것은 어느 것인가요?","options":[{"t":"1 km² = 1000000 m²","correct":true},{"t":"1 km² = 1000 m²","mis":"M5-1-u6-X07"},{"t":"1 m² = 1000 cm²","mis":"M5-1-u6-X07"},{"t":"1 km² = 10000 cm²","mis":"M5-1-u6-X07"}],"explanation":["1 km = 1000 m예요.","가로 1000배, 세로 1000배예요.","1000 × 1000 = 1000000 — 1 km² = 1000000 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_challenge#7','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',3,'sa','auto','넓이가 6 km²인 직사각형 모양 땅의 가로가 2000 m예요. 세로는 몇 km인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C6","difficulty":3,"kind":"sa","stem":"넓이가 6 km²인 직사각형 모양 땅의 가로가 2000 m예요. 세로는 몇 km인가요?","answer":["3"],"explanation":["가로 2000 m = 2 km예요.","2 × □ = 6이니 □ = 6 ÷ 2예요.","6 ÷ 2 = 3 — 세로는 3 km예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"넓이가 12 km²인 직사각형 모양 땅의 가로가 3000 m예요. 세로는 몇 km인가요?","answer":["4"],"explanation":["가로 3000 m = 3 km예요.","3 × □ = 12니 □ = 12 ÷ 3이에요.","12 ÷ 3 = 4 — 세로는 4 km예요."]},{"stem":"넓이가 20 km²인 직사각형 모양 땅의 가로가 4000 m예요. 세로는 몇 km인가요?","answer":["5"],"explanation":["가로 4000 m = 4 km예요.","4 × □ = 20이니 □ = 20 ÷ 4예요.","20 ÷ 4 = 5 — 세로는 5 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_challenge#8','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',4,'sa','auto','가로 1 m, 세로 2 m인 바닥에 한 변이 25 cm인 정사각형 타일을 빈틈없이 깔려고 해요. 타일은 몇 장 필요한가요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C6","difficulty":4,"kind":"sa","stem":"가로 1 m, 세로 2 m인 바닥에 한 변이 25 cm인 정사각형 타일을 빈틈없이 깔려고 해요. 타일은 몇 장 필요한가요?","answer":["32"],"explanation":["1 m = 100 cm니 1 m² 칸 한 줄에 타일이 100 ÷ 25 = 4장, 4줄 — 1 m²에 4 × 4 = 16장이에요.","바닥의 넓이는 1 × 2 = 2예요 — 2 m²예요.","2 × 16 = 32 — 타일은 32장이에요."],"mis":"M5-1-u6-X07","variant_rule":{"alt":[{"stem":"가로 2 m, 세로 2 m인 바닥에 한 변이 50 cm인 정사각형 타일을 빈틈없이 깔려고 해요. 타일은 몇 장 필요한가요?","answer":["16"],"explanation":["1 m = 100 cm니 1 m² 칸 한 줄에 타일이 100 ÷ 50 = 2장, 2줄 — 1 m²에 2 × 2 = 4장이에요.","바닥의 넓이는 2 × 2 = 4예요 — 4 m²예요.","4 × 4 = 16 — 타일은 16장이에요."]},{"stem":"가로 3 m, 세로 2 m인 바닥에 한 변이 50 cm인 정사각형 타일을 빈틈없이 깔려고 해요. 타일은 몇 장 필요한가요?","answer":["24"],"explanation":["1 m = 100 cm니 1 m² 칸 한 줄에 타일이 100 ÷ 50 = 2장, 2줄 — 1 m²에 2 × 2 = 4장이에요.","바닥의 넓이는 3 × 2 = 6이에요 — 6 m²예요.","6 × 4 = 24 — 타일은 24장이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_challenge#9','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',4,'mc','auto','1 km = 1000 m인데 1 km²가 1000 m²가 아니라 1000000 m²인 까닭은 무엇인가요?',ARRAY['M5-1-u6-X07','M5-1-u6-X01']::text[],true,'{"seq":9,"concept":"M5-1-u6-C6","difficulty":4,"kind":"mc","stem":"1 km = 1000 m인데 1 km²가 1000 m²가 아니라 1000000 m²인 까닭은 무엇인가요?","options":[{"t":"가로와 세로가 모두 1000배가 되므로","correct":true},{"t":"1 km²는 원래 1000000으로 약속했으므로","mis":"M5-1-u6-X07"},{"t":"넓이 단위는 길이 단위의 10배씩 커지므로","mis":"M5-1-u6-X07"},{"t":"km²는 둘레를 나타내므로","mis":"M5-1-u6-X01"}],"explanation":["한 변 1 km 정사각형은 가로 1000 m, 세로 1000 m예요.","1 m² 칸이 한 줄에 1000개씩 1000줄이에요.","1000 × 1000 = 1000000 — 두 방향 모두 1000배라서예요."],"variant_rule":{"alt":[{"stem":"1 m = 100 cm인데 1 m²가 100 cm²가 아니라 10000 cm²인 까닭은 무엇인가요?","options":[{"t":"가로와 세로가 모두 100배가 되므로","correct":true},{"t":"m²는 cm²보다 100배 넓기로 약속했으므로","mis":"M5-1-u6-X07"},{"t":"넓이는 둘레의 100배이므로","mis":"M5-1-u6-X01"},{"t":"cm²가 1 m를 100번 잰 것이므로","mis":"M5-1-u6-X06"}],"explanation":["한 변 1 m 정사각형은 가로 100 cm, 세로 100 cm예요.","1 cm² 칸이 한 줄에 100개씩 100줄이에요.","100 × 100 = 10000 — 두 방향 모두 100배라서예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L06_challenge#10','math',5,1,'u6','L06','g5_1_math_u6_L06_challenge','lesson_challenge','M5-1-u6-C6',4,'essay','teacher','1 m = 100 cm인데 1 m²는 왜 100 cm²가 아니라 10000 cm²인지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u6-C6","difficulty":4,"kind":"essay","stem":"1 m = 100 cm인데 1 m²는 왜 100 cm²가 아니라 10000 cm²인지 설명하세요.","answer_guide":{"answer":"예: 1 m²는 한 변이 1 m인 정사각형의 넓이이다. 1 m = 100 cm이므로 이 정사각형을 1 cm² 칸으로 덮으면 한 줄에 100칸씩 100줄이 된다. 100 × 100 = 10000이므로 1 m² = 10000 cm²이다. 길이는 한 방향만 100배지만 넓이는 가로와 세로 두 방향이 모두 100배가 되기 때문이다.","scoring_points":["1 m²가 한 변 1 m 정사각형의 넓이라고 썼는가","한 줄 100칸씩 100줄(100 × 100)으로 설명했는가","두 방향이 모두 100배라 10000배라고 썼는가"]},"explanation":["한 변 1 m = 100 cm예요.","1 cm² 칸이 100칸씩 100줄이에요.","100 × 100 = 10000 — 1 m² = 10000 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_basic#1','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',1,'mc','auto','평행사변형에서 높이란 무엇인가요?',ARRAY['M5-1-u6-X11']::text[],true,'{"seq":1,"concept":"M5-1-u6-C7","difficulty":1,"kind":"mc","stem":"평행사변형에서 높이란 무엇인가요?","options":[{"t":"두 밑변 사이의 거리","correct":true},{"t":"가장 긴 변의 길이","mis":"M5-1-u6-X11"},{"t":"이웃한 변의 길이","mis":"M5-1-u6-X11"},{"t":"대각선의 길이","mis":"M5-1-u6-X11"}],"explanation":["평행한 두 변을 밑변이라고 해요.","두 밑변 사이의 거리가 높이예요.","높이는 밑변과 수직인 선분이라 이웃한 변과 달라요."],"variant_rule":{"alt":[{"stem":"평행사변형에서 밑변이란 무엇인가요?","options":[{"t":"평행한 두 변","correct":true},{"t":"가장 긴 변","mis":"M5-1-u6-X11"},{"t":"이웃한 두 변","mis":"M5-1-u6-X11"},{"t":"높이와 수직인 대각선","mis":"M5-1-u6-X11"}],"explanation":["평행사변형은 마주 보는 두 쌍의 변이 평행해요.","평행한 두 변을 밑변이라고 해요.","두 밑변 사이의 거리가 높이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_basic#2','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',1,'sa','auto','밑변이 5 cm, 높이가 3 cm인 평행사변형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C7","difficulty":1,"kind":"sa","stem":"밑변이 5 cm, 높이가 3 cm인 평행사변형의 넓이는 몇 cm²인가요?","answer":["15"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 5, 높이 3을 곱해요.","5 × 3 = 15 — 넓이는 15 cm²예요."],"variant_rule":{"alt":[{"stem":"밑변이 9 cm, 높이가 4 cm인 평행사변형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 9, 높이 4를 곱해요.","9 × 4 = 36 — 넓이는 36 cm²예요."]},{"stem":"밑변이 6 m, 높이가 7 m인 평행사변형의 넓이는 몇 m²인가요?","answer":["42"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 6, 높이 7을 곱해요.","6 × 7 = 42 — 넓이는 42 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_basic#3','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',1,'mc','auto','평행사변형의 넓이를 구하는 식은 어느 것인가요?',ARRAY['M5-1-u6-X09','M5-1-u6-X01','M5-1-u6-X10']::text[],true,'{"seq":3,"concept":"M5-1-u6-C7","difficulty":1,"kind":"mc","stem":"평행사변형의 넓이를 구하는 식은 어느 것인가요?","options":[{"t":"(밑변의 길이) × (높이)","correct":true},{"t":"(밑변) × (이웃한 변)","mis":"M5-1-u6-X09"},{"t":"(밑변 + 높이) × 2","mis":"M5-1-u6-X01"},{"t":"(밑변의 길이) × (높이) ÷ 2","mis":"M5-1-u6-X10"}],"explanation":["한쪽 삼각형을 잘라 반대쪽에 붙이면 직사각형이 돼요.","그 직사각형의 가로는 밑변, 세로는 높이예요.","그래서 (밑변의 길이) × (높이)예요."],"variant_rule":{"alt":[{"stem":"평행사변형의 넓이를 구할 때 꼭 알아야 하는 두 길이는 무엇인가요?","options":[{"t":"밑변의 길이와 높이","correct":true},{"t":"밑변의 길이와 이웃한 변의 길이","mis":"M5-1-u6-X09"},{"t":"두 대각선의 길이","mis":"M5-1-u6-X13"},{"t":"네 변의 길이","mis":"M5-1-u6-X01"}],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","이웃한 변은 비스듬해서 넓이에 쓰지 않아요.","그래서 밑변의 길이와 높이를 알아야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_basic#4','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',1,'sa','auto','밑변이 10 cm, 높이가 8 cm인 평행사변형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C7","difficulty":1,"kind":"sa","stem":"밑변이 10 cm, 높이가 8 cm인 평행사변형의 넓이는 몇 cm²인가요?","answer":["80"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 10, 높이 8을 곱해요.","10 × 8 = 80 — 넓이는 80 cm²예요."],"variant_rule":{"alt":[{"stem":"밑변이 11 cm, 높이가 9 cm인 평행사변형의 넓이는 몇 cm²인가요?","answer":["99"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 11, 높이 9를 곱해요.","11 × 9 = 99 — 넓이는 99 cm²예요."]},{"stem":"밑변이 12 m, 높이가 6 m인 평행사변형의 넓이는 몇 m²인가요?","answer":["72"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 12, 높이 6을 곱해요.","12 × 6 = 72 — 넓이는 72 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_basic#5','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',2,'mc','auto','평행사변형 ㄱㄴㄷㄹ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 선분은 어느 것인가요?',ARRAY['M5-1-u6-X11','M5-1-u6-X17']::text[],true,'{"seq":5,"concept":"M5-1-u6-C7","difficulty":2,"kind":"mc","stem":"평행사변형 ㄱㄴㄷㄹ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㅁ","correct":true},{"t":"선분 ㄱㄴ","mis":"M5-1-u6-X11"},{"t":"선분 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"선분 ㄹㄷ","mis":"M5-1-u6-X11"}],"explanation":["높이는 두 밑변(변 ㄱㄹ과 변 ㄴㄷ) 사이의 거리예요.","밑변과 수직으로 만나는 선분을 찾아요 — 직각 표시가 있어요.","그래서 높이는 선분 ㄱㅁ이에요. 이웃한 변은 비스듬해 높이가 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[45,15],"ㄴ":[15,75],"ㄷ":[105,75],"ㄹ":[135,15],"ㅁ":[45,75]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㅁ"]],"right":[["ㄱ","ㅁ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 평행사변형 ㄱㄴㄷㄹ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 선분은 어느 것인가요?","options":[{"t":"선분 ㄹㅁ","correct":true},{"t":"선분 ㄹㄷ","mis":"M5-1-u6-X11"},{"t":"선분 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"선분 ㄱㄴ","mis":"M5-1-u6-X11"}],"explanation":["높이는 두 밑변(변 ㄱㄹ과 변 ㄴㄷ) 사이의 거리예요.","밑변과 수직으로 만나는 선분을 찾아요 — 직각 표시가 있어요.","그래서 높이는 선분 ㄹㅁ이에요. 이웃한 변은 비스듬해 높이가 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[15,15],"ㄴ":[45,75],"ㄷ":[135,75],"ㄹ":[105,15],"ㅁ":[105,75]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄹ","ㅁ"]],"right":[["ㄹ","ㅁ","ㄴ"]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 평행사변형 ㄱㄴㄷㄹ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 선분은 어느 것인가요?","options":[{"t":"선분 ㅁㅂ","correct":true},{"t":"선분 ㄱㄴ","mis":"M5-1-u6-X11"},{"t":"선분 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"선분 ㄹㄷ","mis":"M5-1-u6-X11"}],"explanation":["높이는 두 밑변(변 ㄱㄹ과 변 ㄴㄷ) 사이의 거리예요.","밑변과 수직으로 만나는 선분을 찾아요 — 직각 표시가 있어요.","그래서 높이는 선분 ㅁㅂ이에요. 이웃한 변은 비스듬해 높이가 아니에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[30,15],"ㄴ":[15,75],"ㄷ":[105,75],"ㄹ":[120,15],"ㅂ":[75,15],"ㅁ":[75,75]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㅁ","ㅂ"]],"right":[["ㅂ","ㅁ","ㄷ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_basic#6','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',2,'mc','auto','밑변 7 cm, 이웃한 변 5 cm, 높이 4 cm인 평행사변형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X09','M5-1-u6-X10','M5-1-u6-X01']::text[],true,'{"seq":6,"concept":"M5-1-u6-C7","difficulty":2,"kind":"mc","stem":"밑변 7 cm, 이웃한 변 5 cm, 높이 4 cm인 평행사변형의 넓이는 몇 cm²인가요?","options":[{"t":"28 cm²","correct":true},{"t":"35 cm²","mis":"M5-1-u6-X09"},{"t":"14 cm²","mis":"M5-1-u6-X10"},{"t":"24 cm²","mis":"M5-1-u6-X01"}],"explanation":["넓이에는 이웃한 변이 아니라 높이를 써요.","잘라 옮긴 직사각형의 세로가 높이 4 cm이기 때문이에요.","7 × 4 = 28 — 넓이는 28 cm²예요."],"variant_rule":{"alt":[{"stem":"밑변 9 cm, 이웃한 변 6 cm, 높이 5 cm인 평행사변형의 넓이는 몇 cm²인가요?","options":[{"t":"45 cm²","correct":true},{"t":"54 cm²","mis":"M5-1-u6-X09"},{"t":"30 cm²","mis":"M5-1-u6-X01"},{"t":"50 cm²","mis":"M5-1-u6-X16"}],"explanation":["넓이에는 이웃한 변이 아니라 높이를 써요.","잘라 옮긴 직사각형의 세로가 높이 5 cm이기 때문이에요.","9 × 5 = 45 — 넓이는 45 cm²예요."]},{"stem":"밑변 8 cm, 이웃한 변 7 cm, 높이 6 cm인 평행사변형의 넓이는 몇 cm²인가요?","options":[{"t":"48 cm²","correct":true},{"t":"56 cm²","mis":"M5-1-u6-X09"},{"t":"24 cm²","mis":"M5-1-u6-X10"},{"t":"30 cm²","mis":"M5-1-u6-X01"}],"explanation":["넓이에는 이웃한 변이 아니라 높이를 써요.","잘라 옮긴 직사각형의 세로가 높이 6 cm이기 때문이에요.","8 × 6 = 48 — 넓이는 48 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_basic#7','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',2,'sa','auto','넓이가 21 m²인 평행사변형의 밑변이 7 m예요. 높이는 몇 m인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C7","difficulty":2,"kind":"sa","stem":"넓이가 21 m²인 평행사변형의 밑변이 7 m예요. 높이는 몇 m인가요?","answer":["3"],"explanation":["(밑변의 길이) × (높이) = (넓이)예요.","7 × □ = 21이니 □ = 21 ÷ 7이에요.","21 ÷ 7 = 3 — 높이는 3 m예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"넓이가 48 cm²인 평행사변형의 밑변이 8 cm예요. 높이는 몇 cm인가요?","answer":["6"],"explanation":["(밑변의 길이) × (높이) = (넓이)예요.","8 × □ = 48이니 □ = 48 ÷ 8이에요.","48 ÷ 8 = 6 — 높이는 6 cm예요."]},{"stem":"넓이가 56 cm²인 평행사변형의 밑변이 7 cm예요. 높이는 몇 cm인가요?","answer":["8"],"explanation":["(밑변의 길이) × (높이) = (넓이)예요.","7 × □ = 56이니 □ = 56 ÷ 7이에요.","56 ÷ 7 = 8 — 높이는 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_basic#8','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',2,'mc','auto','넓이가 더 넓은 평행사변형은 어느 것인가요? ㉠ 밑변 7 cm, 높이 5 cm ㉡ 밑변 6 cm, 높이 6 cm',ARRAY['M5-1-u6-X16','M5-1-u6-X09']::text[],true,'{"seq":8,"concept":"M5-1-u6-C7","difficulty":2,"kind":"mc","stem":"넓이가 더 넓은 평행사변형은 어느 것인가요? ㉠ 밑변 7 cm, 높이 5 cm ㉡ 밑변 6 cm, 높이 6 cm","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-1-u6-X16"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X16"},{"t":"알 수 없다","mis":"M5-1-u6-X09"}],"explanation":["㉠의 넓이는 7 × 5 = 35예요.","㉡의 넓이는 6 × 6 = 36이에요.","㉡의 넓이가 더 넓어요."],"variant_rule":{"alt":[{"stem":"넓이가 더 넓은 평행사변형은 어느 것인가요? ㉠ 밑변 8 cm, 높이 3 cm ㉡ 밑변 6 cm, 높이 4 cm","options":[{"t":"두 넓이가 같다","correct":true},{"t":"㉠","mis":"M5-1-u6-X16"},{"t":"㉡","mis":"M5-1-u6-X16"},{"t":"알 수 없다","mis":"M5-1-u6-X09"}],"explanation":["㉠의 넓이는 8 × 3 = 24예요.","㉡의 넓이는 6 × 4 = 24예요.","두 넓이는 같아요."]},{"stem":"넓이가 더 넓은 평행사변형은 어느 것인가요? ㉠ 밑변 9 cm, 높이 5 cm ㉡ 밑변 7 cm, 높이 6 cm","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M5-1-u6-X16"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X16"},{"t":"알 수 없다","mis":"M5-1-u6-X09"}],"explanation":["㉠의 넓이는 9 × 5 = 45예요.","㉡의 넓이는 7 × 6 = 42예요.","㉠의 넓이가 더 넓어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_basic#9','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',2,'ox','auto','밑변의 길이와 높이가 같은 평행사변형은 모양이 달라도 넓이가 모두 같아요.',ARRAY['M5-1-u6-X02']::text[],true,'{"seq":9,"concept":"M5-1-u6-C7","difficulty":2,"kind":"ox","stem":"밑변의 길이와 높이가 같은 평행사변형은 모양이 달라도 넓이가 모두 같아요.","answer":"O","reason_options":[{"t":"넓이는 (밑변) × (높이)로만 정해지므로","correct":true},{"t":"평행사변형은 모두 모양이 같으므로","mis":"M5-1-u6-X02"}],"mis":"M5-1-u6-X02","explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변과 높이가 같으면 곱도 같아요.","그래서 기울어진 정도가 달라도 넓이는 같아요."],"variant_rule":{"alt":[{"stem":"평행사변형의 넓이는 밑변과 이웃한 변을 곱해서 구해요.","answer":"X","reason_options":[{"t":"잘라 옮긴 직사각형의 세로는 이웃한 변이 아니라 높이이므로","correct":true},{"t":"이웃한 변과 높이는 늘 같은 길이이므로","mis":"M5-1-u6-X09"}],"explanation":["평행사변형을 잘라 옮기면 직사각형이 돼요.","그 직사각형의 세로는 비스듬한 이웃한 변이 아니라 높이예요.","그래서 (밑변) × (높이)로 구해요."]},{"stem":"평행사변형의 높이는 언제나 이웃한 변보다 짧거나 같아요.","answer":"O","reason_options":[{"t":"높이는 두 밑변 사이의 가장 짧은 거리이므로","correct":true},{"t":"높이는 늘 밑변보다 길므로","mis":"M5-1-u6-X11"}],"explanation":["높이는 밑변에 수직으로 잰 거리예요.","비스듬한 이웃한 변은 같은 두 밑변을 잇지만 수직 거리보다 길어요.","직사각형처럼 수직이면 이웃한 변과 높이가 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_basic#10','math',5,1,'u6','L07','g5_1_math_u6_L07_basic','lesson_basic','M5-1-u6-C7',3,'mc','auto','평행사변형의 넓이가 (밑변의 길이) × (높이)인 까닭은 무엇인가요?',ARRAY['M5-1-u6-X09','M5-1-u6-X02','M5-1-u6-X10']::text[],true,'{"seq":10,"concept":"M5-1-u6-C7","difficulty":3,"kind":"mc","stem":"평행사변형의 넓이가 (밑변의 길이) × (높이)인 까닭은 무엇인가요?","options":[{"t":"잘라 옮기면 밑변이 가로, 높이가 세로인 직사각형이 되므로","correct":true},{"t":"두 변을 곱하면 언제나 넓이가 나오므로","mis":"M5-1-u6-X09"},{"t":"평행사변형이 직사각형보다 넓어서","mis":"M5-1-u6-X02"},{"t":"대각선으로 똑같이 나누어지므로","mis":"M5-1-u6-X10"}],"explanation":["평행사변형의 한쪽 삼각형 부분을 잘라 반대쪽에 옮겨 붙여요.","그러면 가로 = 밑변, 세로 = 높이인 직사각형이 돼요.","잘라 옮겨도 넓이는 변하지 않으니 (밑변) × (높이)예요."],"variant_rule":{"alt":[{"stem":"평행사변형을 잘라 옮겨 직사각형을 만들었어요. 직사각형의 세로는 평행사변형의 무엇과 같나요?","options":[{"t":"높이","correct":true},{"t":"이웃한 변의 길이","mis":"M5-1-u6-X09"},{"t":"밑변의 길이","mis":"M5-1-u6-X16"},{"t":"대각선의 길이","mis":"M5-1-u6-X11"}],"explanation":["높이를 따라 삼각형을 잘라 반대쪽에 붙여요.","그러면 가로는 밑변, 세로는 높이인 직사각형이 돼요.","그래서 넓이는 (밑변) × (높이)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_challenge#1','math',5,1,'u6','L07','g5_1_math_u6_L07_challenge','lesson_challenge','M5-1-u6-C7',2,'error','auto','계단 난간에서 빠진 평행사변형 판은 밑변 8 cm, 이웃한 변 5 cm, 높이 4 cm예요. 판의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u6-X09','M5-1-u6-X17']::text[],true,'{"seq":1,"concept":"M5-1-u6-C7","difficulty":2,"kind":"error","stem":"계단 난간에서 빠진 평행사변형 판은 밑변 8 cm, 이웃한 변 5 cm, 높이 4 cm예요. 판의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「8 × 5 = 40 cm²야.」","correct":true,"mis_target":"M5-1-u6-X09"},{"t":"도현 — 「잘라 옮기면 가로 8 cm, 세로 4 cm인 직사각형이야.」","mis":"M5-1-u6-X17"},{"t":"하은 — 「8 × 4 = 32 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["잘라 옮긴 직사각형의 세로는 높이 4 cm예요.","넓이는 8 × 4 = 32예요.","서윤은 이웃한 변을 곱해 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"계단 난간에서 빠진 평행사변형 판은 밑변 9 cm, 이웃한 변 6 cm, 높이 5 cm예요. 판의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「9 × 6 = 54 cm²야.」","correct":true,"mis_target":"M5-1-u6-X09"},{"t":"라온 — 「잘라 옮기면 가로 9 cm, 세로 5 cm인 직사각형이야.」","mis":"M5-1-u6-X17"},{"t":"예준 — 「9 × 5 = 45 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["잘라 옮긴 직사각형의 세로는 높이 5 cm예요.","넓이는 9 × 5 = 45예요.","지민은 이웃한 변을 곱해 잘못 말했어요."]},{"stem":"계단 난간에서 빠진 평행사변형 판은 밑변 7 cm, 이웃한 변 6 cm, 높이 4 cm예요. 판의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「7 × 6 = 42 cm²야.」","correct":true,"mis_target":"M5-1-u6-X09"},{"t":"유진 — 「잘라 옮기면 가로 7 cm, 세로 4 cm인 직사각형이야.」","mis":"M5-1-u6-X17"},{"t":"민준 — 「7 × 4 = 28 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["잘라 옮긴 직사각형의 세로는 높이 4 cm예요.","넓이는 7 × 4 = 28이에요.","가온은 이웃한 변을 곱해 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_challenge#2','math',5,1,'u6','L07','g5_1_math_u6_L07_challenge','lesson_challenge','M5-1-u6-C7',2,'mc','auto','모눈 한 칸은 1 cm²예요. 넓이가 다른 평행사변형은 어느 것인가요?',ARRAY['M5-1-u6-X09']::text[],true,'{"seq":2,"concept":"M5-1-u6-C7","difficulty":2,"kind":"mc","stem":"모눈 한 칸은 1 cm²예요. 넓이가 다른 평행사변형은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M5-1-u6-X09"},{"t":"㉯","mis":"M5-1-u6-X09"},{"t":"㉰","mis":"M5-1-u6-X09"}],"explanation":["평행사변형의 넓이는 (밑변) × (높이)예요 — 모눈에서 밑변 칸 수와 높이 칸 수를 세어요.","㉮ 12 cm², ㉯ 12 cm², ㉰ 12 cm², ㉱ 15 cm²예요.","기울기가 달라도 밑변과 높이가 같으면 넓이가 같아요 — 다른 하나는 ㉱예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,60],[75,60],[90,15],[30,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,60],[75,60],[105,15],[45,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[30,60],[90,60],[90,15],[30,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,60],[90,60],[105,15],[30,15]]],"show":[]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 넓이가 다른 평행사변형은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-1-u6-X09"},{"t":"㉰","mis":"M5-1-u6-X09"},{"t":"㉱","mis":"M5-1-u6-X09"}],"explanation":["평행사변형의 넓이는 (밑변) × (높이)예요 — 모눈에서 밑변 칸 수와 높이 칸 수를 세어요.","㉮ 12 cm², ㉯ 16 cm², ㉰ 12 cm², ㉱ 12 cm²예요.","기울기가 달라도 밑변과 높이가 같으면 넓이가 같아요 — 다른 하나는 ㉯예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,75],[60,75],[90,15],[45,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,75],[75,75],[90,15],[30,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,75],[60,75],[60,15],[15,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[30,75],[75,75],[120,15],[75,15]]],"show":[]}]}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 넓이가 다른 평행사변형은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M5-1-u6-X09"},{"t":"㉰","mis":"M5-1-u6-X09"},{"t":"㉱","mis":"M5-1-u6-X09"}],"explanation":["평행사변형의 넓이는 (밑변) × (높이)예요 — 모눈에서 밑변 칸 수와 높이 칸 수를 세어요.","㉮ 10 cm², ㉯ 15 cm², ㉰ 15 cm², ㉱ 15 cm²예요.","기울기가 달라도 밑변과 높이가 같으면 넓이가 같아요 — 다른 하나는 ㉮예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,60],[90,60],[105,30],[30,30]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,60],[90,60],[120,15],[45,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[30,60],[105,60],[90,15],[15,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,60],[90,60],[90,15],[15,15]]],"show":[]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_challenge#3','math',5,1,'u6','L07','g5_1_math_u6_L07_challenge','lesson_challenge','M5-1-u6-C7',3,'sa','auto','밑변 12 cm, 높이 5 cm인 평행사변형이 있어요. 길이가 10 cm인 이웃한 변을 밑변으로 하면 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":3,"concept":"M5-1-u6-C7","difficulty":3,"kind":"sa","stem":"밑변 12 cm, 높이 5 cm인 평행사변형이 있어요. 길이가 10 cm인 이웃한 변을 밑변으로 하면 높이는 몇 cm인가요?","answer":["6"],"explanation":["넓이는 밑변을 어느 쪽으로 정해도 같아요 — 12 × 5 = 60이에요.","새 밑변 10 cm로 □ × 10 = 60이에요.","60 ÷ 10 = 6 — 높이는 6 cm예요."],"mis":"M5-1-u6-X11","variant_rule":{"alt":[{"stem":"밑변 15 cm, 높이 4 cm인 평행사변형이 있어요. 길이가 12 cm인 이웃한 변을 밑변으로 하면 높이는 몇 cm인가요?","answer":["5"],"explanation":["넓이는 밑변을 어느 쪽으로 정해도 같아요 — 15 × 4 = 60이에요.","새 밑변 12 cm로 □ × 12 = 60이에요.","60 ÷ 12 = 5 — 높이는 5 cm예요."]},{"stem":"밑변 16 cm, 높이 6 cm인 평행사변형이 있어요. 길이가 12 cm인 이웃한 변을 밑변으로 하면 높이는 몇 cm인가요?","answer":["8"],"explanation":["넓이는 밑변을 어느 쪽으로 정해도 같아요 — 16 × 6 = 96이에요.","새 밑변 12 cm로 □ × 12 = 96이에요.","96 ÷ 12 = 8 — 높이는 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_challenge#4','math',5,1,'u6','L07','g5_1_math_u6_L07_challenge','lesson_challenge','M5-1-u6-C7',3,'sa','auto','둘레가 30 cm인 평행사변형의 이웃한 변이 6 cm이고, 다른 변을 밑변으로 한 높이가 4 cm예요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C7","difficulty":3,"kind":"sa","stem":"둘레가 30 cm인 평행사변형의 이웃한 변이 6 cm이고, 다른 변을 밑변으로 한 높이가 4 cm예요. 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["밑변 + 이웃한 변 = 30 ÷ 2 = 15예요.","밑변 = 15 − 6 = 9예요.","넓이 = 9 × 4 = 36 — 36 cm²예요."],"mis":"M5-1-u6-X04","variant_rule":{"alt":[{"stem":"둘레가 34 cm인 평행사변형의 이웃한 변이 7 cm이고, 다른 변을 밑변으로 한 높이가 5 cm예요. 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["밑변 + 이웃한 변 = 34 ÷ 2 = 17이에요.","밑변 = 17 − 7 = 10이에요.","넓이 = 10 × 5 = 50 — 50 cm²예요."]},{"stem":"둘레가 28 cm인 평행사변형의 이웃한 변이 5 cm이고, 다른 변을 밑변으로 한 높이가 6 cm예요. 넓이는 몇 cm²인가요?","answer":["54"],"explanation":["밑변 + 이웃한 변 = 28 ÷ 2 = 14예요.","밑변 = 14 − 5 = 9예요.","넓이 = 9 × 6 = 54 — 54 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_challenge#5','math',5,1,'u6','L07','g5_1_math_u6_L07_challenge','lesson_challenge','M5-1-u6-C7',3,'mc','auto','평행사변형의 높이는 그대로 두고 밑변만 2배로 늘리면 넓이는 몇 배가 되나요?',ARRAY['M5-1-u6-X07','M5-1-u6-X09','M5-1-u6-X16']::text[],true,'{"seq":5,"concept":"M5-1-u6-C7","difficulty":3,"kind":"mc","stem":"평행사변형의 높이는 그대로 두고 밑변만 2배로 늘리면 넓이는 몇 배가 되나요?","options":[{"t":"2배","correct":true},{"t":"4배","mis":"M5-1-u6-X07"},{"t":"그대로","mis":"M5-1-u6-X09"},{"t":"3배","mis":"M5-1-u6-X16"}],"explanation":["넓이 = (밑변) × (높이)예요.","밑변만 2배면 곱도 2배가 돼요.","예: 6 × 4 = 24, 12 × 4 = 48 — 2배예요."],"variant_rule":{"alt":[{"stem":"평행사변형의 밑변과 높이를 모두 2배로 늘리면 넓이는 몇 배가 되나요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M5-1-u6-X07"},{"t":"8배","mis":"M5-1-u6-X16"},{"t":"그대로","mis":"M5-1-u6-X02"}],"explanation":["넓이 = (밑변) × (높이)예요.","밑변 2배, 높이 2배면 2 × 2 = 4배예요.","예: 5 × 3 = 15, 10 × 6 = 60 — 4배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_challenge#6','math',5,1,'u6','L07','g5_1_math_u6_L07_challenge','lesson_challenge','M5-1-u6-C7',3,'sa','auto','모눈 한 칸은 1 cm²예요. 그림에서 색칠한 평행사변형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-1-u6-C7","difficulty":3,"kind":"sa","stem":"모눈 한 칸은 1 cm²예요. 그림에서 색칠한 평행사변형의 넓이는 몇 cm²인가요?","answer":["20"],"explanation":["평행사변형의 넓이는 (밑변) × (높이)예요.","모눈에서 밑변은 5칸, 높이는 4칸이에요 — 비스듬한 변의 칸이 아니라 위아래 거리를 세요.","5 × 4 = 20 — 넓이는 20 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,75],[90,75],[120,15],[45,15]]],"show":[]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 평행사변형의 넓이는 몇 cm²인가요?","answer":["18"],"explanation":["평행사변형의 넓이는 (밑변) × (높이)예요.","모눈에서 밑변은 6칸, 높이는 3칸이에요 — 비스듬한 변의 칸이 아니라 위아래 거리를 세요.","6 × 3 = 18 — 넓이는 18 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[30,75],[120,75],[105,30],[15,30]]],"show":[]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 평행사변형의 넓이는 몇 cm²인가요?","answer":["21"],"explanation":["평행사변형의 넓이는 (밑변) × (높이)예요.","모눈에서 밑변은 7칸, 높이는 3칸이에요 — 비스듬한 변의 칸이 아니라 위아래 거리를 세요.","7 × 3 = 21 — 넓이는 21 cm²예요."],"asset":{"type":"geo","items":[{"w":150,"h":75,"grid":15,"poly":[[[15,60],[120,60],[135,15],[30,15]]],"show":[]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_challenge#7','math',5,1,'u6','L07','g5_1_math_u6_L07_challenge','lesson_challenge','M5-1-u6-C7',3,'mc','auto','가로 9 cm, 세로 4 cm인 직사각형과 넓이가 같고 밑변이 12 cm인 평행사변형의 높이는 몇 cm인가요?',ARRAY['M5-1-u6-X14','M5-1-u6-X16']::text[],true,'{"seq":7,"concept":"M5-1-u6-C7","difficulty":3,"kind":"mc","stem":"가로 9 cm, 세로 4 cm인 직사각형과 넓이가 같고 밑변이 12 cm인 평행사변형의 높이는 몇 cm인가요?","options":[{"t":"3 cm","correct":true},{"t":"36 cm","mis":"M5-1-u6-X14"},{"t":"24 cm","mis":"M5-1-u6-X14"},{"t":"4 cm","mis":"M5-1-u6-X16"}],"explanation":["직사각형의 넓이는 9 × 4 = 36이에요.","평행사변형도 넓이가 36이니 12 × □ = 36이에요.","36 ÷ 12 = 3 — 높이는 3 cm예요."],"variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 6 cm인 직사각형과 넓이가 같고 밑변이 16 cm인 평행사변형의 높이는 몇 cm인가요?","options":[{"t":"3 cm","correct":true},{"t":"48 cm","mis":"M5-1-u6-X14"},{"t":"32 cm","mis":"M5-1-u6-X14"},{"t":"4 cm","mis":"M5-1-u6-X16"}],"explanation":["직사각형의 넓이는 8 × 6 = 48이에요.","평행사변형도 넓이가 48이니 16 × □ = 48이에요.","48 ÷ 16 = 3 — 높이는 3 cm예요."]},{"stem":"가로 10 cm, 세로 6 cm인 직사각형과 넓이가 같고 밑변이 15 cm인 평행사변형의 높이는 몇 cm인가요?","options":[{"t":"4 cm","correct":true},{"t":"60 cm","mis":"M5-1-u6-X14"},{"t":"45 cm","mis":"M5-1-u6-X14"},{"t":"2 cm","mis":"M5-1-u6-X10"}],"explanation":["직사각형의 넓이는 10 × 6 = 60이에요.","평행사변형도 넓이가 60이니 15 × □ = 60이에요.","60 ÷ 15 = 4 — 높이는 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_challenge#8','math',5,1,'u6','L07','g5_1_math_u6_L07_challenge','lesson_challenge','M5-1-u6-C7',4,'sa','auto','밑변 8 cm, 높이 6 cm인 평행사변형 모양 난간 판 2장을 새로 만들려고 해요. 판의 넓이는 모두 몇 cm²인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C7","difficulty":4,"kind":"sa","stem":"밑변 8 cm, 높이 6 cm인 평행사변형 모양 난간 판 2장을 새로 만들려고 해요. 판의 넓이는 모두 몇 cm²인가요?","answer":["96"],"explanation":["판 한 장의 넓이는 8 × 6 = 48이에요.","2장이니 48 × 2예요.","48 × 2 = 96 — 모두 96 cm²예요."],"variant_rule":{"alt":[{"stem":"밑변 7 cm, 높이 5 cm인 평행사변형 모양 난간 판 2장을 새로 만들려고 해요. 판의 넓이는 모두 몇 cm²인가요?","answer":["70"],"explanation":["판 한 장의 넓이는 7 × 5 = 35예요.","2장이니 35 × 2예요.","35 × 2 = 70 — 모두 70 cm²예요."]},{"stem":"밑변 9 cm, 높이 5 cm인 평행사변형 모양 난간 판 2장을 새로 만들려고 해요. 판의 넓이는 모두 몇 cm²인가요?","answer":["90"],"explanation":["판 한 장의 넓이는 9 × 5 = 45예요.","2장이니 45 × 2예요.","45 × 2 = 90 — 모두 90 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_challenge#9','math',5,1,'u6','L07','g5_1_math_u6_L07_challenge','lesson_challenge','M5-1-u6-C7',4,'sa','auto','가로 12 m, 세로 8 m인 직사각형 밭 가운데로 밑변 2 m인 평행사변형 모양 길이 위에서 아래까지 비스듬히 나 있어요(길의 높이는 밭의 세로와 같아요). 길을 뺀 밭의 넓이는 몇 m²인가요?','{}'::text[],true,'{"seq":9,"concept":"M5-1-u6-C7","difficulty":4,"kind":"sa","stem":"가로 12 m, 세로 8 m인 직사각형 밭 가운데로 밑변 2 m인 평행사변형 모양 길이 위에서 아래까지 비스듬히 나 있어요(길의 높이는 밭의 세로와 같아요). 길을 뺀 밭의 넓이는 몇 m²인가요?","answer":["80"],"explanation":["밭 전체는 12 × 8 = 96이에요.","길은 밑변 2, 높이 8인 평행사변형이라 2 × 8 = 16이에요.","96 − 16 = 80 — 남은 밭은 80 m²예요."],"mis":"M5-1-u6-X15","variant_rule":{"alt":[{"stem":"가로 10 m, 세로 9 m인 직사각형 밭 가운데로 밑변 3 m인 평행사변형 모양 길이 위에서 아래까지 비스듬히 나 있어요(길의 높이는 밭의 세로와 같아요). 길을 뺀 밭의 넓이는 몇 m²인가요?","answer":["63"],"explanation":["밭 전체는 10 × 9 = 90이에요.","길은 밑변 3, 높이 9인 평행사변형이라 3 × 9 = 27이에요.","90 − 27 = 63 — 남은 밭은 63 m²예요."]},{"stem":"가로 11 m, 세로 7 m인 직사각형 밭 가운데로 밑변 2 m인 평행사변형 모양 길이 위에서 아래까지 비스듬히 나 있어요(길의 높이는 밭의 세로와 같아요). 길을 뺀 밭의 넓이는 몇 m²인가요?","answer":["63"],"explanation":["밭 전체는 11 × 7 = 77이에요.","길은 밑변 2, 높이 7인 평행사변형이라 2 × 7 = 14예요.","77 − 14 = 63 — 남은 밭은 63 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L07_challenge#10','math',5,1,'u6','L07','g5_1_math_u6_L07_challenge','lesson_challenge','M5-1-u6-C7',4,'essay','teacher','밑변 7 cm, 이웃한 변 5 cm, 높이 4 cm인 평행사변형의 넓이를 7 × 5로 구하면 안 되는 까닭을 설명하고, 바른 넓이를 구하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u6-C7","difficulty":4,"kind":"essay","stem":"밑변 7 cm, 이웃한 변 5 cm, 높이 4 cm인 평행사변형의 넓이를 7 × 5로 구하면 안 되는 까닭을 설명하고, 바른 넓이를 구하세요.","answer_guide":{"answer":"예: 평행사변형을 높이를 따라 잘라 반대쪽에 붙이면 가로가 밑변 7 cm, 세로가 높이 4 cm인 직사각형이 된다. 세로는 비스듬한 이웃한 변 5 cm가 아니라 높이 4 cm이므로 7 × 4 = 28, 넓이는 28 cm²이다.","scoring_points":["잘라 옮기면 직사각형이 된다고 썼는가","직사각형의 세로가 이웃한 변이 아니라 높이라고 썼는가","7 × 4 = 28 cm²를 바르게 구했는가"]},"explanation":["잘라 옮기면 직사각형이 돼요.","그 직사각형의 세로는 높이 4 cm예요.","7 × 4 = 28 — 넓이는 28 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_basic#1','math',5,1,'u6','L08','g5_1_math_u6_L08_basic','lesson_basic','M5-1-u6-C8',1,'mc','auto','삼각형의 넓이를 구하는 식은 어느 것인가요?',ARRAY['M5-1-u6-X10','M5-1-u6-X01']::text[],true,'{"seq":1,"concept":"M5-1-u6-C8","difficulty":1,"kind":"mc","stem":"삼각형의 넓이를 구하는 식은 어느 것인가요?","options":[{"t":"(밑변의 길이) × (높이) ÷ 2","correct":true},{"t":"(밑변) × (높이)","mis":"M5-1-u6-X10"},{"t":"(밑변 + 높이) ÷ 2","mis":"M5-1-u6-X01"},{"t":"(밑변) × (높이) × 2","mis":"M5-1-u6-X10"}],"explanation":["똑같은 삼각형 두 개를 붙이면 평행사변형(또는 직사각형)이 돼요.","그 넓이가 (밑변) × (높이)예요.","삼각형은 그 절반이라 ÷ 2를 해요."],"variant_rule":{"alt":[{"stem":"삼각형에서 높이란 무엇인가요?","options":[{"t":"밑변과 마주 보는 꼭짓점에서 밑변에 수직으로 그은 선분의 길이","correct":true},{"t":"가장 긴 변의 길이","mis":"M5-1-u6-X11"},{"t":"밑변과 이웃한 변의 길이","mis":"M5-1-u6-X11"},{"t":"꼭짓점에서 밑변의 가운데까지 그은 선분의 길이","mis":"M5-1-u6-X11"}],"explanation":["삼각형의 한 변을 밑변으로 정해요.","마주 보는 꼭짓점에서 밑변에 수직으로 그은 선분의 길이가 높이예요.","밑변을 바꾸면 높이도 바뀌어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_basic#2','math',5,1,'u6','L08','g5_1_math_u6_L08_basic','lesson_basic','M5-1-u6-C8',1,'sa','auto','밑변이 8 cm, 높이가 5 cm인 삼각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C8","difficulty":1,"kind":"sa","stem":"밑변이 8 cm, 높이가 5 cm인 삼각형의 넓이는 몇 cm²인가요?","answer":["20"],"explanation":["삼각형의 넓이는 (밑변의 길이) × (높이) ÷ 2예요.","8 × 5 = 40은 평행사변형 전체예요.","40 ÷ 2 = 20 — 넓이는 20 cm²예요."],"variant_rule":{"alt":[{"stem":"밑변이 6 cm, 높이가 9 cm인 삼각형의 넓이는 몇 cm²인가요?","answer":["27"],"explanation":["삼각형의 넓이는 (밑변의 길이) × (높이) ÷ 2예요.","6 × 9 = 54는 평행사변형 전체예요.","54 ÷ 2 = 27 — 넓이는 27 cm²예요."]},{"stem":"밑변이 10 cm, 높이가 7 cm인 삼각형의 넓이는 몇 cm²인가요?","answer":["35"],"explanation":["삼각형의 넓이는 (밑변의 길이) × (높이) ÷ 2예요.","10 × 7 = 70은 평행사변형 전체예요.","70 ÷ 2 = 35 — 넓이는 35 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_basic#3','math',5,1,'u6','L08','g5_1_math_u6_L08_basic','lesson_basic','M5-1-u6-C8',1,'mc','auto','밑변이 6 cm, 높이가 4 cm인 삼각형 모양 연을 만들었어요. 연의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X10','M5-1-u6-X01']::text[],true,'{"seq":3,"concept":"M5-1-u6-C8","difficulty":1,"kind":"mc","stem":"밑변이 6 cm, 높이가 4 cm인 삼각형 모양 연을 만들었어요. 연의 넓이는 몇 cm²인가요?","options":[{"t":"12 cm²","correct":true},{"t":"24 cm²","mis":"M5-1-u6-X10"},{"t":"5 cm²","mis":"M5-1-u6-X01"},{"t":"10 cm²","mis":"M5-1-u6-X01"}],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","6 × 4 = 24예요.","24 ÷ 2 = 12 — 넓이는 12 cm²예요. ÷ 2를 빠뜨리면 두 배가 돼요."],"variant_rule":{"alt":[{"stem":"밑변이 10 cm, 높이가 6 cm인 삼각형 모양 연을 만들었어요. 연의 넓이는 몇 cm²인가요?","options":[{"t":"30 cm²","correct":true},{"t":"60 cm²","mis":"M5-1-u6-X10"},{"t":"8 cm²","mis":"M5-1-u6-X01"},{"t":"16 cm²","mis":"M5-1-u6-X01"}],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","10 × 6 = 60이에요.","60 ÷ 2 = 30 — 넓이는 30 cm²예요. ÷ 2를 빠뜨리면 두 배가 돼요."]},{"stem":"밑변이 12 cm, 높이가 5 cm인 삼각형 모양 연을 만들었어요. 연의 넓이는 몇 cm²인가요?","options":[{"t":"30 cm²","correct":true},{"t":"60 cm²","mis":"M5-1-u6-X10"},{"t":"17 cm²","mis":"M5-1-u6-X01"},{"t":"42 cm²","mis":"M5-1-u6-X16"}],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","12 × 5 = 60이에요.","60 ÷ 2 = 30 — 넓이는 30 cm²예요. ÷ 2를 빠뜨리면 두 배가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_basic#4','math',5,1,'u6','L08','g5_1_math_u6_L08_basic','lesson_basic','M5-1-u6-C8',1,'sa','auto','밑변이 12 cm, 높이가 7 cm인 삼각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C8","difficulty":1,"kind":"sa","stem":"밑변이 12 cm, 높이가 7 cm인 삼각형의 넓이는 몇 cm²인가요?","answer":["42"],"explanation":["삼각형의 넓이는 (밑변의 길이) × (높이) ÷ 2예요.","12 × 7 = 84는 평행사변형 전체예요.","84 ÷ 2 = 42 — 넓이는 42 cm²예요."],"variant_rule":{"alt":[{"stem":"밑변이 14 m, 높이가 5 m인 삼각형의 넓이는 몇 m²인가요?","answer":["35"],"explanation":["삼각형의 넓이는 (밑변의 길이) × (높이) ÷ 2예요.","14 × 5 = 70은 평행사변형 전체예요.","70 ÷ 2 = 35 — 넓이는 35 m²예요."]},{"stem":"밑변이 9 cm, 높이가 8 cm인 삼각형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["삼각형의 넓이는 (밑변의 길이) × (높이) ÷ 2예요.","9 × 8 = 72는 평행사변형 전체예요.","72 ÷ 2 = 36 — 넓이는 36 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_basic#5','math',5,1,'u6','L08','g5_1_math_u6_L08_basic','lesson_basic','M5-1-u6-C8',2,'mc','auto','삼각형 ㄱㄴㄷ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 것은 어느 것인가요?',ARRAY['M5-1-u6-X11','M5-1-u6-X17']::text[],true,'{"seq":5,"concept":"M5-1-u6-C8","difficulty":2,"kind":"mc","stem":"삼각형 ㄱㄴㄷ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 것은 어느 것인가요?","options":[{"t":"선분 ㄱㄹ","correct":true},{"t":"선분 ㄱㄴ","mis":"M5-1-u6-X11"},{"t":"선분 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"선분 ㄱㄷ","mis":"M5-1-u6-X11"}],"explanation":["밑변과 마주 보는 꼭짓점 ㄱ에서 밑변에 수직으로 그은 선분이 높이예요.","높이는 삼각형 안에 있어요.","그래서 높이는 선분 ㄱㄹ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[60,15],"ㄴ":[15,75],"ㄷ":[120,75],"ㄹ":[60,75]},"poly":[["ㄱ","ㄴ","ㄷ"]],"seg":[["ㄱ","ㄹ"]],"right":[["ㄱ","ㄹ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 삼각형 ㄱㄴㄷ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 것은 어느 것인가요?","options":[{"t":"선분 ㄱㄹ","correct":true},{"t":"선분 ㄱㄷ","mis":"M5-1-u6-X11"},{"t":"선분 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"선분 ㄱㄴ","mis":"M5-1-u6-X11"}],"explanation":["밑변과 마주 보는 꼭짓점 ㄱ에서 밑변에 수직으로 그은 선분이 높이예요.","꼭짓점 ㄱ이 밑변 바깥쪽 위에 있어 밑변을 늘인 선에 수직으로 내려요 — 높이가 삼각형 밖에 있어요.","그래서 높이는 선분 ㄱㄹ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[120,15],"ㄴ":[15,75],"ㄷ":[75,75],"ㄹ":[120,75]},"poly":[["ㄱ","ㄴ","ㄷ"]],"seg":[["ㄱ","ㄹ"],["ㄷ","ㄹ"]],"right":[["ㄱ","ㄹ","ㄴ"]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 삼각형 ㄱㄴㄷ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 것은 어느 것인가요?","options":[{"t":"선분 ㄱㄹ","correct":true},{"t":"선분 ㄱㄴ","mis":"M5-1-u6-X11"},{"t":"선분 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"선분 ㄱㄷ","mis":"M5-1-u6-X11"}],"explanation":["밑변과 마주 보는 꼭짓점 ㄱ에서 밑변에 수직으로 그은 선분이 높이예요.","꼭짓점 ㄱ이 밑변 바깥쪽 위에 있어 밑변을 늘인 선에 수직으로 내려요 — 높이가 삼각형 밖에 있어요.","그래서 높이는 선분 ㄱㄹ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[15,15],"ㄴ":[60,75],"ㄷ":[135,75],"ㄹ":[15,75]},"poly":[["ㄱ","ㄴ","ㄷ"]],"seg":[["ㄱ","ㄹ"],["ㄴ","ㄹ"]],"right":[["ㄱ","ㄹ","ㄷ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_basic#6','math',5,1,'u6','L08','g5_1_math_u6_L08_basic','lesson_basic','M5-1-u6-C8',2,'mc','auto','삼각형의 넓이를 계산한 것 가운데 잘못된 것은 어느 것인가요?',ARRAY['M5-1-u6-X17']::text[],true,'{"seq":6,"concept":"M5-1-u6-C8","difficulty":2,"kind":"mc","stem":"삼각형의 넓이를 계산한 것 가운데 잘못된 것은 어느 것인가요?","options":[{"t":"밑변 5 cm · 높이 8 cm → 40 cm²","correct":true},{"t":"밑변 4 cm · 높이 6 cm → 12 cm²","mis":"M5-1-u6-X17"},{"t":"밑변 10 cm · 높이 3 cm → 15 cm²","mis":"M5-1-u6-X17"},{"t":"밑변 9 cm · 높이 2 cm → 9 cm²","mis":"M5-1-u6-X17"}],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","4 × 6 ÷ 2 = 12, 10 × 3 ÷ 2 = 15, 9 × 2 ÷ 2 = 9, 5 × 8 ÷ 2 = 20이에요.","밑변 5 cm · 높이 8 cm는 ÷ 2를 빠뜨렸어요 — 바른 값은 20 cm²예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 삼각형의 넓이를 계산한 것 가운데 잘못된 것은 어느 것인가요?","options":[{"t":"밑변 6 cm · 높이 4 cm → 24 cm²","correct":true},{"t":"밑변 8 cm · 높이 3 cm → 12 cm²","mis":"M5-1-u6-X17"},{"t":"밑변 5 cm · 높이 6 cm → 15 cm²","mis":"M5-1-u6-X17"},{"t":"밑변 7 cm · 높이 2 cm → 7 cm²","mis":"M5-1-u6-X17"}],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","6 × 4 ÷ 2 = 12, 8 × 3 ÷ 2 = 12, 5 × 6 ÷ 2 = 15, 7 × 2 ÷ 2 = 7이에요.","밑변 6 cm · 높이 4 cm는 ÷ 2를 빠뜨렸어요 — 바른 값은 12 cm²예요."]},{"stem":"이번에는 다른 보기예요. 삼각형의 넓이를 계산한 것 가운데 잘못된 것은 어느 것인가요?","options":[{"t":"밑변 9 cm · 높이 4 cm → 36 cm²","correct":true},{"t":"밑변 3 cm · 높이 8 cm → 12 cm²","mis":"M5-1-u6-X17"},{"t":"밑변 12 cm · 높이 2 cm → 12 cm²","mis":"M5-1-u6-X17"},{"t":"밑변 6 cm · 높이 5 cm → 15 cm²","mis":"M5-1-u6-X17"}],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","3 × 8 ÷ 2 = 12, 12 × 2 ÷ 2 = 12, 6 × 5 ÷ 2 = 15, 9 × 4 ÷ 2 = 18이에요.","밑변 9 cm · 높이 4 cm는 ÷ 2를 빠뜨렸어요 — 바른 값은 18 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_basic#7','math',5,1,'u6','L08','g5_1_math_u6_L08_basic','lesson_basic','M5-1-u6-C8',2,'sa','auto','넓이가 30 cm²인 삼각형의 밑변이 10 cm예요. 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C8","difficulty":2,"kind":"sa","stem":"넓이가 30 cm²인 삼각형의 밑변이 10 cm예요. 높이는 몇 cm인가요?","answer":["6"],"explanation":["(밑변) × (높이) ÷ 2 = 30이니 (밑변) × (높이) = 30 × 2 = 60이에요.","10 × □ = 60이니 □ = 60 ÷ 10이에요.","60 ÷ 10 = 6 — 높이는 6 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"넓이가 36 cm²인 삼각형의 밑변이 9 cm예요. 높이는 몇 cm인가요?","answer":["8"],"explanation":["(밑변) × (높이) ÷ 2 = 36이니 (밑변) × (높이) = 36 × 2 = 72예요.","9 × □ = 72니 □ = 72 ÷ 9예요.","72 ÷ 9 = 8 — 높이는 8 cm예요."]},{"stem":"넓이가 35 cm²인 삼각형의 밑변이 7 cm예요. 높이는 몇 cm인가요?","answer":["10"],"explanation":["(밑변) × (높이) ÷ 2 = 35니 (밑변) × (높이) = 35 × 2 = 70이에요.","7 × □ = 70이니 □ = 70 ÷ 7이에요.","70 ÷ 7 = 10 — 높이는 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_basic#8','math',5,1,'u6','L08','g5_1_math_u6_L08_basic','lesson_basic','M5-1-u6-C8',2,'mc','auto','㉠ 밑변 8 cm, 높이 3 cm인 삼각형과 ㉡ 밑변 6 cm, 높이 4 cm인 삼각형의 넓이를 비교하면 어떠한가요?',ARRAY['M5-1-u6-X16','M5-1-u6-X11']::text[],true,'{"seq":8,"concept":"M5-1-u6-C8","difficulty":2,"kind":"mc","stem":"㉠ 밑변 8 cm, 높이 3 cm인 삼각형과 ㉡ 밑변 6 cm, 높이 4 cm인 삼각형의 넓이를 비교하면 어떠한가요?","options":[{"t":"두 넓이가 같다","correct":true},{"t":"㉠이 더 넓다","mis":"M5-1-u6-X16"},{"t":"㉡이 더 넓다","mis":"M5-1-u6-X16"},{"t":"알 수 없다","mis":"M5-1-u6-X11"}],"explanation":["㉠의 넓이는 8 × 3 ÷ 2 = 12예요.","㉡의 넓이는 6 × 4 ÷ 2 = 12예요.","그래서 두 넓이가 같아요."],"variant_rule":{"alt":[{"stem":"㉠ 밑변 9 cm, 높이 4 cm인 삼각형과 ㉡ 밑변 6 cm, 높이 5 cm인 삼각형의 넓이를 비교하면 어떠한가요?","options":[{"t":"㉠이 더 넓다","correct":true},{"t":"㉡이 더 넓다","mis":"M5-1-u6-X16"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X11"}],"explanation":["㉠의 넓이는 9 × 4 ÷ 2 = 18이에요.","㉡의 넓이는 6 × 5 ÷ 2 = 15예요.","그래서 ㉠이 더 넓어요."]},{"stem":"㉠ 밑변 10 cm, 높이 3 cm인 삼각형과 ㉡ 밑변 7 cm, 높이 4 cm인 삼각형의 넓이를 비교하면 어떠한가요?","options":[{"t":"㉠이 더 넓다","correct":true},{"t":"㉡이 더 넓다","mis":"M5-1-u6-X16"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X02"},{"t":"알 수 없다","mis":"M5-1-u6-X11"}],"explanation":["㉠의 넓이는 10 × 3 ÷ 2 = 15예요.","㉡의 넓이는 7 × 4 ÷ 2 = 14예요.","그래서 ㉠이 더 넓어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_basic#9','math',5,1,'u6','L08','g5_1_math_u6_L08_basic','lesson_basic','M5-1-u6-C8',2,'ox','auto','밑변의 길이와 높이가 같은 삼각형은 모양이 달라도 넓이가 같아요.',ARRAY['M5-1-u6-X11']::text[],true,'{"seq":9,"concept":"M5-1-u6-C8","difficulty":2,"kind":"ox","stem":"밑변의 길이와 높이가 같은 삼각형은 모양이 달라도 넓이가 같아요.","answer":"O","reason_options":[{"t":"넓이는 (밑변) × (높이) ÷ 2로만 정해지므로","correct":true},{"t":"삼각형은 모두 모양이 같으므로","mis":"M5-1-u6-X11"}],"mis":"M5-1-u6-X11","explanation":["삼각형의 넓이는 (밑변의 길이) × (높이) ÷ 2예요.","밑변과 높이가 같으면 값이 같아요.","꼭짓점이 옆으로 움직여도 넓이는 그대로예요."],"variant_rule":{"alt":[{"stem":"직각삼각형만 넓이를 구할 때 2로 나누고, 다른 삼각형은 2로 나누지 않아요.","answer":"X","reason_options":[{"t":"어떤 삼각형이든 똑같은 두 개를 붙이면 평행사변형이 되므로","correct":true},{"t":"직각이 있어야 반으로 나뉘므로","mis":"M5-1-u6-X10"}],"explanation":["어떤 삼각형이든 똑같은 삼각형 두 개를 돌려 붙이면 평행사변형이 돼요.","그래서 모든 삼각형은 (밑변) × (높이)의 절반이에요.","모든 삼각형에 ÷ 2를 해요."]},{"stem":"삼각형의 높이는 삼각형 바깥에 있을 수도 있어요.","answer":"O","reason_options":[{"t":"둔각삼각형은 밑변을 늘인 선에 수직으로 높이를 그리므로","correct":true},{"t":"높이는 언제나 가장 긴 변이므로","mis":"M5-1-u6-X11"}],"explanation":["높이는 꼭짓점에서 밑변(또는 밑변을 늘인 선)에 수직으로 그은 선분이에요.","한 각이 둔각이면 그 선분이 삼각형 밖으로 나가요.","그래도 넓이는 (밑변) × (높이) ÷ 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_basic#10','math',5,1,'u6','L08','g5_1_math_u6_L08_basic','lesson_basic','M5-1-u6-C8',3,'mc','auto','삼각형의 넓이를 구할 때 2로 나누는 까닭은 무엇인가요?',ARRAY['M5-1-u6-X16','M5-1-u6-X11','M5-1-u6-X10']::text[],true,'{"seq":10,"concept":"M5-1-u6-C8","difficulty":3,"kind":"mc","stem":"삼각형의 넓이를 구할 때 2로 나누는 까닭은 무엇인가요?","options":[{"t":"똑같은 삼각형 두 개를 붙이면 평행사변형이 되므로","correct":true},{"t":"삼각형의 변이 3개여서","mis":"M5-1-u6-X16"},{"t":"높이가 밑변보다 짧아서","mis":"M5-1-u6-X11"},{"t":"밑변을 두 번 쓰므로","mis":"M5-1-u6-X10"}],"explanation":["똑같은 삼각형 두 개를 돌려 붙이면 밑변과 높이가 같은 평행사변형이 돼요.","(밑변) × (높이)는 그 평행사변형 전체의 넓이예요.","삼각형은 그 절반이라 2로 나누어요."],"variant_rule":{"alt":[{"stem":"똑같은 삼각형 두 개를 돌려 붙이면 어떤 도형을 만들 수 있나요?","options":[{"t":"밑변과 높이가 같은 평행사변형","correct":true},{"t":"밑변이 2배인 삼각형","mis":"M5-1-u6-X10"},{"t":"한 변이 밑변인 정사각형","mis":"M5-1-u6-X16"},{"t":"넓이가 같은 삼각형","mis":"M5-1-u6-X10"}],"explanation":["똑같은 삼각형 하나를 돌려 붙이면 평행사변형(또는 직사각형)이 돼요.","그 평행사변형의 밑변과 높이는 삼각형과 같아요.","그래서 삼각형은 그 절반 — (밑변) × (높이) ÷ 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_challenge#1','math',5,1,'u6','L08','g5_1_math_u6_L08_challenge','lesson_challenge','M5-1-u6-C8',2,'error','auto','밑변 8 cm, 높이 5 cm인 삼각형의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u6-X10','M5-1-u6-X17']::text[],true,'{"seq":1,"concept":"M5-1-u6-C8","difficulty":2,"kind":"error","stem":"밑변 8 cm, 높이 5 cm인 삼각형의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「8 × 5 = 40 cm²야.」","correct":true,"mis_target":"M5-1-u6-X10"},{"t":"도현 — 「똑같은 삼각형 두 개를 붙이면 40 cm²야.」","mis":"M5-1-u6-X17"},{"t":"하은 — 「그러니 삼각형은 20 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["8 × 5 = 40은 삼각형 두 개를 붙인 평행사변형의 넓이예요.","삼각형 하나는 그 절반이에요.","서윤은 ÷ 2를 빠뜨려 잘못 말했어요 — 넓이는 8 × 5 ÷ 2 = 20이에요."],"variant_rule":{"alt":[{"stem":"밑변 6 cm, 높이 7 cm인 삼각형의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「6 × 7 = 42 cm²야.」","correct":true,"mis_target":"M5-1-u6-X10"},{"t":"라온 — 「똑같은 삼각형 두 개를 붙이면 42 cm²야.」","mis":"M5-1-u6-X17"},{"t":"예준 — 「그러니 삼각형은 21 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["6 × 7 = 42는 삼각형 두 개를 붙인 평행사변형의 넓이예요.","삼각형 하나는 그 절반이에요.","지민은 ÷ 2를 빠뜨려 잘못 말했어요 — 넓이는 6 × 7 ÷ 2 = 21이에요."]},{"stem":"밑변 10 cm, 높이 9 cm인 삼각형의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤아 — 「10 × 9 = 90 cm²야.」","correct":true,"mis_target":"M5-1-u6-X10"},{"t":"시우 — 「똑같은 삼각형 두 개를 붙이면 90 cm²야.」","mis":"M5-1-u6-X17"},{"t":"나린 — 「그러니 삼각형은 45 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["10 × 9 = 90은 삼각형 두 개를 붙인 평행사변형의 넓이예요.","삼각형 하나는 그 절반이에요.","윤아는 ÷ 2를 빠뜨려 잘못 말했어요 — 넓이는 10 × 9 ÷ 2 = 45예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_challenge#2','math',5,1,'u6','L08','g5_1_math_u6_L08_challenge','lesson_challenge','M5-1-u6-C8',2,'mc','auto','모눈 한 칸은 1 cm²예요. 넓이가 다른 삼각형은 어느 것인가요?',ARRAY['M5-1-u6-X11']::text[],true,'{"seq":2,"concept":"M5-1-u6-C8","difficulty":2,"kind":"mc","stem":"모눈 한 칸은 1 cm²예요. 넓이가 다른 삼각형은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M5-1-u6-X11"},{"t":"㉯","mis":"M5-1-u6-X11"},{"t":"㉰","mis":"M5-1-u6-X11"}],"explanation":["모눈에서 밑변 칸 수와 높이 칸 수를 세어 (밑변) × (높이) ÷ 2로 구해요.","㉮ 8 cm², ㉯ 8 cm², ㉰ 8 cm², ㉱ 10 cm²예요.","밑변과 높이가 같으면 꼭짓점이 옆으로 가도 넓이가 같아요 — 다른 하나는 ㉱예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,75],[75,75],[45,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,75],[75,75],[15,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,75],[75,75],[105,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,75],[90,75],[45,15]]],"show":[]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 넓이가 다른 삼각형은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M5-1-u6-X11"},{"t":"㉯","mis":"M5-1-u6-X11"},{"t":"㉱","mis":"M5-1-u6-X11"}],"explanation":["모눈에서 밑변 칸 수와 높이 칸 수를 세어 (밑변) × (높이) ÷ 2로 구해요.","㉮ 9 cm², ㉯ 9 cm², ㉰ 6 cm², ㉱ 9 cm²예요.","밑변과 높이가 같으면 꼭짓점이 옆으로 가도 넓이가 같아요 — 다른 하나는 ㉰예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,75],[105,75],[30,30]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,75],[105,75],[75,30]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,75],[75,75],[120,30]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,75],[105,75],[120,30]]],"show":[]}]}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 넓이가 다른 삼각형은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M5-1-u6-X11"},{"t":"㉰","mis":"M5-1-u6-X11"},{"t":"㉱","mis":"M5-1-u6-X11"}],"explanation":["모눈에서 밑변 칸 수와 높이 칸 수를 세어 (밑변) × (높이) ÷ 2로 구해요.","㉮ 8 cm², ㉯ 6 cm², ㉰ 8 cm², ㉱ 8 cm²예요.","밑변과 높이가 같으면 꼭짓점이 옆으로 가도 넓이가 같아요 — 다른 하나는 ㉯예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,75],[75,75],[30,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[30,75],[90,75],[105,30]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,75],[75,75],[75,15]]],"show":[]},{"w":135,"h":90,"grid":15,"poly":[[[15,75],[75,75],[120,15]]],"show":[]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_challenge#3','math',5,1,'u6','L08','g5_1_math_u6_L08_challenge','lesson_challenge','M5-1-u6-C8',3,'sa','auto','가로 10 cm, 세로 6 cm인 직사각형에 대각선을 하나 그었더니 똑같은 삼각형 두 개로 나뉘었어요. 삼각형 한 개의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":3,"concept":"M5-1-u6-C8","difficulty":3,"kind":"sa","stem":"가로 10 cm, 세로 6 cm인 직사각형에 대각선을 하나 그었더니 똑같은 삼각형 두 개로 나뉘었어요. 삼각형 한 개의 넓이는 몇 cm²인가요?","answer":["30"],"explanation":["직사각형의 넓이는 10 × 6 = 60이에요.","대각선은 직사각형을 똑같이 둘로 나눠요.","60 ÷ 2 = 30 — 삼각형 하나는 30 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 12 cm, 세로 7 cm인 직사각형에 대각선을 하나 그었더니 똑같은 삼각형 두 개로 나뉘었어요. 삼각형 한 개의 넓이는 몇 cm²인가요?","answer":["42"],"explanation":["직사각형의 넓이는 12 × 7 = 84예요.","대각선은 직사각형을 똑같이 둘로 나눠요.","84 ÷ 2 = 42 — 삼각형 하나는 42 cm²예요."]},{"stem":"가로 9 cm, 세로 8 cm인 직사각형에 대각선을 하나 그었더니 똑같은 삼각형 두 개로 나뉘었어요. 삼각형 한 개의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["직사각형의 넓이는 9 × 8 = 72예요.","대각선은 직사각형을 똑같이 둘로 나눠요.","72 ÷ 2 = 36 — 삼각형 하나는 36 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_challenge#4','math',5,1,'u6','L08','g5_1_math_u6_L08_challenge','lesson_challenge','M5-1-u6-C8',3,'sa','auto','세 변의 길이가 6 cm, 8 cm, 10 cm인 직각삼각형이 있어요. 가장 긴 변이 직각과 마주 보는 변일 때 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C8","difficulty":3,"kind":"sa","stem":"세 변의 길이가 6 cm, 8 cm, 10 cm인 직각삼각형이 있어요. 가장 긴 변이 직각과 마주 보는 변일 때 넓이는 몇 cm²인가요?","answer":["24"],"explanation":["직각을 낀 두 변 6 cm와 8 cm가 서로 수직이에요.","한 변을 밑변으로 하면 다른 변이 높이예요 — 가장 긴 변 10 cm는 높이가 아니에요.","6 × 8 ÷ 2 = 24 — 넓이는 24 cm²예요."],"mis":"M5-1-u6-X11","variant_rule":{"alt":[{"stem":"세 변의 길이가 5 cm, 12 cm, 13 cm인 직각삼각형이 있어요. 가장 긴 변이 직각과 마주 보는 변일 때 넓이는 몇 cm²인가요?","answer":["30"],"explanation":["직각을 낀 두 변 5 cm와 12 cm가 서로 수직이에요.","한 변을 밑변으로 하면 다른 변이 높이예요 — 가장 긴 변 13 cm는 높이가 아니에요.","5 × 12 ÷ 2 = 30 — 넓이는 30 cm²예요."]},{"stem":"세 변의 길이가 9 cm, 12 cm, 15 cm인 직각삼각형이 있어요. 가장 긴 변이 직각과 마주 보는 변일 때 넓이는 몇 cm²인가요?","answer":["54"],"explanation":["직각을 낀 두 변 9 cm와 12 cm가 서로 수직이에요.","한 변을 밑변으로 하면 다른 변이 높이예요 — 가장 긴 변 15 cm는 높이가 아니에요.","9 × 12 ÷ 2 = 54 — 넓이는 54 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_challenge#5','math',5,1,'u6','L08','g5_1_math_u6_L08_challenge','lesson_challenge','M5-1-u6-C8',3,'sa','auto','밑변 8 cm, 높이 6 cm인 삼각형과 넓이가 같은 평행사변형의 밑변이 4 cm예요. 평행사변형의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":5,"concept":"M5-1-u6-C8","difficulty":3,"kind":"sa","stem":"밑변 8 cm, 높이 6 cm인 삼각형과 넓이가 같은 평행사변형의 밑변이 4 cm예요. 평행사변형의 높이는 몇 cm인가요?","answer":["6"],"explanation":["삼각형의 넓이는 8 × 6 ÷ 2 = 24예요.","평행사변형도 24니 4 × □ = 24예요.","24 ÷ 4 = 6 — 높이는 6 cm예요."],"mis":"M5-1-u6-X10","variant_rule":{"alt":[{"stem":"밑변 10 cm, 높이 6 cm인 삼각형과 넓이가 같은 평행사변형의 밑변이 5 cm예요. 평행사변형의 높이는 몇 cm인가요?","answer":["6"],"explanation":["삼각형의 넓이는 10 × 6 ÷ 2 = 30이에요.","평행사변형도 30이니 5 × □ = 30이에요.","30 ÷ 5 = 6 — 높이는 6 cm예요."]},{"stem":"밑변 12 cm, 높이 4 cm인 삼각형과 넓이가 같은 평행사변형의 밑변이 3 cm예요. 평행사변형의 높이는 몇 cm인가요?","answer":["8"],"explanation":["삼각형의 넓이는 12 × 4 ÷ 2 = 24예요.","평행사변형도 24니 3 × □ = 24예요.","24 ÷ 3 = 8 — 높이는 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_challenge#6','math',5,1,'u6','L08','g5_1_math_u6_L08_challenge','lesson_challenge','M5-1-u6-C8',3,'sa','auto','모눈 한 칸은 1 cm²예요. 그림에서 색칠한 삼각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-1-u6-C8","difficulty":3,"kind":"sa","stem":"모눈 한 칸은 1 cm²예요. 그림에서 색칠한 삼각형의 넓이는 몇 cm²인가요?","answer":["14"],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","모눈에서 밑변은 7칸, 높이는 꼭짓점까지 4칸이에요.","7 × 4 ÷ 2 = 14 — 넓이는 14 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,75],[120,75],[60,15]]],"show":[]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 삼각형의 넓이는 몇 cm²인가요?","answer":["12"],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","모눈에서 밑변은 6칸, 높이는 꼭짓점까지 4칸이에요.","6 × 4 ÷ 2 = 12 — 넓이는 12 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,75],[105,75],[120,15]]],"show":[]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 삼각형의 넓이는 몇 cm²인가요?","answer":["12"],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","모눈에서 밑변은 6칸, 높이는 꼭짓점까지 4칸이에요.","6 × 4 ÷ 2 = 12 — 넓이는 12 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[30,75],[120,75],[15,15]]],"show":[]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_challenge#7','math',5,1,'u6','L08','g5_1_math_u6_L08_challenge','lesson_challenge','M5-1-u6-C8',3,'sa','auto','넓이가 40 cm²이고 높이가 8 cm인 삼각형의 밑변은 몇 cm인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C8","difficulty":3,"kind":"sa","stem":"넓이가 40 cm²이고 높이가 8 cm인 삼각형의 밑변은 몇 cm인가요?","answer":["10"],"explanation":["(밑변) × (높이) = 40 × 2 = 80이에요.","□ × 8 = 80이니 □ = 80 ÷ 8이에요.","80 ÷ 8 = 10 — 밑변은 10 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"넓이가 27 cm²이고 높이가 6 cm인 삼각형의 밑변은 몇 cm인가요?","answer":["9"],"explanation":["(밑변) × (높이) = 27 × 2 = 54예요.","□ × 6 = 54니 □ = 54 ÷ 6이에요.","54 ÷ 6 = 9 — 밑변은 9 cm예요."]},{"stem":"넓이가 45 cm²이고 높이가 9 cm인 삼각형의 밑변은 몇 cm인가요?","answer":["10"],"explanation":["(밑변) × (높이) = 45 × 2 = 90이에요.","□ × 9 = 90이니 □ = 90 ÷ 9예요.","90 ÷ 9 = 10 — 밑변은 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_challenge#8','math',5,1,'u6','L08','g5_1_math_u6_L08_challenge','lesson_challenge','M5-1-u6-C8',4,'sa','auto','밑변을 맞붙인 두 삼각형으로 연을 만들었어요. 맞붙인 밑변은 12 cm이고, 위 삼각형의 높이는 5 cm, 아래 삼각형의 높이는 9 cm예요. 연의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C8","difficulty":4,"kind":"sa","stem":"밑변을 맞붙인 두 삼각형으로 연을 만들었어요. 맞붙인 밑변은 12 cm이고, 위 삼각형의 높이는 5 cm, 아래 삼각형의 높이는 9 cm예요. 연의 넓이는 몇 cm²인가요?","answer":["84"],"explanation":["위 삼각형은 12 × 5 ÷ 2 = 30이에요.","아래 삼각형은 12 × 9 ÷ 2 = 54예요.","30 + 54 = 84 — 연의 넓이는 84 cm²예요."],"variant_rule":{"alt":[{"stem":"밑변을 맞붙인 두 삼각형으로 연을 만들었어요. 맞붙인 밑변은 10 cm이고, 위 삼각형의 높이는 4 cm, 아래 삼각형의 높이는 8 cm예요. 연의 넓이는 몇 cm²인가요?","answer":["60"],"explanation":["위 삼각형은 10 × 4 ÷ 2 = 20이에요.","아래 삼각형은 10 × 8 ÷ 2 = 40이에요.","20 + 40 = 60 — 연의 넓이는 60 cm²예요."]},{"stem":"밑변을 맞붙인 두 삼각형으로 연을 만들었어요. 맞붙인 밑변은 8 cm이고, 위 삼각형의 높이는 6 cm, 아래 삼각형의 높이는 9 cm예요. 연의 넓이는 몇 cm²인가요?","answer":["60"],"explanation":["위 삼각형은 8 × 6 ÷ 2 = 24예요.","아래 삼각형은 8 × 9 ÷ 2 = 36이에요.","24 + 36 = 60 — 연의 넓이는 60 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_challenge#9','math',5,1,'u6','L08','g5_1_math_u6_L08_challenge','lesson_challenge','M5-1-u6-C8',4,'sa','auto','세 변이 15 cm, 20 cm, 25 cm인 직각삼각형에서 가장 긴 변 25 cm를 밑변으로 하면 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M5-1-u6-C8","difficulty":4,"kind":"sa","stem":"세 변이 15 cm, 20 cm, 25 cm인 직각삼각형에서 가장 긴 변 25 cm를 밑변으로 하면 높이는 몇 cm인가요?","answer":["12"],"explanation":["직각을 낀 두 변으로 넓이를 구하면 15 × 20 ÷ 2 = 150이에요.","밑변을 25 cm로 바꾸어도 넓이는 같으니 25 × □ ÷ 2 = 150이에요.","□ = 150 × 2 ÷ 25 = 12 — 높이는 12 cm예요."],"mis":"M5-1-u6-X11","variant_rule":{"alt":[{"stem":"세 변이 30 cm, 40 cm, 50 cm인 직각삼각형에서 가장 긴 변 50 cm를 밑변으로 하면 높이는 몇 cm인가요?","answer":["24"],"explanation":["직각을 낀 두 변으로 넓이를 구하면 30 × 40 ÷ 2 = 600이에요.","밑변을 50 cm로 바꾸어도 넓이는 같으니 50 × □ ÷ 2 = 600이에요.","□ = 600 × 2 ÷ 50 = 24 — 높이는 24 cm예요."]},{"stem":"세 변이 45 cm, 60 cm, 75 cm인 직각삼각형에서 가장 긴 변 75 cm를 밑변으로 하면 높이는 몇 cm인가요?","answer":["36"],"explanation":["직각을 낀 두 변으로 넓이를 구하면 45 × 60 ÷ 2 = 1350이에요.","밑변을 75 cm로 바꾸어도 넓이는 같으니 75 × □ ÷ 2 = 1350이에요.","□ = 1350 × 2 ÷ 75 = 36 — 높이는 36 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L08_challenge#10','math',5,1,'u6','L08','g5_1_math_u6_L08_challenge','lesson_challenge','M5-1-u6-C8',4,'essay','teacher','삼각형의 넓이를 (밑변의 길이) × (높이) ÷ 2로 구하는 까닭을 설명하고, 밑변 10 cm, 높이 6 cm인 삼각형의 넓이를 구하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u6-C8","difficulty":4,"kind":"essay","stem":"삼각형의 넓이를 (밑변의 길이) × (높이) ÷ 2로 구하는 까닭을 설명하고, 밑변 10 cm, 높이 6 cm인 삼각형의 넓이를 구하세요.","answer_guide":{"answer":"예: 똑같은 삼각형 두 개를 돌려 붙이면 밑변과 높이가 같은 평행사변형이 되고, 그 넓이는 (밑변) × (높이)이다. 삼각형은 그 절반이므로 2로 나눈다. 10 × 6 ÷ 2 = 30, 넓이는 30 cm²이다.","scoring_points":["똑같은 삼각형 두 개로 평행사변형(직사각형)을 만든다고 썼는가","삼각형이 그 절반이라 ÷ 2를 한다고 썼는가","10 × 6 ÷ 2 = 30 cm²를 바르게 구했는가"]},"explanation":["똑같은 삼각형 두 개를 붙이면 평행사변형이에요.","삼각형은 그 절반이에요.","10 × 6 ÷ 2 = 30 — 30 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_basic#1','math',5,1,'u6','L09','g5_1_math_u6_L09_basic','lesson_basic','M5-1-u6-C9',1,'mc','auto','사다리꼴의 넓이를 구하는 식은 어느 것인가요?',ARRAY['M5-1-u6-X12','M5-1-u6-X10']::text[],true,'{"seq":1,"concept":"M5-1-u6-C9","difficulty":1,"kind":"mc","stem":"사다리꼴의 넓이를 구하는 식은 어느 것인가요?","options":[{"t":"((윗변) + (아랫변)) × (높이) ÷ 2","correct":true},{"t":"(윗변) × (높이) ÷ 2","mis":"M5-1-u6-X12"},{"t":"((윗변) + (아랫변)) × (높이)","mis":"M5-1-u6-X10"},{"t":"(윗변) + (아랫변) + (높이)","mis":"M5-1-u6-X12"}],"explanation":["똑같은 사다리꼴 두 개를 거꾸로 붙이면 평행사변형이 돼요.","그 평행사변형의 밑변은 (윗변 + 아랫변), 높이는 그대로예요.","사다리꼴은 그 절반이라 ((윗변) + (아랫변)) × (높이) ÷ 2예요."],"variant_rule":{"alt":[{"stem":"사다리꼴에서 평행한 두 변을 무엇이라고 하나요?","options":[{"t":"윗변과 아랫변","correct":true},{"t":"밑변과 높이","mis":"M5-1-u6-X11"},{"t":"이웃한 두 변","mis":"M5-1-u6-X12"},{"t":"두 대각선","mis":"M5-1-u6-X13"}],"explanation":["사다리꼴은 평행한 변이 한 쌍 있는 사각형이에요.","그 평행한 두 변을 윗변과 아랫변이라고 해요.","두 변 사이의 거리가 높이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_basic#2','math',5,1,'u6','L09','g5_1_math_u6_L09_basic','lesson_basic','M5-1-u6-C9',1,'sa','auto','윗변 5 cm, 아랫변 7 cm, 높이 4 cm인 사다리꼴의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C9","difficulty":1,"kind":"sa","stem":"윗변 5 cm, 아랫변 7 cm, 높이 4 cm인 사다리꼴의 넓이는 몇 cm²인가요?","answer":["24"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","5 + 7 = 12예요.","(5 + 7) × 4 ÷ 2 = 24 — 넓이는 24 cm²예요."],"variant_rule":{"alt":[{"stem":"윗변 3 cm, 아랫변 9 cm, 높이 5 cm인 사다리꼴의 넓이는 몇 cm²인가요?","answer":["30"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","3 + 9 = 12예요.","(3 + 9) × 5 ÷ 2 = 30 — 넓이는 30 cm²예요."]},{"stem":"윗변 6 cm, 아랫변 8 cm, 높이 5 cm인 사다리꼴의 넓이는 몇 cm²인가요?","answer":["35"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","6 + 8 = 14예요.","(6 + 8) × 5 ÷ 2 = 35 — 넓이는 35 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_basic#3','math',5,1,'u6','L09','g5_1_math_u6_L09_basic','lesson_basic','M5-1-u6-C9',1,'mc','auto','사다리꼴 모양 색종이의 윗변이 4 cm, 아랫변이 8 cm, 높이가 5 cm예요. 색종이의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X10','M5-1-u6-X12']::text[],true,'{"seq":3,"concept":"M5-1-u6-C9","difficulty":1,"kind":"mc","stem":"사다리꼴 모양 색종이의 윗변이 4 cm, 아랫변이 8 cm, 높이가 5 cm예요. 색종이의 넓이는 몇 cm²인가요?","options":[{"t":"30 cm²","correct":true},{"t":"60 cm²","mis":"M5-1-u6-X10"},{"t":"10 cm²","mis":"M5-1-u6-X12"},{"t":"20 cm²","mis":"M5-1-u6-X12"}],"explanation":["윗변과 아랫변을 먼저 더해요 — 4 + 8 = 12예요.","높이를 곱하면 12 × 5 = 60 — 사다리꼴 두 개 넓이예요.","60 ÷ 2 = 30 — 넓이는 30 cm²예요."],"variant_rule":{"alt":[{"stem":"사다리꼴 모양 색종이의 윗변이 6 cm, 아랫변이 10 cm, 높이가 4 cm예요. 색종이의 넓이는 몇 cm²인가요?","options":[{"t":"32 cm²","correct":true},{"t":"64 cm²","mis":"M5-1-u6-X10"},{"t":"12 cm²","mis":"M5-1-u6-X12"},{"t":"20 cm²","mis":"M5-1-u6-X12"}],"explanation":["윗변과 아랫변을 먼저 더해요 — 6 + 10 = 16이에요.","높이를 곱하면 16 × 4 = 64 — 사다리꼴 두 개 넓이예요.","64 ÷ 2 = 32 — 넓이는 32 cm²예요."]},{"stem":"사다리꼴 모양 색종이의 윗변이 5 cm, 아랫변이 9 cm, 높이가 6 cm예요. 색종이의 넓이는 몇 cm²인가요?","options":[{"t":"42 cm²","correct":true},{"t":"84 cm²","mis":"M5-1-u6-X10"},{"t":"15 cm²","mis":"M5-1-u6-X12"},{"t":"27 cm²","mis":"M5-1-u6-X12"}],"explanation":["윗변과 아랫변을 먼저 더해요 — 5 + 9 = 14예요.","높이를 곱하면 14 × 6 = 84 — 사다리꼴 두 개 넓이예요.","84 ÷ 2 = 42 — 넓이는 42 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_basic#4','math',5,1,'u6','L09','g5_1_math_u6_L09_basic','lesson_basic','M5-1-u6-C9',1,'sa','auto','윗변 7 m, 아랫변 5 m, 높이 5 m인 사다리꼴의 넓이는 몇 m²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C9","difficulty":1,"kind":"sa","stem":"윗변 7 m, 아랫변 5 m, 높이 5 m인 사다리꼴의 넓이는 몇 m²인가요?","answer":["30"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","7 + 5 = 12예요.","(7 + 5) × 5 ÷ 2 = 30 — 넓이는 30 m²예요."],"variant_rule":{"alt":[{"stem":"윗변 10 m, 아랫변 6 m, 높이 4 m인 사다리꼴의 넓이는 몇 m²인가요?","answer":["32"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","10 + 6 = 16이에요.","(10 + 6) × 4 ÷ 2 = 32 — 넓이는 32 m²예요."]},{"stem":"윗변 9 m, 아랫변 5 m, 높이 6 m인 사다리꼴의 넓이는 몇 m²인가요?","answer":["42"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","9 + 5 = 14예요.","(9 + 5) × 6 ÷ 2 = 42 — 넓이는 42 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_basic#5','math',5,1,'u6','L09','g5_1_math_u6_L09_basic','lesson_basic','M5-1-u6-C9',2,'mc','auto','사다리꼴 ㄱㄴㄷㄹ에서 윗변과 아랫변을 바르게 짝지은 것은 어느 것인가요?',ARRAY['M5-1-u6-X12','M5-1-u6-X11']::text[],true,'{"seq":5,"concept":"M5-1-u6-C9","difficulty":2,"kind":"mc","stem":"사다리꼴 ㄱㄴㄷㄹ에서 윗변과 아랫변을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"변 ㄱㄹ과 변 ㄴㄷ","correct":true},{"t":"변 ㄱㄴ과 변 ㄹㄷ","mis":"M5-1-u6-X12"},{"t":"변 ㄱㄹ과 선분 ㄱㅁ","mis":"M5-1-u6-X11"},{"t":"변 ㄴㄷ과 선분 ㄱㅁ","mis":"M5-1-u6-X11"}],"explanation":["사다리꼴에서 평행한 두 변을 윗변과 아랫변이라고 해요.","변 ㄱㄹ과 변 ㄴㄷ이 서로 평행해요.","높이는 그 두 변 사이의 거리로, 선분 ㄱㅁ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[45,15],"ㄴ":[15,75],"ㄷ":[135,75],"ㄹ":[90,15],"ㅁ":[45,75]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㅁ"]],"right":[["ㄱ","ㅁ","ㄷ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 사다리꼴 ㄱㄴㄷㄹ에서 윗변과 아랫변을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"변 ㄱㄹ과 변 ㄴㄷ","correct":true},{"t":"변 ㄱㄴ과 변 ㄹㄷ","mis":"M5-1-u6-X12"},{"t":"변 ㄱㄴ과 변 ㄴㄷ","mis":"M5-1-u6-X11"},{"t":"변 ㄱㄹ과 변 ㄱㄴ","mis":"M5-1-u6-X11"}],"explanation":["사다리꼴에서 평행한 두 변을 윗변과 아랫변이라고 해요.","변 ㄱㄹ과 변 ㄴㄷ이 서로 평행해요.","높이는 그 두 변 사이의 거리로, 두 변과 수직인 변 ㄱㄴ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[15,15],"ㄴ":[15,75],"ㄷ":[135,75],"ㄹ":[75,15]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"right":[["ㄱ","ㄴ","ㄷ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_basic#6','math',5,1,'u6','L09','g5_1_math_u6_L09_basic','lesson_basic','M5-1-u6-C9',2,'mc','auto','사다리꼴의 넓이를 계산한 것 가운데 잘못된 것은 어느 것인가요? (단위는 cm)',ARRAY['M5-1-u6-X17']::text[],true,'{"seq":6,"concept":"M5-1-u6-C9","difficulty":2,"kind":"mc","stem":"사다리꼴의 넓이를 계산한 것 가운데 잘못된 것은 어느 것인가요? (단위는 cm)","options":[{"t":"윗변 6 · 아랫변 8 · 높이 3 → 42 cm²","correct":true},{"t":"윗변 3 · 아랫변 5 · 높이 4 → 16 cm²","mis":"M5-1-u6-X17"},{"t":"윗변 2 · 아랫변 6 · 높이 5 → 20 cm²","mis":"M5-1-u6-X17"},{"t":"윗변 4 · 아랫변 4 · 높이 6 → 24 cm²","mis":"M5-1-u6-X17"}],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","(3 + 5) × 4 ÷ 2 = 16, (6 + 8) × 3 ÷ 2 = 21, (2 + 6) × 5 ÷ 2 = 20, (4 + 4) × 6 ÷ 2 = 24예요.","잘못된 것의 바른 값은 21 cm²예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 사다리꼴의 넓이를 계산한 것 가운데 잘못된 것은 어느 것인가요? (단위는 cm)","options":[{"t":"윗변 4 · 아랫변 6 · 높이 5 → 50 cm²","correct":true},{"t":"윗변 5 · 아랫변 7 · 높이 2 → 12 cm²","mis":"M5-1-u6-X17"},{"t":"윗변 3 · 아랫변 9 · 높이 4 → 24 cm²","mis":"M5-1-u6-X17"},{"t":"윗변 2 · 아랫변 8 · 높이 3 → 15 cm²","mis":"M5-1-u6-X17"}],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","(5 + 7) × 2 ÷ 2 = 12, (3 + 9) × 4 ÷ 2 = 24, (4 + 6) × 5 ÷ 2 = 25, (2 + 8) × 3 ÷ 2 = 15예요.","잘못된 것의 바른 값은 25 cm²예요."]},{"stem":"이번에는 다른 보기예요. 사다리꼴의 넓이를 계산한 것 가운데 잘못된 것은 어느 것인가요? (단위는 cm)","options":[{"t":"윗변 3 · 아랫변 7 · 높이 6 → 60 cm²","correct":true},{"t":"윗변 4 · 아랫변 8 · 높이 3 → 18 cm²","mis":"M5-1-u6-X17"},{"t":"윗변 5 · 아랫변 5 · 높이 4 → 20 cm²","mis":"M5-1-u6-X17"},{"t":"윗변 6 · 아랫변 10 · 높이 3 → 24 cm²","mis":"M5-1-u6-X17"}],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","(4 + 8) × 3 ÷ 2 = 18, (5 + 5) × 4 ÷ 2 = 20, (6 + 10) × 3 ÷ 2 = 24, (3 + 7) × 6 ÷ 2 = 30이에요.","잘못된 것의 바른 값은 30 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_basic#7','math',5,1,'u6','L09','g5_1_math_u6_L09_basic','lesson_basic','M5-1-u6-C9',2,'sa','auto','넓이가 42 m²인 사다리꼴의 윗변이 10 m, 아랫변이 4 m예요. 높이는 몇 m인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C9","difficulty":2,"kind":"sa","stem":"넓이가 42 m²인 사다리꼴의 윗변이 10 m, 아랫변이 4 m예요. 높이는 몇 m인가요?","answer":["6"],"explanation":["(10 + 4) × □ ÷ 2 = 42예요.","14 × □ = 42 × 2 = 84예요.","□ = 84 ÷ 14 = 6 — 높이는 6 m예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"넓이가 45 cm²인 사다리꼴의 윗변이 4 cm, 아랫변이 6 cm예요. 높이는 몇 cm인가요?","answer":["9"],"explanation":["(4 + 6) × □ ÷ 2 = 45예요.","10 × □ = 45 × 2 = 90이에요.","□ = 90 ÷ 10 = 9 — 높이는 9 cm예요."]},{"stem":"넓이가 40 cm²인 사다리꼴의 윗변이 3 cm, 아랫변이 7 cm예요. 높이는 몇 cm인가요?","answer":["8"],"explanation":["(3 + 7) × □ ÷ 2 = 40이에요.","10 × □ = 40 × 2 = 80이에요.","□ = 80 ÷ 10 = 8 — 높이는 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_basic#8','math',5,1,'u6','L09','g5_1_math_u6_L09_basic','lesson_basic','M5-1-u6-C9',2,'mc','auto','윗변 5 cm, 아랫변 9 cm, 높이 4 cm인 사다리꼴(한 변이 밑변과 수직)을 직사각형과 삼각형으로 나누어 구했더니 20 cm²와 8 cm²였어요. 공식으로 구한 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X15']::text[],true,'{"seq":8,"concept":"M5-1-u6-C9","difficulty":2,"kind":"mc","stem":"윗변 5 cm, 아랫변 9 cm, 높이 4 cm인 사다리꼴(한 변이 밑변과 수직)을 직사각형과 삼각형으로 나누어 구했더니 20 cm²와 8 cm²였어요. 공식으로 구한 넓이는 몇 cm²인가요?","options":[{"t":"28 cm²","correct":true},{"t":"20 cm²","mis":"M5-1-u6-X15"},{"t":"8 cm²","mis":"M5-1-u6-X15"},{"t":"36 cm²","mis":"M5-1-u6-X15"}],"explanation":["나눈 두 넓이를 더하면 20 + 8 = 28이에요.","공식으로 구하면 (5 + 9) × 4 ÷ 2 = 28이에요.","넓이는 어떻게 나누어도 변하지 않아 둘 다 28 cm²예요."],"variant_rule":{"alt":[{"stem":"윗변 4 cm, 아랫변 10 cm, 높이 6 cm인 사다리꼴(한 변이 밑변과 수직)을 직사각형과 삼각형으로 나누어 구했더니 24 cm²와 18 cm²였어요. 공식으로 구한 넓이는 몇 cm²인가요?","options":[{"t":"42 cm²","correct":true},{"t":"24 cm²","mis":"M5-1-u6-X15"},{"t":"18 cm²","mis":"M5-1-u6-X15"},{"t":"60 cm²","mis":"M5-1-u6-X15"}],"explanation":["나눈 두 넓이를 더하면 24 + 18 = 42예요.","공식으로 구하면 (4 + 10) × 6 ÷ 2 = 42예요.","넓이는 어떻게 나누어도 변하지 않아 둘 다 42 cm²예요."]},{"stem":"윗변 6 cm, 아랫변 8 cm, 높이 5 cm인 사다리꼴(한 변이 밑변과 수직)을 직사각형과 삼각형으로 나누어 구했더니 30 cm²와 5 cm²였어요. 공식으로 구한 넓이는 몇 cm²인가요?","options":[{"t":"35 cm²","correct":true},{"t":"30 cm²","mis":"M5-1-u6-X15"},{"t":"5 cm²","mis":"M5-1-u6-X15"},{"t":"40 cm²","mis":"M5-1-u6-X15"}],"explanation":["나눈 두 넓이를 더하면 30 + 5 = 35예요.","공식으로 구하면 (6 + 8) × 5 ÷ 2 = 35예요.","넓이는 어떻게 나누어도 변하지 않아 둘 다 35 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_basic#9','math',5,1,'u6','L09','g5_1_math_u6_L09_basic','lesson_basic','M5-1-u6-C9',2,'ox','auto','사다리꼴의 넓이를 구할 때 2로 나누는 까닭은 똑같은 사다리꼴 두 개를 붙이면 평행사변형이 되기 때문이에요.',ARRAY['M5-1-u6-X12']::text[],true,'{"seq":9,"concept":"M5-1-u6-C9","difficulty":2,"kind":"ox","stem":"사다리꼴의 넓이를 구할 때 2로 나누는 까닭은 똑같은 사다리꼴 두 개를 붙이면 평행사변형이 되기 때문이에요.","answer":"O","reason_options":[{"t":"두 개를 붙인 평행사변형의 절반이 사다리꼴 하나이므로","correct":true},{"t":"윗변과 아랫변이 두 개라 나누어 주므로","mis":"M5-1-u6-X12"}],"mis":"M5-1-u6-X12","explanation":["똑같은 사다리꼴 두 개를 거꾸로 붙이면 평행사변형이에요.","그 넓이는 (윗변 + 아랫변) × (높이)예요.","사다리꼴은 그 절반이라 ÷ 2예요."],"variant_rule":{"alt":[{"stem":"사다리꼴의 넓이는 (아랫변) × (높이)로 구해요.","answer":"X","reason_options":[{"t":"윗변과 아랫변을 더한 값에 높이를 곱하고 2로 나누므로","correct":true},{"t":"아랫변이 윗변보다 길어 아랫변만 쓰므로","mis":"M5-1-u6-X12"}],"explanation":["사다리꼴은 윗변과 아랫변의 길이가 달라요.","아랫변만 쓰면 직사각형보다 넓게 셈하게 돼요.","((윗변) + (아랫변)) × (높이) ÷ 2로 구해요."]},{"stem":"사다리꼴을 직사각형과 삼각형으로 나누어 더한 넓이와 공식으로 구한 넓이는 같아요.","answer":"O","reason_options":[{"t":"겹치거나 빠뜨리지 않고 나누면 넓이는 변하지 않으므로","correct":true},{"t":"나누면 넓이가 조금씩 줄어들므로","mis":"M5-1-u6-X15"}],"explanation":["넓이는 칸의 수예요.","나누어도 칸의 수는 그대로예요.","그래서 어떻게 나누어 구해도 공식과 같은 값이 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_basic#10','math',5,1,'u6','L09','g5_1_math_u6_L09_basic','lesson_basic','M5-1-u6-C9',3,'sa','auto','윗변 5 cm, 아랫변 9 cm, 높이 4 cm인 사다리꼴이 있어요. 한 변이 밑변과 수직이라 직사각형과 직각삼각형으로 나눌 수 있어요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":10,"concept":"M5-1-u6-C9","difficulty":3,"kind":"sa","stem":"윗변 5 cm, 아랫변 9 cm, 높이 4 cm인 사다리꼴이 있어요. 한 변이 밑변과 수직이라 직사각형과 직각삼각형으로 나눌 수 있어요. 넓이는 몇 cm²인가요?","answer":["28"],"explanation":["직사각형은 가로 5, 세로 4 — 5 × 4 = 20이에요.","삼각형은 밑변 9 − 5 = 4, 높이 4 — 4 × 4 ÷ 2 = 8이에요.","20 + 8 = 28 — 공식 (5 + 9) × 4 ÷ 2 = 28과 같아요."],"variant_rule":{"alt":[{"stem":"윗변 6 cm, 아랫변 10 cm, 높이 5 cm인 사다리꼴이 있어요. 한 변이 밑변과 수직이라 직사각형과 직각삼각형으로 나눌 수 있어요. 넓이는 몇 cm²인가요?","answer":["40"],"explanation":["직사각형은 가로 6, 세로 5 — 6 × 5 = 30이에요.","삼각형은 밑변 10 − 6 = 4, 높이 5 — 4 × 5 ÷ 2 = 10이에요.","30 + 10 = 40 — 공식 (6 + 10) × 5 ÷ 2 = 40과 같아요."]},{"stem":"윗변 3 cm, 아랫변 9 cm, 높이 4 cm인 사다리꼴이 있어요. 한 변이 밑변과 수직이라 직사각형과 직각삼각형으로 나눌 수 있어요. 넓이는 몇 cm²인가요?","answer":["24"],"explanation":["직사각형은 가로 3, 세로 4 — 3 × 4 = 12예요.","삼각형은 밑변 9 − 3 = 6, 높이 4 — 6 × 4 ÷ 2 = 12예요.","12 + 12 = 24 — 공식 (3 + 9) × 4 ÷ 2 = 24와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_challenge#1','math',5,1,'u6','L09','g5_1_math_u6_L09_challenge','lesson_challenge','M5-1-u6-C9',2,'error','auto','윗변 5 cm, 아랫변 7 cm, 높이 4 cm인 사다리꼴의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u6-X10','M5-1-u6-X17']::text[],true,'{"seq":1,"concept":"M5-1-u6-C9","difficulty":2,"kind":"error","stem":"윗변 5 cm, 아랫변 7 cm, 높이 4 cm인 사다리꼴의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「(5 + 7) × 4 = 48 cm²야.」","correct":true,"mis_target":"M5-1-u6-X10"},{"t":"도현 — 「두 개를 붙인 평행사변형은 밑변이 12 cm야.」","mis":"M5-1-u6-X17"},{"t":"하은 — 「(5 + 7) × 4 ÷ 2 = 24 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["(5 + 7) × 4 = 48은 사다리꼴 두 개를 붙인 평행사변형의 넓이예요.","사다리꼴 하나는 그 절반이에요.","서윤은 ÷ 2를 빠뜨려 잘못 말했어요 — 넓이는 24 cm²예요."],"variant_rule":{"alt":[{"stem":"윗변 4 cm, 아랫변 8 cm, 높이 5 cm인 사다리꼴의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「(4 + 8) × 5 = 60 cm²야.」","correct":true,"mis_target":"M5-1-u6-X10"},{"t":"라온 — 「두 개를 붙인 평행사변형은 밑변이 12 cm야.」","mis":"M5-1-u6-X17"},{"t":"예준 — 「(4 + 8) × 5 ÷ 2 = 30 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["(4 + 8) × 5 = 60은 사다리꼴 두 개를 붙인 평행사변형의 넓이예요.","사다리꼴 하나는 그 절반이에요.","지민은 ÷ 2를 빠뜨려 잘못 말했어요 — 넓이는 30 cm²예요."]},{"stem":"윗변 6 cm, 아랫변 10 cm, 높이 3 cm인 사다리꼴의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤아 — 「(6 + 10) × 3 = 48 cm²야.」","correct":true,"mis_target":"M5-1-u6-X10"},{"t":"시우 — 「두 개를 붙인 평행사변형은 밑변이 16 cm야.」","mis":"M5-1-u6-X17"},{"t":"나린 — 「(6 + 10) × 3 ÷ 2 = 24 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["(6 + 10) × 3 = 48은 사다리꼴 두 개를 붙인 평행사변형의 넓이예요.","사다리꼴 하나는 그 절반이에요.","윤아는 ÷ 2를 빠뜨려 잘못 말했어요 — 넓이는 24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_challenge#2','math',5,1,'u6','L09','g5_1_math_u6_L09_challenge','lesson_challenge','M5-1-u6-C9',2,'sa','auto','넓이가 50 cm²인 사다리꼴의 아랫변이 12 cm, 높이가 5 cm예요. 윗변은 몇 cm인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C9","difficulty":2,"kind":"sa","stem":"넓이가 50 cm²인 사다리꼴의 아랫변이 12 cm, 높이가 5 cm예요. 윗변은 몇 cm인가요?","answer":["8"],"explanation":["(□ + 12) × 5 ÷ 2 = 50이에요.","(□ + 12) × 5 = 100이니 □ + 12 = 100 ÷ 5 = 20이에요.","□ = 20 − 12 = 8 — 윗변은 8 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"넓이가 36 cm²인 사다리꼴의 아랫변이 7 cm, 높이가 4 cm예요. 윗변은 몇 cm인가요?","answer":["11"],"explanation":["(□ + 7) × 4 ÷ 2 = 36이에요.","(□ + 7) × 4 = 72니 □ + 7 = 72 ÷ 4 = 18이에요.","□ = 18 − 7 = 11 — 윗변은 11 cm예요."]},{"stem":"넓이가 54 cm²인 사다리꼴의 아랫변이 10 cm, 높이가 6 cm예요. 윗변은 몇 cm인가요?","answer":["8"],"explanation":["(□ + 10) × 6 ÷ 2 = 54예요.","(□ + 10) × 6 = 108이니 □ + 10 = 108 ÷ 6 = 18이에요.","□ = 18 − 10 = 8 — 윗변은 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_challenge#3','math',5,1,'u6','L09','g5_1_math_u6_L09_challenge','lesson_challenge','M5-1-u6-C9',3,'sa','auto','윗변 6 cm, 아랫변 10 cm, 높이 4 cm인 사다리꼴(한 변이 밑변과 수직)을 가로 10 cm, 세로 4 cm인 직사각형에서 빼는 방법으로 넓이를 구하면 몇 cm²인가요?','{}'::text[],true,'{"seq":3,"concept":"M5-1-u6-C9","difficulty":3,"kind":"sa","stem":"윗변 6 cm, 아랫변 10 cm, 높이 4 cm인 사다리꼴(한 변이 밑변과 수직)을 가로 10 cm, 세로 4 cm인 직사각형에서 빼는 방법으로 넓이를 구하면 몇 cm²인가요?","answer":["32"],"explanation":["감싸는 직사각형은 10 × 4 = 40이에요.","빠지는 직각삼각형은 밑변 10 − 6 = 4, 높이 4 — 4 × 4 ÷ 2 = 8이에요.","40 − 8 = 32 — 공식 (6 + 10) × 4 ÷ 2 = 32와 같아요."],"mis":"M5-1-u6-X15","variant_rule":{"alt":[{"stem":"윗변 4 cm, 아랫변 9 cm, 높이 6 cm인 사다리꼴(한 변이 밑변과 수직)을 가로 9 cm, 세로 6 cm인 직사각형에서 빼는 방법으로 넓이를 구하면 몇 cm²인가요?","answer":["39"],"explanation":["감싸는 직사각형은 9 × 6 = 54예요.","빠지는 직각삼각형은 밑변 9 − 4 = 5, 높이 6 — 5 × 6 ÷ 2 = 15예요.","54 − 15 = 39 — 공식 (4 + 9) × 6 ÷ 2 = 39와 같아요."]},{"stem":"윗변 5 cm, 아랫변 11 cm, 높이 4 cm인 사다리꼴(한 변이 밑변과 수직)을 가로 11 cm, 세로 4 cm인 직사각형에서 빼는 방법으로 넓이를 구하면 몇 cm²인가요?","answer":["32"],"explanation":["감싸는 직사각형은 11 × 4 = 44예요.","빠지는 직각삼각형은 밑변 11 − 5 = 6, 높이 4 — 6 × 4 ÷ 2 = 12예요.","44 − 12 = 32 — 공식 (5 + 11) × 4 ÷ 2 = 32와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_challenge#4','math',5,1,'u6','L09','g5_1_math_u6_L09_challenge','lesson_challenge','M5-1-u6-C9',3,'mc','auto','㉠ 윗변 4 cm, 아랫변 8 cm, 높이 6 cm인 사다리꼴과 ㉡ 밑변 6 cm, 높이 6 cm인 평행사변형의 넓이를 비교하면 어떠한가요?',ARRAY['M5-1-u6-X16','M5-1-u6-X12']::text[],true,'{"seq":4,"concept":"M5-1-u6-C9","difficulty":3,"kind":"mc","stem":"㉠ 윗변 4 cm, 아랫변 8 cm, 높이 6 cm인 사다리꼴과 ㉡ 밑변 6 cm, 높이 6 cm인 평행사변형의 넓이를 비교하면 어떠한가요?","options":[{"t":"두 넓이가 같다","correct":true},{"t":"㉠이 더 넓다","mis":"M5-1-u6-X16"},{"t":"㉡이 더 넓다","mis":"M5-1-u6-X16"},{"t":"알 수 없다","mis":"M5-1-u6-X12"}],"explanation":["㉠은 (4 + 8) × 6 ÷ 2 = 36이에요.","㉡은 6 × 6 = 36이에요 — 평행사변형은 ÷ 2가 없어요.","그래서 두 넓이는 같아요."],"variant_rule":{"alt":[{"stem":"㉠ 윗변 5 cm, 아랫변 9 cm, 높이 4 cm인 사다리꼴과 ㉡ 밑변 7 cm, 높이 5 cm인 평행사변형의 넓이를 비교하면 어떠한가요?","options":[{"t":"㉡이 더 넓다","correct":true},{"t":"㉠이 더 넓다","mis":"M5-1-u6-X16"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X10"},{"t":"알 수 없다","mis":"M5-1-u6-X12"}],"explanation":["㉠은 (5 + 9) × 4 ÷ 2 = 28이에요.","㉡은 7 × 5 = 35예요 — 평행사변형은 ÷ 2가 없어요.","그래서 ㉡이 더 넓어요."]},{"stem":"㉠ 윗변 6 cm, 아랫변 10 cm, 높이 5 cm인 사다리꼴과 ㉡ 밑변 8 cm, 높이 6 cm인 평행사변형의 넓이를 비교하면 어떠한가요?","options":[{"t":"㉡이 더 넓다","correct":true},{"t":"㉠이 더 넓다","mis":"M5-1-u6-X16"},{"t":"두 넓이가 같다","mis":"M5-1-u6-X10"},{"t":"알 수 없다","mis":"M5-1-u6-X12"}],"explanation":["㉠은 (6 + 10) × 5 ÷ 2 = 40이에요.","㉡은 8 × 6 = 48이에요 — 평행사변형은 ÷ 2가 없어요.","그래서 ㉡이 더 넓어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_challenge#5','math',5,1,'u6','L09','g5_1_math_u6_L09_challenge','lesson_challenge','M5-1-u6-C9',3,'mc','auto','사다리꼴의 윗변의 길이를 점점 줄여 0이 되면 어떤 도형의 넓이 공식과 같아지나요?',ARRAY['M5-1-u6-X10','M5-1-u6-X13']::text[],true,'{"seq":5,"concept":"M5-1-u6-C9","difficulty":3,"kind":"mc","stem":"사다리꼴의 윗변의 길이를 점점 줄여 0이 되면 어떤 도형의 넓이 공식과 같아지나요?","options":[{"t":"삼각형 — (아랫변) × (높이) ÷ 2","correct":true},{"t":"직사각형 — (아랫변) × (높이)","mis":"M5-1-u6-X10"},{"t":"평행사변형 — (아랫변) × (높이)","mis":"M5-1-u6-X10"},{"t":"마름모 — (아랫변) × (높이) ÷ 4","mis":"M5-1-u6-X13"}],"explanation":["윗변이 0이 되면 윗변이 한 점으로 모여 삼각형이 돼요.","공식에 넣으면 (0 + 아랫변) × (높이) ÷ 2예요.","그래서 삼각형의 넓이 공식과 같아요."],"variant_rule":{"alt":[{"stem":"윗변과 아랫변의 길이가 같아지면 사다리꼴 공식은 어떤 도형의 공식과 같아지나요?","options":[{"t":"평행사변형 — (밑변) × (높이)","correct":true},{"t":"삼각형 — (밑변) × (높이) ÷ 2","mis":"M5-1-u6-X10"},{"t":"마름모 — (밑변) × (높이) ÷ 2","mis":"M5-1-u6-X13"},{"t":"사다리꼴 공식은 쓸 수 없다","mis":"M5-1-u6-X12"}],"explanation":["윗변 = 아랫변이면 마주 보는 두 변이 평행하고 같아 평행사변형이에요.","(□ + □) × (높이) ÷ 2 = □ × (높이)예요.","그래서 (밑변) × (높이)가 돼요."]},{"stem":"사다리꼴의 넓이에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"나누어 더해도, 큰 도형에서 빼어도 공식과 같은 답이 나온다","correct":true},{"t":"윗변만 알면 넓이를 구할 수 있다","mis":"M5-1-u6-X12"},{"t":"높이는 비스듬한 변의 길이다","mis":"M5-1-u6-X11"},{"t":"평행사변형처럼 ÷ 2를 하지 않는다","mis":"M5-1-u6-X10"}],"explanation":["넓이는 칸의 수라 나누거나 빼어도 변하지 않아요.","높이는 윗변과 아랫변 사이의 수직 거리예요.","공식에는 윗변·아랫변·높이가 모두 필요하고 ÷ 2가 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_challenge#6','math',5,1,'u6','L09','g5_1_math_u6_L09_challenge','lesson_challenge','M5-1-u6-C9',3,'sa','auto','모눈 한 칸은 1 cm²예요. 그림에서 색칠한 사다리꼴의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-1-u6-C9","difficulty":3,"kind":"sa","stem":"모눈 한 칸은 1 cm²예요. 그림에서 색칠한 사다리꼴의 넓이는 몇 cm²인가요?","answer":["20"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","모눈에서 윗변은 3칸, 아랫변은 7칸, 높이는 4칸이에요.","(3 + 7) × 4 ÷ 2 = 20 — 넓이는 20 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[45,15],[15,75],[120,75],[90,15]]],"show":[]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 사다리꼴의 넓이는 몇 cm²인가요?","answer":["20"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","모눈에서 윗변은 3칸, 아랫변은 7칸, 높이는 4칸이에요.","(3 + 7) × 4 ÷ 2 = 20 — 넓이는 20 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,15],[15,75],[120,75],[60,15]]],"show":[]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 사다리꼴의 넓이는 몇 cm²인가요?","answer":["18"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","모눈에서 윗변은 4칸, 아랫변은 8칸, 높이는 3칸이에요.","(4 + 8) × 3 ÷ 2 = 18 — 넓이는 18 cm²예요."],"asset":{"type":"geo","items":[{"w":150,"h":75,"grid":15,"poly":[[[30,15],[15,60],[135,60],[90,15]]],"show":[]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_challenge#7','math',5,1,'u6','L09','g5_1_math_u6_L09_challenge','lesson_challenge','M5-1-u6-C9',3,'sa','auto','윗변 4 m, 아랫변 8 m, 높이 5 m인 사다리꼴 모양 화단에 1 m²마다 흙 2포대를 채우려고 해요. 흙은 모두 몇 포대 필요한가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C9","difficulty":3,"kind":"sa","stem":"윗변 4 m, 아랫변 8 m, 높이 5 m인 사다리꼴 모양 화단에 1 m²마다 흙 2포대를 채우려고 해요. 흙은 모두 몇 포대 필요한가요?","answer":["60"],"explanation":["화단의 넓이는 (4 + 8) × 5 ÷ 2 = 30이에요.","1 m²마다 2포대예요.","30 × 2 = 60 — 흙은 60포대예요."],"variant_rule":{"alt":[{"stem":"윗변 3 m, 아랫변 7 m, 높이 4 m인 사다리꼴 모양 화단에 1 m²마다 흙 3포대를 채우려고 해요. 흙은 모두 몇 포대 필요한가요?","answer":["60"],"explanation":["화단의 넓이는 (3 + 7) × 4 ÷ 2 = 20이에요.","1 m²마다 3포대예요.","20 × 3 = 60 — 흙은 60포대예요."]},{"stem":"윗변 5 m, 아랫변 9 m, 높이 6 m인 사다리꼴 모양 화단에 1 m²마다 흙 2포대를 채우려고 해요. 흙은 모두 몇 포대 필요한가요?","answer":["84"],"explanation":["화단의 넓이는 (5 + 9) × 6 ÷ 2 = 42예요.","1 m²마다 2포대예요.","42 × 2 = 84 — 흙은 84포대예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_challenge#8','math',5,1,'u6','L09','g5_1_math_u6_L09_challenge','lesson_challenge','M5-1-u6-C9',4,'sa','auto','윗변 5 cm, 아랫변 9 cm, 높이 6 cm인 사다리꼴과 넓이가 같은 삼각형의 밑변이 12 cm예요. 삼각형의 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C9","difficulty":4,"kind":"sa","stem":"윗변 5 cm, 아랫변 9 cm, 높이 6 cm인 사다리꼴과 넓이가 같은 삼각형의 밑변이 12 cm예요. 삼각형의 높이는 몇 cm인가요?","answer":["7"],"explanation":["사다리꼴의 넓이는 (5 + 9) × 6 ÷ 2 = 42예요.","삼각형은 12 × □ ÷ 2 = 42니 12 × □ = 84예요.","□ = 84 ÷ 12 = 7 — 높이는 7 cm예요."],"mis":"M5-1-u6-X10","variant_rule":{"alt":[{"stem":"윗변 4 cm, 아랫변 10 cm, 높이 6 cm인 사다리꼴과 넓이가 같은 삼각형의 밑변이 14 cm예요. 삼각형의 높이는 몇 cm인가요?","answer":["6"],"explanation":["사다리꼴의 넓이는 (4 + 10) × 6 ÷ 2 = 42예요.","삼각형은 14 × □ ÷ 2 = 42니 14 × □ = 84예요.","□ = 84 ÷ 14 = 6 — 높이는 6 cm예요."]},{"stem":"윗변 3 cm, 아랫변 9 cm, 높이 8 cm인 사다리꼴과 넓이가 같은 삼각형의 밑변이 16 cm예요. 삼각형의 높이는 몇 cm인가요?","answer":["6"],"explanation":["사다리꼴의 넓이는 (3 + 9) × 8 ÷ 2 = 48이에요.","삼각형은 16 × □ ÷ 2 = 48이니 16 × □ = 96이에요.","□ = 96 ÷ 16 = 6 — 높이는 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_challenge#9','math',5,1,'u6','L09','g5_1_math_u6_L09_challenge','lesson_challenge','M5-1-u6-C9',4,'sa','auto','윗변이 아랫변보다 4 cm 짧은 사다리꼴이 있어요. 아랫변이 10 cm이고 넓이가 48 cm²일 때 높이는 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M5-1-u6-C9","difficulty":4,"kind":"sa","stem":"윗변이 아랫변보다 4 cm 짧은 사다리꼴이 있어요. 아랫변이 10 cm이고 넓이가 48 cm²일 때 높이는 몇 cm인가요?","answer":["6"],"explanation":["윗변은 10 − 4 = 6이에요.","(6 + 10) × □ ÷ 2 = 48이니 16 × □ = 96이에요.","□ = 96 ÷ 16 = 6 — 높이는 6 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"윗변이 아랫변보다 6 cm 짧은 사다리꼴이 있어요. 아랫변이 12 cm이고 넓이가 63 cm²일 때 높이는 몇 cm인가요?","answer":["7"],"explanation":["윗변은 12 − 6 = 6이에요.","(6 + 12) × □ ÷ 2 = 63이니 18 × □ = 126이에요.","□ = 126 ÷ 18 = 7 — 높이는 7 cm예요."]},{"stem":"윗변이 아랫변보다 3 cm 짧은 사다리꼴이 있어요. 아랫변이 11 cm이고 넓이가 76 cm²일 때 높이는 몇 cm인가요?","answer":["8"],"explanation":["윗변은 11 − 3 = 8이에요.","(8 + 11) × □ ÷ 2 = 76이니 19 × □ = 152예요.","□ = 152 ÷ 19 = 8 — 높이는 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L09_challenge#10','math',5,1,'u6','L09','g5_1_math_u6_L09_challenge','lesson_challenge','M5-1-u6-C9',4,'essay','teacher','사다리꼴의 넓이를 ((윗변) + (아랫변)) × (높이) ÷ 2로 구하는 까닭을 똑같은 사다리꼴 두 개를 써서 설명하고, 윗변 6 cm, 아랫변 10 cm, 높이 5 cm인 사다리꼴의 넓이를 구하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u6-C9","difficulty":4,"kind":"essay","stem":"사다리꼴의 넓이를 ((윗변) + (아랫변)) × (높이) ÷ 2로 구하는 까닭을 똑같은 사다리꼴 두 개를 써서 설명하고, 윗변 6 cm, 아랫변 10 cm, 높이 5 cm인 사다리꼴의 넓이를 구하세요.","answer_guide":{"answer":"예: 똑같은 사다리꼴 하나를 거꾸로 돌려 붙이면 밑변이 (윗변 + 아랫변), 높이가 그대로인 평행사변형이 된다. 그 넓이는 (윗변 + 아랫변) × (높이)이고 사다리꼴은 그 절반이다. (6 + 10) × 5 ÷ 2 = 40, 넓이는 40 cm²이다.","scoring_points":["두 개를 붙이면 평행사변형이 된다고 썼는가","평행사변형의 밑변이 윗변 + 아랫변이라고 썼는가","(6 + 10) × 5 ÷ 2 = 40 cm²를 바르게 구했는가"]},"explanation":["두 개를 거꾸로 붙이면 평행사변형이에요.","밑변은 6 + 10 = 16, 높이는 5예요.","16 × 5 ÷ 2 = 40 — 40 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_basic#1','math',5,1,'u6','L10','g5_1_math_u6_L10_basic','lesson_basic','M5-1-u6-C10',1,'mc','auto','마름모의 넓이를 구하는 식은 어느 것인가요?',ARRAY['M5-1-u6-X13','M5-1-u6-X10']::text[],true,'{"seq":1,"concept":"M5-1-u6-C10","difficulty":1,"kind":"mc","stem":"마름모의 넓이를 구하는 식은 어느 것인가요?","options":[{"t":"(한 대각선의 길이) × (다른 대각선의 길이) ÷ 2","correct":true},{"t":"(한 변) × (한 변)","mis":"M5-1-u6-X13"},{"t":"(한 변) × 4","mis":"M5-1-u6-X13"},{"t":"(한 대각선의 길이) × (다른 대각선의 길이)","mis":"M5-1-u6-X10"}],"explanation":["마름모를 딱 맞게 감싸는 직사각형의 가로와 세로는 두 대각선이에요.","마름모는 그 직사각형의 절반이에요.","그래서 (한 대각선) × (다른 대각선) ÷ 2예요."],"variant_rule":{"alt":[{"stem":"마름모의 넓이는 마름모를 딱 맞게 감싸는 직사각형 넓이의 얼마인가요?","options":[{"t":"절반","correct":true},{"t":"같다","mis":"M5-1-u6-X10"},{"t":"2배","mis":"M5-1-u6-X10"},{"t":"4분의 1","mis":"M5-1-u6-X16"}],"explanation":["직사각형 안에서 마름모 바깥은 작은 삼각형 네 개예요.","네 조각을 마름모 안으로 접으면 마름모를 딱 채워요.","그래서 마름모는 감싼 직사각형의 절반이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_basic#2','math',5,1,'u6','L10','g5_1_math_u6_L10_basic','lesson_basic','M5-1-u6-C10',1,'sa','auto','두 대각선의 길이가 6 cm와 4 cm인 마름모의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C10","difficulty":1,"kind":"sa","stem":"두 대각선의 길이가 6 cm와 4 cm인 마름모의 넓이는 몇 cm²인가요?","answer":["12"],"explanation":["마름모를 감싸는 직사각형은 6 × 4 = 24예요.","마름모는 그 절반이에요.","6 × 4 ÷ 2 = 12 — 넓이는 12 cm²예요."],"variant_rule":{"alt":[{"stem":"두 대각선의 길이가 8 cm와 6 cm인 마름모의 넓이는 몇 cm²인가요?","answer":["24"],"explanation":["마름모를 감싸는 직사각형은 8 × 6 = 48이에요.","마름모는 그 절반이에요.","8 × 6 ÷ 2 = 24 — 넓이는 24 cm²예요."]},{"stem":"두 대각선의 길이가 10 cm와 8 cm인 마름모의 넓이는 몇 cm²인가요?","answer":["40"],"explanation":["마름모를 감싸는 직사각형은 10 × 8 = 80이에요.","마름모는 그 절반이에요.","10 × 8 ÷ 2 = 40 — 넓이는 40 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_basic#3','math',5,1,'u6','L10','g5_1_math_u6_L10_basic','lesson_basic','M5-1-u6-C10',1,'mc','auto','두 대각선이 15 cm와 8 cm인 마름모 모양 스카프가 있어요. 스카프의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X10','M5-1-u6-X13','M5-1-u6-X16']::text[],true,'{"seq":3,"concept":"M5-1-u6-C10","difficulty":1,"kind":"mc","stem":"두 대각선이 15 cm와 8 cm인 마름모 모양 스카프가 있어요. 스카프의 넓이는 몇 cm²인가요?","options":[{"t":"60 cm²","correct":true},{"t":"120 cm²","mis":"M5-1-u6-X10"},{"t":"23 cm²","mis":"M5-1-u6-X13"},{"t":"30 cm²","mis":"M5-1-u6-X16"}],"explanation":["감싸는 직사각형은 15 × 8 = 120이에요.","마름모는 그 직사각형의 절반이에요.","120 ÷ 2 = 60 — 넓이는 60 cm²예요."],"variant_rule":{"alt":[{"stem":"두 대각선이 12 cm와 10 cm인 마름모 모양 스카프가 있어요. 스카프의 넓이는 몇 cm²인가요?","options":[{"t":"60 cm²","correct":true},{"t":"120 cm²","mis":"M5-1-u6-X10"},{"t":"22 cm²","mis":"M5-1-u6-X13"},{"t":"30 cm²","mis":"M5-1-u6-X16"}],"explanation":["감싸는 직사각형은 12 × 10 = 120이에요.","마름모는 그 직사각형의 절반이에요.","120 ÷ 2 = 60 — 넓이는 60 cm²예요."]},{"stem":"두 대각선이 14 cm와 6 cm인 마름모 모양 스카프가 있어요. 스카프의 넓이는 몇 cm²인가요?","options":[{"t":"42 cm²","correct":true},{"t":"84 cm²","mis":"M5-1-u6-X10"},{"t":"20 cm²","mis":"M5-1-u6-X13"},{"t":"21 cm²","mis":"M5-1-u6-X16"}],"explanation":["감싸는 직사각형은 14 × 6 = 84예요.","마름모는 그 직사각형의 절반이에요.","84 ÷ 2 = 42 — 넓이는 42 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_basic#4','math',5,1,'u6','L10','g5_1_math_u6_L10_basic','lesson_basic','M5-1-u6-C10',1,'sa','auto','두 대각선의 길이가 10 m와 14 m인 마름모의 넓이는 몇 m²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C10","difficulty":1,"kind":"sa","stem":"두 대각선의 길이가 10 m와 14 m인 마름모의 넓이는 몇 m²인가요?","answer":["70"],"explanation":["마름모를 감싸는 직사각형은 10 × 14 = 140이에요.","마름모는 그 절반이에요.","10 × 14 ÷ 2 = 70 — 넓이는 70 m²예요."],"variant_rule":{"alt":[{"stem":"두 대각선의 길이가 12 m와 9 m인 마름모의 넓이는 몇 m²인가요?","answer":["54"],"explanation":["마름모를 감싸는 직사각형은 12 × 9 = 108이에요.","마름모는 그 절반이에요.","12 × 9 ÷ 2 = 54 — 넓이는 54 m²예요."]},{"stem":"두 대각선의 길이가 16 cm와 10 cm인 마름모의 넓이는 몇 cm²인가요?","answer":["80"],"explanation":["마름모를 감싸는 직사각형은 16 × 10 = 160이에요.","마름모는 그 절반이에요.","16 × 10 ÷ 2 = 80 — 넓이는 80 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_basic#5','math',5,1,'u6','L10','g5_1_math_u6_L10_basic','lesson_basic','M5-1-u6-C10',2,'mc','auto','한 변의 길이가 5 cm인 마름모의 넓이를 구할 수 있나요?',ARRAY['M5-1-u6-X13']::text[],false,'{"seq":5,"concept":"M5-1-u6-C10","difficulty":2,"kind":"mc","stem":"한 변의 길이가 5 cm인 마름모의 넓이를 구할 수 있나요?","options":[{"t":"대각선의 길이를 알아야 구할 수 있다","correct":true},{"t":"5 × 5로 구할 수 있다","mis":"M5-1-u6-X13"},{"t":"5 × 4로 구할 수 있다","mis":"M5-1-u6-X13"},{"t":"한 변만 알면 언제나 구할 수 있다","mis":"M5-1-u6-X13"}],"explanation":["한 변이 5 cm인 마름모도 납작하게 누르면 넓이가 작아지고 통통하면 커져요.","한 변만으로는 넓이가 하나로 정해지지 않아요.","넓이는 두 대각선의 길이로 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_basic#6','math',5,1,'u6','L10','g5_1_math_u6_L10_basic','lesson_basic','M5-1-u6-C10',2,'sa','auto','넓이가 40 cm²인 마름모의 한 대각선이 10 cm예요. 다른 대각선은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-1-u6-C10","difficulty":2,"kind":"sa","stem":"넓이가 40 cm²인 마름모의 한 대각선이 10 cm예요. 다른 대각선은 몇 cm인가요?","answer":["8"],"explanation":["10 × □ ÷ 2 = 40이에요.","10 × □ = 40 × 2 = 80이에요.","□ = 80 ÷ 10 = 8 — 다른 대각선은 8 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"넓이가 48 cm²인 마름모의 한 대각선이 12 cm예요. 다른 대각선은 몇 cm인가요?","answer":["8"],"explanation":["12 × □ ÷ 2 = 48이에요.","12 × □ = 48 × 2 = 96이에요.","□ = 96 ÷ 12 = 8 — 다른 대각선은 8 cm예요."]},{"stem":"넓이가 35 cm²인 마름모의 한 대각선이 7 cm예요. 다른 대각선은 몇 cm인가요?","answer":["10"],"explanation":["7 × □ ÷ 2 = 35예요.","7 × □ = 35 × 2 = 70이에요.","□ = 70 ÷ 7 = 10 — 다른 대각선은 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_basic#7','math',5,1,'u6','L10','g5_1_math_u6_L10_basic','lesson_basic','M5-1-u6-C10',2,'mc','auto','두 대각선이 12 cm와 9 cm인 마름모를 딱 맞게 감싸는 직사각형의 넓이는 108 cm²예요. 마름모의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X10','M5-1-u6-X13']::text[],true,'{"seq":7,"concept":"M5-1-u6-C10","difficulty":2,"kind":"mc","stem":"두 대각선이 12 cm와 9 cm인 마름모를 딱 맞게 감싸는 직사각형의 넓이는 108 cm²예요. 마름모의 넓이는 몇 cm²인가요?","options":[{"t":"54 cm²","correct":true},{"t":"108 cm²","mis":"M5-1-u6-X10"},{"t":"216 cm²","mis":"M5-1-u6-X10"},{"t":"21 cm²","mis":"M5-1-u6-X13"}],"explanation":["직사각형 안에서 마름모 바깥의 네 조각을 안으로 접으면 마름모를 딱 채워요.","그래서 마름모는 감싼 직사각형의 절반이에요.","108 ÷ 2 = 54 — 넓이는 54 cm²예요."],"variant_rule":{"alt":[{"stem":"두 대각선이 14 cm와 8 cm인 마름모를 딱 맞게 감싸는 직사각형의 넓이는 112 cm²예요. 마름모의 넓이는 몇 cm²인가요?","options":[{"t":"56 cm²","correct":true},{"t":"112 cm²","mis":"M5-1-u6-X10"},{"t":"224 cm²","mis":"M5-1-u6-X10"},{"t":"22 cm²","mis":"M5-1-u6-X13"}],"explanation":["직사각형 안에서 마름모 바깥의 네 조각을 안으로 접으면 마름모를 딱 채워요.","그래서 마름모는 감싼 직사각형의 절반이에요.","112 ÷ 2 = 56 — 넓이는 56 cm²예요."]},{"stem":"두 대각선이 10 cm와 7 cm인 마름모를 딱 맞게 감싸는 직사각형의 넓이는 70 cm²예요. 마름모의 넓이는 몇 cm²인가요?","options":[{"t":"35 cm²","correct":true},{"t":"70 cm²","mis":"M5-1-u6-X10"},{"t":"140 cm²","mis":"M5-1-u6-X10"},{"t":"17 cm²","mis":"M5-1-u6-X13"}],"explanation":["직사각형 안에서 마름모 바깥의 네 조각을 안으로 접으면 마름모를 딱 채워요.","그래서 마름모는 감싼 직사각형의 절반이에요.","70 ÷ 2 = 35 — 넓이는 35 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_basic#8','math',5,1,'u6','L10','g5_1_math_u6_L10_basic','lesson_basic','M5-1-u6-C10',2,'mc','auto','마름모에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M5-1-u6-X13']::text[],true,'{"seq":8,"concept":"M5-1-u6-C10","difficulty":2,"kind":"mc","stem":"마름모에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"둘레는 한 변의 길이로, 넓이는 두 대각선으로 구한다","correct":true},{"t":"둘레도 넓이도 한 변의 길이로 구한다","mis":"M5-1-u6-X13"},{"t":"둘레도 넓이도 두 대각선으로 구한다","mis":"M5-1-u6-X13"},{"t":"넓이는 한 변의 길이를 4배 하여 구한다","mis":"M5-1-u6-X13"}],"explanation":["둘레는 가장자리 네 변의 합이라 (한 변) × 4예요.","넓이는 감싼 직사각형의 절반이라 (대각선) × (대각선) ÷ 2예요.","그래서 둘레는 한 변, 넓이는 대각선으로 구해요."],"variant_rule":{"alt":[{"stem":"마름모를 딱 맞게 감싸는 직사각형의 가로와 세로는 마름모의 무엇과 같나요?","options":[{"t":"두 대각선의 길이","correct":true},{"t":"한 변의 길이","mis":"M5-1-u6-X13"},{"t":"둘레","mis":"M5-1-u6-X01"},{"t":"한 변의 길이의 2배","mis":"M5-1-u6-X13"}],"explanation":["마름모의 마주 보는 꼭짓점끼리 직사각형의 변에 닿아요.","그래서 직사각형의 가로와 세로는 두 대각선의 길이와 같아요.","마름모의 넓이는 그 직사각형의 절반이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_basic#9','math',5,1,'u6','L10','g5_1_math_u6_L10_basic','lesson_basic','M5-1-u6-C10',2,'mc','auto','마름모 ㄱㄴㄷㄹ의 넓이를 구할 때 길이를 알아야 하는 두 선분은 어느 것인가요?',ARRAY['M5-1-u6-X13']::text[],true,'{"seq":9,"concept":"M5-1-u6-C10","difficulty":2,"kind":"mc","stem":"마름모 ㄱㄴㄷㄹ의 넓이를 구할 때 길이를 알아야 하는 두 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄷ과 선분 ㄴㄹ","correct":true},{"t":"변 ㄱㄴ과 변 ㄴㄷ","mis":"M5-1-u6-X13"},{"t":"변 ㄱㄴ과 선분 ㄱㄷ","mis":"M5-1-u6-X13"},{"t":"변 ㄱㄹ과 변 ㄴㄷ","mis":"M5-1-u6-X13"}],"explanation":["마름모의 넓이는 두 대각선으로 구해요.","마주 보는 꼭짓점을 이은 선분 ㄱㄷ과 선분 ㄴㄹ이 대각선이에요 — 두 대각선은 수직으로 만나요.","변의 길이는 둘레를 구할 때 써요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[75,7.5],"ㄴ":[15,45],"ㄷ":[75,82.5],"ㄹ":[135,45],"ㅁ":[75.0,45.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ","ㅁ","ㄹ"]],"tick":[["ㄱ","ㄴ",1],["ㄴ","ㄷ",1],["ㄷ","ㄹ",1],["ㄹ","ㄱ",1]],"show":["ㄱ","ㄴ","ㄷ","ㄹ"]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 마름모 ㄱㄴㄷㄹ의 넓이를 구할 때 길이를 알아야 하는 두 선분은 어느 것인가요?","options":[{"t":"선분 ㄱㄷ과 선분 ㄴㄹ","correct":true},{"t":"변 ㄱㄴ과 변 ㄴㄷ","mis":"M5-1-u6-X13"},{"t":"변 ㄱㄴ과 선분 ㄱㄷ","mis":"M5-1-u6-X13"},{"t":"변 ㄱㄹ과 변 ㄴㄷ","mis":"M5-1-u6-X13"}],"explanation":["마름모의 넓이는 두 대각선으로 구해요.","마주 보는 꼭짓점을 이은 선분 ㄱㄷ과 선분 ㄴㄹ이 대각선이에요 — 두 대각선은 수직으로 만나요.","변의 길이는 둘레를 구할 때 써요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"pts":{"ㄱ":[60,7.5],"ㄴ":[15,52.5],"ㄷ":[60,97.5],"ㄹ":[105,52.5],"ㅁ":[60.0,52.5]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"right":[["ㄱ","ㅁ","ㄹ"]],"tick":[["ㄱ","ㄴ",1],["ㄴ","ㄷ",1],["ㄷ","ㄹ",1],["ㄹ","ㄱ",1]],"show":["ㄱ","ㄴ","ㄷ","ㄹ"]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_basic#10','math',5,1,'u6','L10','g5_1_math_u6_L10_basic','lesson_basic','M5-1-u6-C10',3,'sa','auto','정사각형은 마름모이기도 해요. 대각선의 길이가 8 cm인 정사각형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":10,"concept":"M5-1-u6-C10","difficulty":3,"kind":"sa","stem":"정사각형은 마름모이기도 해요. 대각선의 길이가 8 cm인 정사각형의 넓이는 몇 cm²인가요?","answer":["32"],"explanation":["정사각형도 네 변이 같으니 마름모예요 — 두 대각선의 길이가 같아요.","마름모 공식으로 8 × 8 ÷ 2를 해요.","8 × 8 ÷ 2 = 32 — 넓이는 32 cm²예요."],"variant_rule":{"alt":[{"stem":"정사각형은 마름모이기도 해요. 대각선의 길이가 10 cm인 정사각형의 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["정사각형도 네 변이 같으니 마름모예요 — 두 대각선의 길이가 같아요.","마름모 공식으로 10 × 10 ÷ 2를 해요.","10 × 10 ÷ 2 = 50 — 넓이는 50 cm²예요."]},{"stem":"정사각형은 마름모이기도 해요. 대각선의 길이가 6 cm인 정사각형의 넓이는 몇 cm²인가요?","answer":["18"],"explanation":["정사각형도 네 변이 같으니 마름모예요 — 두 대각선의 길이가 같아요.","마름모 공식으로 6 × 6 ÷ 2를 해요.","6 × 6 ÷ 2 = 18 — 넓이는 18 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_challenge#1','math',5,1,'u6','L10','g5_1_math_u6_L10_challenge','lesson_challenge','M5-1-u6-C10',2,'error','auto','두 대각선이 6 cm와 4 cm인 마름모의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u6-X10','M5-1-u6-X17']::text[],true,'{"seq":1,"concept":"M5-1-u6-C10","difficulty":2,"kind":"error","stem":"두 대각선이 6 cm와 4 cm인 마름모의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「6 × 4 = 24 cm²야.」","correct":true,"mis_target":"M5-1-u6-X10"},{"t":"도현 — 「감싸는 직사각형이 24 cm²이고 마름모는 그 절반이야.」","mis":"M5-1-u6-X17"},{"t":"하은 — 「6 × 4 ÷ 2 = 12 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["6 × 4 = 24는 마름모를 감싸는 직사각형의 넓이예요.","마름모는 그 절반이에요.","서윤은 ÷ 2를 빠뜨려 잘못 말했어요 — 넓이는 12 cm²예요."],"variant_rule":{"alt":[{"stem":"두 대각선이 10 cm와 8 cm인 마름모의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「10 × 8 = 80 cm²야.」","correct":true,"mis_target":"M5-1-u6-X10"},{"t":"라온 — 「감싸는 직사각형이 80 cm²이고 마름모는 그 절반이야.」","mis":"M5-1-u6-X17"},{"t":"예준 — 「10 × 8 ÷ 2 = 40 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["10 × 8 = 80은 마름모를 감싸는 직사각형의 넓이예요.","마름모는 그 절반이에요.","지민은 ÷ 2를 빠뜨려 잘못 말했어요 — 넓이는 40 cm²예요."]},{"stem":"두 대각선이 12 cm와 6 cm인 마름모의 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤아 — 「12 × 6 = 72 cm²야.」","correct":true,"mis_target":"M5-1-u6-X10"},{"t":"시우 — 「감싸는 직사각형이 72 cm²이고 마름모는 그 절반이야.」","mis":"M5-1-u6-X17"},{"t":"나린 — 「12 × 6 ÷ 2 = 36 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["12 × 6 = 72는 마름모를 감싸는 직사각형의 넓이예요.","마름모는 그 절반이에요.","윤아는 ÷ 2를 빠뜨려 잘못 말했어요 — 넓이는 36 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_challenge#2','math',5,1,'u6','L10','g5_1_math_u6_L10_challenge','lesson_challenge','M5-1-u6-C10',2,'sa','auto','둘레가 20 cm이고 두 대각선이 8 cm와 6 cm인 마름모가 있어요. 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C10","difficulty":2,"kind":"sa","stem":"둘레가 20 cm이고 두 대각선이 8 cm와 6 cm인 마름모가 있어요. 넓이는 몇 cm²인가요?","answer":["24"],"explanation":["넓이에는 둘레가 아니라 두 대각선이 필요해요.","감싸는 직사각형은 8 × 6 = 48이에요.","48 ÷ 2 = 24 — 넓이는 24 cm²예요."],"mis":"M5-1-u6-X13","variant_rule":{"alt":[{"stem":"둘레가 40 cm이고 두 대각선이 16 cm와 12 cm인 마름모가 있어요. 넓이는 몇 cm²인가요?","answer":["96"],"explanation":["넓이에는 둘레가 아니라 두 대각선이 필요해요.","감싸는 직사각형은 16 × 12 = 192예요.","192 ÷ 2 = 96 — 넓이는 96 cm²예요."]},{"stem":"둘레가 30 cm이고 두 대각선이 9 cm와 12 cm인 마름모가 있어요. 넓이는 몇 cm²인가요?","answer":["54"],"explanation":["넓이에는 둘레가 아니라 두 대각선이 필요해요.","감싸는 직사각형은 9 × 12 = 108이에요.","108 ÷ 2 = 54 — 넓이는 54 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_challenge#3','math',5,1,'u6','L10','g5_1_math_u6_L10_challenge','lesson_challenge','M5-1-u6-C10',3,'sa','auto','가로 12 cm, 세로 8 cm인 직사각형의 네 변의 가운데 점을 차례로 이어 마름모를 그렸어요. 마름모의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":3,"concept":"M5-1-u6-C10","difficulty":3,"kind":"sa","stem":"가로 12 cm, 세로 8 cm인 직사각형의 네 변의 가운데 점을 차례로 이어 마름모를 그렸어요. 마름모의 넓이는 몇 cm²인가요?","answer":["48"],"explanation":["마름모의 두 대각선은 직사각형의 가로 12 cm와 세로 8 cm예요.","마름모는 감싸는 직사각형의 절반이에요.","12 × 8 ÷ 2 = 48 — 넓이는 48 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 10 cm, 세로 6 cm인 직사각형의 네 변의 가운데 점을 차례로 이어 마름모를 그렸어요. 마름모의 넓이는 몇 cm²인가요?","answer":["30"],"explanation":["마름모의 두 대각선은 직사각형의 가로 10 cm와 세로 6 cm예요.","마름모는 감싸는 직사각형의 절반이에요.","10 × 6 ÷ 2 = 30 — 넓이는 30 cm²예요."]},{"stem":"가로 14 cm, 세로 8 cm인 직사각형의 네 변의 가운데 점을 차례로 이어 마름모를 그렸어요. 마름모의 넓이는 몇 cm²인가요?","answer":["56"],"explanation":["마름모의 두 대각선은 직사각형의 가로 14 cm와 세로 8 cm예요.","마름모는 감싸는 직사각형의 절반이에요.","14 × 8 ÷ 2 = 56 — 넓이는 56 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_challenge#4','math',5,1,'u6','L10','g5_1_math_u6_L10_challenge','lesson_challenge','M5-1-u6-C10',3,'sa','auto','가로 10 cm, 세로 9 cm인 직사각형 종이에 네 변의 가운데 점을 이은 마름모를 그리고 마름모를 오려 냈어요. 남은 네 귀퉁이의 넓이를 모두 더하면 몇 cm²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C10","difficulty":3,"kind":"sa","stem":"가로 10 cm, 세로 9 cm인 직사각형 종이에 네 변의 가운데 점을 이은 마름모를 그리고 마름모를 오려 냈어요. 남은 네 귀퉁이의 넓이를 모두 더하면 몇 cm²인가요?","answer":["45"],"explanation":["직사각형은 10 × 9 = 90이에요.","마름모는 그 절반 45예요.","90 − 45 = 45 — 네 귀퉁이도 직사각형의 절반이에요."],"mis":"M5-1-u6-X15","variant_rule":{"alt":[{"stem":"가로 12 cm, 세로 7 cm인 직사각형 종이에 네 변의 가운데 점을 이은 마름모를 그리고 마름모를 오려 냈어요. 남은 네 귀퉁이의 넓이를 모두 더하면 몇 cm²인가요?","answer":["42"],"explanation":["직사각형은 12 × 7 = 84예요.","마름모는 그 절반 42예요.","84 − 42 = 42 — 네 귀퉁이도 직사각형의 절반이에요."]},{"stem":"가로 8 cm, 세로 9 cm인 직사각형 종이에 네 변의 가운데 점을 이은 마름모를 그리고 마름모를 오려 냈어요. 남은 네 귀퉁이의 넓이를 모두 더하면 몇 cm²인가요?","answer":["36"],"explanation":["직사각형은 8 × 9 = 72예요.","마름모는 그 절반 36이에요.","72 − 36 = 36 — 네 귀퉁이도 직사각형의 절반이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_challenge#5','math',5,1,'u6','L10','g5_1_math_u6_L10_challenge','lesson_challenge','M5-1-u6-C10',3,'mc','auto','마름모의 한 대각선만 2배로 늘리면 넓이는 몇 배가 되나요?',ARRAY['M5-1-u6-X07','M5-1-u6-X13','M5-1-u6-X10']::text[],true,'{"seq":5,"concept":"M5-1-u6-C10","difficulty":3,"kind":"mc","stem":"마름모의 한 대각선만 2배로 늘리면 넓이는 몇 배가 되나요?","options":[{"t":"2배","correct":true},{"t":"4배","mis":"M5-1-u6-X07"},{"t":"그대로","mis":"M5-1-u6-X13"},{"t":"⟨1/2⟩배","mis":"M5-1-u6-X10"}],"explanation":["넓이 = (한 대각선) × (다른 대각선) ÷ 2예요.","한 대각선만 2배면 곱도 2배예요.","예: 6 × 4 ÷ 2 = 12, 12 × 4 ÷ 2 = 24 — 2배예요."],"variant_rule":{"alt":[{"stem":"마름모의 두 대각선을 모두 2배로 늘리면 넓이는 몇 배가 되나요?","options":[{"t":"4배","correct":true},{"t":"2배","mis":"M5-1-u6-X07"},{"t":"8배","mis":"M5-1-u6-X16"},{"t":"그대로","mis":"M5-1-u6-X13"}],"explanation":["두 대각선이 모두 2배가 돼요.","곱은 2 × 2 = 4배가 돼요.","예: 6 × 4 ÷ 2 = 12, 12 × 8 ÷ 2 = 48 — 4배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_challenge#6','math',5,1,'u6','L10','g5_1_math_u6_L10_challenge','lesson_challenge','M5-1-u6-C10',3,'sa','auto','두 대각선이 12 cm와 6 cm인 마름모와 넓이가 같은 마름모의 한 대각선이 9 cm예요. 다른 대각선은 몇 cm인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-1-u6-C10","difficulty":3,"kind":"sa","stem":"두 대각선이 12 cm와 6 cm인 마름모와 넓이가 같은 마름모의 한 대각선이 9 cm예요. 다른 대각선은 몇 cm인가요?","answer":["8"],"explanation":["첫 마름모의 넓이는 12 × 6 ÷ 2 = 36이에요.","9 × □ ÷ 2 = 36이니 9 × □ = 72예요.","□ = 72 ÷ 9 = 8 — 다른 대각선은 8 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"두 대각선이 10 cm와 8 cm인 마름모와 넓이가 같은 마름모의 한 대각선이 5 cm예요. 다른 대각선은 몇 cm인가요?","answer":["16"],"explanation":["첫 마름모의 넓이는 10 × 8 ÷ 2 = 40이에요.","5 × □ ÷ 2 = 40이니 5 × □ = 80이에요.","□ = 80 ÷ 5 = 16 — 다른 대각선은 16 cm예요."]},{"stem":"두 대각선이 14 cm와 6 cm인 마름모와 넓이가 같은 마름모의 한 대각선이 7 cm예요. 다른 대각선은 몇 cm인가요?","answer":["12"],"explanation":["첫 마름모의 넓이는 14 × 6 ÷ 2 = 42예요.","7 × □ ÷ 2 = 42니 7 × □ = 84예요.","□ = 84 ÷ 7 = 12 — 다른 대각선은 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_challenge#7','math',5,1,'u6','L10','g5_1_math_u6_L10_challenge','lesson_challenge','M5-1-u6-C10',3,'mc','auto','한 변의 길이가 같은 두 마름모에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M5-1-u6-X13','M5-1-u6-X02']::text[],true,'{"seq":7,"concept":"M5-1-u6-C10","difficulty":3,"kind":"mc","stem":"한 변의 길이가 같은 두 마름모에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"둘레는 같지만 넓이는 다를 수 있다","correct":true},{"t":"둘레도 넓이도 반드시 같다","mis":"M5-1-u6-X13"},{"t":"넓이는 같지만 둘레는 다를 수 있다","mis":"M5-1-u6-X13"},{"t":"둘레도 넓이도 반드시 다르다","mis":"M5-1-u6-X02"}],"explanation":["한 변이 같으면 둘레 (한 변) × 4는 같아요.","하지만 납작한 마름모와 통통한 마름모는 대각선이 달라 넓이가 달라요.","그래서 둘레는 같아도 넓이는 다를 수 있어요."],"variant_rule":{"alt":[{"stem":"한 변이 5 cm인 마름모 가운데 넓이가 가장 넓은 것은 어떤 모양인가요?","options":[{"t":"네 각이 모두 직각인 정사각형","correct":true},{"t":"아주 납작한 마름모","mis":"M5-1-u6-X13"},{"t":"한 대각선이 가장 긴 마름모","mis":"M5-1-u6-X13"},{"t":"모두 넓이가 같다","mis":"M5-1-u6-X13"}],"explanation":["한 변이 같아도 기울어질수록 높이가 낮아져 넓이가 작아져요.","똑바로 세운 정사각형일 때 높이가 한 변과 같아 가장 커요.","그래서 5 × 5 = 25 cm²인 정사각형이 가장 넓어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_challenge#8','math',5,1,'u6','L10','g5_1_math_u6_L10_challenge','lesson_challenge','M5-1-u6-C10',4,'sa','auto','두 대각선이 9 cm와 8 cm인 마름모 모양 스카프 2장을 염색하려고 해요. 스카프의 넓이는 모두 몇 cm²인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C10","difficulty":4,"kind":"sa","stem":"두 대각선이 9 cm와 8 cm인 마름모 모양 스카프 2장을 염색하려고 해요. 스카프의 넓이는 모두 몇 cm²인가요?","answer":["72"],"explanation":["스카프 한 장은 9 × 8 ÷ 2 = 36이에요.","2장이니 36 × 2예요.","36 × 2 = 72 — 모두 72 cm²예요."],"variant_rule":{"alt":[{"stem":"두 대각선이 10 cm와 7 cm인 마름모 모양 스카프 2장을 염색하려고 해요. 스카프의 넓이는 모두 몇 cm²인가요?","answer":["70"],"explanation":["스카프 한 장은 10 × 7 ÷ 2 = 35예요.","2장이니 35 × 2예요.","35 × 2 = 70 — 모두 70 cm²예요."]},{"stem":"두 대각선이 8 cm와 6 cm인 마름모 모양 스카프 3장을 염색하려고 해요. 스카프의 넓이는 모두 몇 cm²인가요?","answer":["72"],"explanation":["스카프 한 장은 8 × 6 ÷ 2 = 24예요.","3장이니 24 × 3이에요.","24 × 3 = 72 — 모두 72 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_challenge#9','math',5,1,'u6','L10','g5_1_math_u6_L10_challenge','lesson_challenge','M5-1-u6-C10',4,'sa','auto','긴 대각선이 짧은 대각선의 2배인 마름모의 넓이가 49 cm²예요. 긴 대각선은 몇 cm인가요?','{}'::text[],true,'{"seq":9,"concept":"M5-1-u6-C10","difficulty":4,"kind":"sa","stem":"긴 대각선이 짧은 대각선의 2배인 마름모의 넓이가 49 cm²예요. 긴 대각선은 몇 cm인가요?","answer":["14"],"explanation":["짧은 대각선을 □라 하면 긴 대각선은 □ × 2예요.","□ × (□ × 2) ÷ 2 = □ × □ = 49예요.","□ = 7이니 긴 대각선은 7 × 2 = 14 — 14 cm예요."],"mis":"M5-1-u6-X14","variant_rule":{"alt":[{"stem":"긴 대각선이 짧은 대각선의 2배인 마름모의 넓이가 36 cm²예요. 긴 대각선은 몇 cm인가요?","answer":["12"],"explanation":["짧은 대각선을 □라 하면 긴 대각선은 □ × 2예요.","□ × (□ × 2) ÷ 2 = □ × □ = 36이에요.","□ = 6이니 긴 대각선은 6 × 2 = 12 — 12 cm예요."]},{"stem":"긴 대각선이 짧은 대각선의 2배인 마름모의 넓이가 64 cm²예요. 긴 대각선은 몇 cm인가요?","answer":["16"],"explanation":["짧은 대각선을 □라 하면 긴 대각선은 □ × 2예요.","□ × (□ × 2) ÷ 2 = □ × □ = 64예요.","□ = 8이니 긴 대각선은 8 × 2 = 16 — 16 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L10_challenge#10','math',5,1,'u6','L10','g5_1_math_u6_L10_challenge','lesson_challenge','M5-1-u6-C10',4,'essay','teacher','마름모의 넓이를 한 변의 길이로 구할 수 없는 까닭과, 두 대각선으로 구하는 까닭을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u6-C10","difficulty":4,"kind":"essay","stem":"마름모의 넓이를 한 변의 길이로 구할 수 없는 까닭과, 두 대각선으로 구하는 까닭을 설명하세요.","answer_guide":{"answer":"예: 한 변의 길이가 같아도 납작한 마름모와 통통한 마름모는 넓이가 다르므로 한 변만으로는 넓이가 정해지지 않는다. 마름모를 딱 맞게 감싸는 직사각형의 가로와 세로는 두 대각선이고, 마름모 바깥의 조각을 안으로 접으면 마름모를 딱 채우므로 마름모는 그 직사각형의 절반이다. 그래서 (한 대각선) × (다른 대각선) ÷ 2로 구한다.","scoring_points":["한 변이 같아도 모양에 따라 넓이가 다르다고 썼는가","감싼 직사각형의 가로·세로가 두 대각선이라고 썼는가","마름모가 그 절반이라 ÷ 2를 한다고 썼는가"]},"explanation":["한 변이 같아도 납작하면 좁고 통통하면 넓어요.","감싼 직사각형의 가로·세로가 두 대각선이에요.","마름모는 그 절반 — (대각선) × (대각선) ÷ 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_basic#1','math',5,1,'u6','L11','g5_1_math_u6_L11_basic','lesson_basic','M5-1-u6-C11',1,'mc','auto','넓이를 바로 구하기 어려운 도형을 만났을 때 좋은 방법은 어느 것인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X16','M5-1-u6-X15']::text[],false,'{"seq":1,"concept":"M5-1-u6-C11","difficulty":1,"kind":"mc","stem":"넓이를 바로 구하기 어려운 도형을 만났을 때 좋은 방법은 어느 것인가요?","options":[{"t":"아는 도형으로 나누거나 큰 도형에서 뺀다","correct":true},{"t":"둘레를 대신 구한다","mis":"M5-1-u6-X01"},{"t":"가장 긴 변을 두 번 곱한다","mis":"M5-1-u6-X16"},{"t":"가장 넓은 부분만 구한다","mis":"M5-1-u6-X15"}],"explanation":["직사각형·삼각형·사다리꼴처럼 공식을 아는 도형을 떠올려요.","도형을 그런 도형으로 나누어 더하거나, 감싸는 큰 도형에서 빠진 부분을 빼요.","둘레는 넓이와 다른 양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_basic#2','math',5,1,'u6','L11','g5_1_math_u6_L11_basic','lesson_basic','M5-1-u6-C11',1,'mc','auto','가족 지원 센터가 지어질 땅을 감싸는 직사각형은 가로 16 m, 세로 10 m예요. 직사각형의 넓이는 몇 m²인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X10']::text[],false,'{"seq":2,"concept":"M5-1-u6-C11","difficulty":1,"kind":"mc","stem":"가족 지원 센터가 지어질 땅을 감싸는 직사각형은 가로 16 m, 세로 10 m예요. 직사각형의 넓이는 몇 m²인가요?","options":[{"t":"160 m²","correct":true},{"t":"52 m²","mis":"M5-1-u6-X01"},{"t":"26 m²","mis":"M5-1-u6-X01"},{"t":"80 m²","mis":"M5-1-u6-X10"}],"explanation":["직사각형의 넓이는 (가로) × (세로)예요.","16 × 10 = 160이에요.","(16 + 10) × 2 = 52는 둘레예요 — 넓이는 160 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_basic#3','math',5,1,'u6','L11','g5_1_math_u6_L11_basic','lesson_basic','M5-1-u6-C11',1,'mc','auto','땅에서 빠지는 부분은 밑변 5 m, 높이 6 m인 직각삼각형이에요. 빠지는 부분의 넓이는 몇 m²인가요?',ARRAY['M5-1-u6-X10','M5-1-u6-X01']::text[],false,'{"seq":3,"concept":"M5-1-u6-C11","difficulty":1,"kind":"mc","stem":"땅에서 빠지는 부분은 밑변 5 m, 높이 6 m인 직각삼각형이에요. 빠지는 부분의 넓이는 몇 m²인가요?","options":[{"t":"15 m²","correct":true},{"t":"30 m²","mis":"M5-1-u6-X10"},{"t":"11 m²","mis":"M5-1-u6-X01"},{"t":"60 m²","mis":"M5-1-u6-X10"}],"explanation":["삼각형의 넓이는 (밑변) × (높이) ÷ 2예요.","5 × 6 = 30이에요.","30 ÷ 2 = 15 — 빠지는 부분은 15 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_basic#4','math',5,1,'u6','L11','g5_1_math_u6_L11_basic','lesson_basic','M5-1-u6-C11',1,'mc','auto','윤아의 방법이에요. 땅을 감싸는 직사각형 160 m²에서 빠지는 부분 15 m²를 빼면 몇 m²인가요?',ARRAY['M5-1-u6-X15','M5-1-u6-X16']::text[],false,'{"seq":4,"concept":"M5-1-u6-C11","difficulty":1,"kind":"mc","stem":"윤아의 방법이에요. 땅을 감싸는 직사각형 160 m²에서 빠지는 부분 15 m²를 빼면 몇 m²인가요?","options":[{"t":"145 m²","correct":true},{"t":"175 m²","mis":"M5-1-u6-X15"},{"t":"155 m²","mis":"M5-1-u6-X16"},{"t":"135 m²","mis":"M5-1-u6-X16"}],"explanation":["윤아는 큰 직사각형에서 빠진 부분을 빼요.","160 − 15 = 145예요.","빼야 할 부분을 더하면 175가 되어 틀려요 — 땅은 145 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_basic#5','math',5,1,'u6','L11','g5_1_math_u6_L11_basic','lesson_basic','M5-1-u6-C11',2,'mc','auto','아빠의 방법이에요. 잘라 낸 사다리꼴은 윗변 5 m, 아랫변 10 m, 높이 6 m예요. 사다리꼴의 넓이는 몇 m²인가요?',ARRAY['M5-1-u6-X10','M5-1-u6-X12']::text[],false,'{"seq":5,"concept":"M5-1-u6-C11","difficulty":2,"kind":"mc","stem":"아빠의 방법이에요. 잘라 낸 사다리꼴은 윗변 5 m, 아랫변 10 m, 높이 6 m예요. 사다리꼴의 넓이는 몇 m²인가요?","options":[{"t":"45 m²","correct":true},{"t":"90 m²","mis":"M5-1-u6-X10"},{"t":"30 m²","mis":"M5-1-u6-X12"},{"t":"21 m²","mis":"M5-1-u6-X12"}],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","(5 + 10) × 6 = 90이에요.","90 ÷ 2 = 45 — 사다리꼴은 45 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_basic#6','math',5,1,'u6','L11','g5_1_math_u6_L11_basic','lesson_basic','M5-1-u6-C11',2,'mc','auto','아빠의 방법이에요. 사다리꼴 45 m²와 정사각형 100 m²를 더하면 땅의 넓이는 몇 m²인가요?',ARRAY['M5-1-u6-X15','M5-1-u6-X16']::text[],false,'{"seq":6,"concept":"M5-1-u6-C11","difficulty":2,"kind":"mc","stem":"아빠의 방법이에요. 사다리꼴 45 m²와 정사각형 100 m²를 더하면 땅의 넓이는 몇 m²인가요?","options":[{"t":"145 m²","correct":true},{"t":"55 m²","mis":"M5-1-u6-X15"},{"t":"155 m²","mis":"M5-1-u6-X16"},{"t":"4500 m²","mis":"M5-1-u6-X16"}],"explanation":["아빠는 땅을 사다리꼴과 정사각형으로 잘라 나누어 더해요.","45 + 100 = 145예요.","땅의 넓이는 145 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_basic#7','math',5,1,'u6','L11','g5_1_math_u6_L11_basic','lesson_basic','M5-1-u6-C11',2,'mc','auto','윤아의 방법(큰 직사각형에서 빼기)과 아빠의 방법(잘라서 나누어 더하기)을 비교하면 어떠한가요?',ARRAY['M5-1-u6-X15']::text[],false,'{"seq":7,"concept":"M5-1-u6-C11","difficulty":2,"kind":"mc","stem":"윤아의 방법(큰 직사각형에서 빼기)과 아빠의 방법(잘라서 나누어 더하기)을 비교하면 어떠한가요?","options":[{"t":"두 방법 모두 145 m²로 같다","correct":true},{"t":"윤아의 방법이 더 넓게 나온다","mis":"M5-1-u6-X15"},{"t":"아빠의 방법이 더 넓게 나온다","mis":"M5-1-u6-X15"},{"t":"방법에 따라 넓이가 달라진다","mis":"M5-1-u6-X15"}],"explanation":["윤아: 160 − 15 = 145예요.","아빠: 45 + 100 = 145예요.","같은 땅의 칸을 센 것이라 두 방법의 답이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_basic#8','math',5,1,'u6','L11','g5_1_math_u6_L11_basic','lesson_basic','M5-1-u6-C11',2,'ox','auto','같은 땅을 나누는 방법에 따라 넓이가 달라질 수 있어요.',ARRAY['M5-1-u6-X15']::text[],true,'{"seq":8,"concept":"M5-1-u6-C11","difficulty":2,"kind":"ox","stem":"같은 땅을 나누는 방법에 따라 넓이가 달라질 수 있어요.","answer":"X","reason_options":[{"t":"자르고 붙여도 칸의 수는 변하지 않으므로","correct":true},{"t":"많이 자를수록 잘린 칸이 사라지므로","mis":"M5-1-u6-X15"}],"mis":"M5-1-u6-X15","explanation":["넓이는 덮은 칸의 수예요.","잘라 나누어도 칸이 사라지거나 생기지 않아요.","그래서 어떻게 나누어도 넓이는 같아요."],"variant_rule":{"alt":[{"stem":"큰 직사각형에서 빼는 방법을 쓸 때는 빠진 부분의 넓이를 큰 직사각형의 넓이에 더해야 해요.","answer":"X","reason_options":[{"t":"빠진 부분은 땅이 아니라 큰 직사각형에서 덜어 내야 하므로","correct":true},{"t":"빠진 부분도 땅을 감싸는 데 쓰였으므로","mis":"M5-1-u6-X15"}],"explanation":["큰 직사각형은 땅보다 넓게 감싼 도형이에요.","빠진 부분은 땅이 아닌 곳이라 덜어 내요.","그래서 (큰 직사각형) − (빠진 부분)이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_basic#9','math',5,1,'u6','L11','g5_1_math_u6_L11_basic','lesson_basic','M5-1-u6-C11',2,'sa','auto','ㄴ자 모양 꽃밭을 두 직사각형으로 나누었더니 하나는 가로 8 m, 세로 5 m이고 다른 하나는 가로 4 m, 세로 3 m였어요. 꽃밭의 넓이는 몇 m²인가요?','{}'::text[],true,'{"seq":9,"concept":"M5-1-u6-C11","difficulty":2,"kind":"sa","stem":"ㄴ자 모양 꽃밭을 두 직사각형으로 나누었더니 하나는 가로 8 m, 세로 5 m이고 다른 하나는 가로 4 m, 세로 3 m였어요. 꽃밭의 넓이는 몇 m²인가요?","answer":["52"],"explanation":["한 직사각형은 8 × 5 = 40이에요.","다른 직사각형은 4 × 3 = 12예요.","40 + 12 = 52 — 꽃밭은 52 m²예요."],"mis":"M5-1-u6-X15","variant_rule":{"alt":[{"stem":"ㄴ자 모양 꽃밭을 두 직사각형으로 나누었더니 하나는 가로 7 m, 세로 4 m이고 다른 하나는 가로 3 m, 세로 5 m였어요. 꽃밭의 넓이는 몇 m²인가요?","answer":["43"],"explanation":["한 직사각형은 7 × 4 = 28이에요.","다른 직사각형은 3 × 5 = 15예요.","28 + 15 = 43 — 꽃밭은 43 m²예요."]},{"stem":"ㄴ자 모양 꽃밭을 두 직사각형으로 나누었더니 하나는 가로 9 m, 세로 6 m이고 다른 하나는 가로 5 m, 세로 2 m였어요. 꽃밭의 넓이는 몇 m²인가요?","answer":["64"],"explanation":["한 직사각형은 9 × 6 = 54예요.","다른 직사각형은 5 × 2 = 10이에요.","54 + 10 = 64 — 꽃밭은 64 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_basic#10','math',5,1,'u6','L11','g5_1_math_u6_L11_basic','lesson_basic','M5-1-u6-C11',3,'sa','auto','가로 12 m, 세로 8 m인 직사각형 땅 한가운데에 가로 4 m, 세로 4 m인 직사각형 연못이 있어요. 연못을 뺀 땅의 넓이는 몇 m²인가요?','{}'::text[],true,'{"seq":10,"concept":"M5-1-u6-C11","difficulty":3,"kind":"sa","stem":"가로 12 m, 세로 8 m인 직사각형 땅 한가운데에 가로 4 m, 세로 4 m인 직사각형 연못이 있어요. 연못을 뺀 땅의 넓이는 몇 m²인가요?","answer":["80"],"explanation":["땅 전체는 12 × 8 = 96이에요.","연못은 4 × 4 = 16이에요.","96 − 16 = 80 — 연못을 뺀 땅은 80 m²예요."],"mis":"M5-1-u6-X15","variant_rule":{"alt":[{"stem":"가로 10 m, 세로 9 m인 직사각형 땅 한가운데에 가로 5 m, 세로 2 m인 직사각형 연못이 있어요. 연못을 뺀 땅의 넓이는 몇 m²인가요?","answer":["80"],"explanation":["땅 전체는 10 × 9 = 90이에요.","연못은 5 × 2 = 10이에요.","90 − 10 = 80 — 연못을 뺀 땅은 80 m²예요."]},{"stem":"가로 11 m, 세로 8 m인 직사각형 땅 한가운데에 가로 3 m, 세로 5 m인 직사각형 연못이 있어요. 연못을 뺀 땅의 넓이는 몇 m²인가요?","answer":["73"],"explanation":["땅 전체는 11 × 8 = 88이에요.","연못은 3 × 5 = 15예요.","88 − 15 = 73 — 연못을 뺀 땅은 73 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_challenge#1','math',5,1,'u6','L11','g5_1_math_u6_L11_challenge','lesson_challenge','M5-1-u6-C11',2,'error','auto','가로 6 cm, 세로 4 cm인 직사각형 오른쪽 아래에 가로 3 cm, 세로 2 cm인 직사각형이 붙은 ㄴ자 모양이 있어요. 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-1-u6-X15','M5-1-u6-X17']::text[],true,'{"seq":1,"concept":"M5-1-u6-C11","difficulty":2,"kind":"error","stem":"가로 6 cm, 세로 4 cm인 직사각형 오른쪽 아래에 가로 3 cm, 세로 2 cm인 직사각형이 붙은 ㄴ자 모양이 있어요. 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「(6 + 3) × (4 + 2) = 54 cm²야.」","correct":true,"mis_target":"M5-1-u6-X15"},{"t":"도현 — 「6 × 4 = 24에 3 × 2 = 6을 더하면 돼.」","mis":"M5-1-u6-X17"},{"t":"하은 — 「그러니 넓이는 30 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["(6 + 3) × (4 + 2)는 ㄴ자 모양을 감싸는 큰 직사각형이에요.","그 안에는 ㄴ자 모양이 아닌 빈 부분까지 들어 있어요.","서윤은 빈 부분을 빼지 않아 잘못 말했어요 — 넓이는 24 + 6 = 30이에요."],"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm인 직사각형 오른쪽 아래에 가로 4 cm, 세로 2 cm인 직사각형이 붙은 ㄴ자 모양이 있어요. 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「(5 + 4) × (3 + 2) = 45 cm²야.」","correct":true,"mis_target":"M5-1-u6-X15"},{"t":"라온 — 「5 × 3 = 15에 4 × 2 = 8을 더하면 돼.」","mis":"M5-1-u6-X17"},{"t":"예준 — 「그러니 넓이는 23 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["(5 + 4) × (3 + 2)는 ㄴ자 모양을 감싸는 큰 직사각형이에요.","그 안에는 ㄴ자 모양이 아닌 빈 부분까지 들어 있어요.","지민은 빈 부분을 빼지 않아 잘못 말했어요 — 넓이는 15 + 8 = 23이에요."]},{"stem":"가로 7 cm, 세로 4 cm인 직사각형 오른쪽 아래에 가로 2 cm, 세로 3 cm인 직사각형이 붙은 ㄴ자 모양이 있어요. 넓이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤아 — 「(7 + 2) × (4 + 3) = 63 cm²야.」","correct":true,"mis_target":"M5-1-u6-X15"},{"t":"시우 — 「7 × 4 = 28에 2 × 3 = 6을 더하면 돼.」","mis":"M5-1-u6-X17"},{"t":"나린 — 「그러니 넓이는 34 cm²야.」","mis":"M5-1-u6-X17"}],"explanation":["(7 + 2) × (4 + 3)은 ㄴ자 모양을 감싸는 큰 직사각형이에요.","그 안에는 ㄴ자 모양이 아닌 빈 부분까지 들어 있어요.","윤아는 빈 부분을 빼지 않아 잘못 말했어요 — 넓이는 28 + 6 = 34예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_challenge#2','math',5,1,'u6','L11','g5_1_math_u6_L11_challenge','lesson_challenge','M5-1-u6-C11',2,'sa','auto','가로 10 m, 세로 8 m인 직사각형 밭에 폭이 1 m인 길을 가로로 하나, 세로로 하나 곧게 냈어요. 길을 뺀 밭의 넓이는 몇 m²인가요?','{}'::text[],true,'{"seq":2,"concept":"M5-1-u6-C11","difficulty":2,"kind":"sa","stem":"가로 10 m, 세로 8 m인 직사각형 밭에 폭이 1 m인 길을 가로로 하나, 세로로 하나 곧게 냈어요. 길을 뺀 밭의 넓이는 몇 m²인가요?","answer":["63"],"explanation":["두 길을 밭 가장자리로 밀어 붙여도 남은 밭의 넓이는 그대로예요.","그러면 남은 밭은 가로 10 − 1 = 9, 세로 8 − 1 = 7인 직사각형이에요.","9 × 7 = 63 — 남은 밭은 63 m²예요. 길이 겹친 1 m²를 두 번 빼지 않아요."],"mis":"M5-1-u6-X15","variant_rule":{"alt":[{"stem":"가로 12 m, 세로 9 m인 직사각형 밭에 폭이 1 m인 길을 가로로 하나, 세로로 하나 곧게 냈어요. 길을 뺀 밭의 넓이는 몇 m²인가요?","answer":["88"],"explanation":["두 길을 밭 가장자리로 밀어 붙여도 남은 밭의 넓이는 그대로예요.","그러면 남은 밭은 가로 12 − 1 = 11, 세로 9 − 1 = 8인 직사각형이에요.","11 × 8 = 88 — 남은 밭은 88 m²예요. 길이 겹친 1 m²를 두 번 빼지 않아요."]},{"stem":"가로 9 m, 세로 7 m인 직사각형 밭에 폭이 1 m인 길을 가로로 하나, 세로로 하나 곧게 냈어요. 길을 뺀 밭의 넓이는 몇 m²인가요?","answer":["48"],"explanation":["두 길을 밭 가장자리로 밀어 붙여도 남은 밭의 넓이는 그대로예요.","그러면 남은 밭은 가로 9 − 1 = 8, 세로 7 − 1 = 6인 직사각형이에요.","8 × 6 = 48 — 남은 밭은 48 m²예요. 길이 겹친 1 m²를 두 번 빼지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_challenge#3','math',5,1,'u6','L11','g5_1_math_u6_L11_challenge','lesson_challenge','M5-1-u6-C11',3,'sa','auto','한 변이 10 cm인 정사각형 타일 안에 네 변의 가운데 점을 이은 마름모 무늬를 그렸어요. 마름모 바깥 부분의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":3,"concept":"M5-1-u6-C11","difficulty":3,"kind":"sa","stem":"한 변이 10 cm인 정사각형 타일 안에 네 변의 가운데 점을 이은 마름모 무늬를 그렸어요. 마름모 바깥 부분의 넓이는 몇 cm²인가요?","answer":["50"],"explanation":["정사각형은 10 × 10 = 100이에요.","마름모의 두 대각선은 10 cm, 10 cm라 10 × 10 ÷ 2 = 50이에요.","100 − 50 = 50 — 바깥 부분은 50 cm²예요."],"variant_rule":{"alt":[{"stem":"한 변이 8 cm인 정사각형 타일 안에 네 변의 가운데 점을 이은 마름모 무늬를 그렸어요. 마름모 바깥 부분의 넓이는 몇 cm²인가요?","answer":["32"],"explanation":["정사각형은 8 × 8 = 64예요.","마름모의 두 대각선은 8 cm, 8 cm라 8 × 8 ÷ 2 = 32예요.","64 − 32 = 32 — 바깥 부분은 32 cm²예요."]},{"stem":"한 변이 12 cm인 정사각형 타일 안에 네 변의 가운데 점을 이은 마름모 무늬를 그렸어요. 마름모 바깥 부분의 넓이는 몇 cm²인가요?","answer":["72"],"explanation":["정사각형은 12 × 12 = 144예요.","마름모의 두 대각선은 12 cm, 12 cm라 12 × 12 ÷ 2 = 72예요.","144 − 72 = 72 — 바깥 부분은 72 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_challenge#4','math',5,1,'u6','L11','g5_1_math_u6_L11_challenge','lesson_challenge','M5-1-u6-C11',3,'sa','auto','윗변 6 cm, 아랫변 10 cm, 높이 5 cm인 사다리꼴을 밑변 6 cm인 평행사변형과 삼각형으로 나누었어요. 사다리꼴의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":4,"concept":"M5-1-u6-C11","difficulty":3,"kind":"sa","stem":"윗변 6 cm, 아랫변 10 cm, 높이 5 cm인 사다리꼴을 밑변 6 cm인 평행사변형과 삼각형으로 나누었어요. 사다리꼴의 넓이는 몇 cm²인가요?","answer":["40"],"explanation":["평행사변형은 6 × 5 = 30이에요.","삼각형은 밑변 10 − 6 = 4, 높이 5 — 4 × 5 ÷ 2 = 10이에요.","30 + 10 = 40 — 공식 (6 + 10) × 5 ÷ 2 = 40과 같아요."],"variant_rule":{"alt":[{"stem":"윗변 4 cm, 아랫변 10 cm, 높이 6 cm인 사다리꼴을 밑변 4 cm인 평행사변형과 삼각형으로 나누었어요. 사다리꼴의 넓이는 몇 cm²인가요?","answer":["42"],"explanation":["평행사변형은 4 × 6 = 24예요.","삼각형은 밑변 10 − 4 = 6, 높이 6 — 6 × 6 ÷ 2 = 18이에요.","24 + 18 = 42 — 공식 (4 + 10) × 6 ÷ 2 = 42와 같아요."]},{"stem":"윗변 5 cm, 아랫변 9 cm, 높이 7 cm인 사다리꼴을 밑변 5 cm인 평행사변형과 삼각형으로 나누었어요. 사다리꼴의 넓이는 몇 cm²인가요?","answer":["49"],"explanation":["평행사변형은 5 × 7 = 35예요.","삼각형은 밑변 9 − 5 = 4, 높이 7 — 4 × 7 ÷ 2 = 14예요.","35 + 14 = 49 — 공식 (5 + 9) × 7 ÷ 2 = 49와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_challenge#5','math',5,1,'u6','L11','g5_1_math_u6_L11_challenge','lesson_challenge','M5-1-u6-C11',3,'mc','auto','가로 10 m, 세로 8 m인 직사각형에서 가로 4 m, 세로 3 m인 직사각형 귀퉁이가 빠진 땅이에요. 넓이를 구하는 방법으로 잘못된 것은 어느 것인가요?',ARRAY['M5-1-u6-X17']::text[],true,'{"seq":5,"concept":"M5-1-u6-C11","difficulty":3,"kind":"mc","stem":"가로 10 m, 세로 8 m인 직사각형에서 가로 4 m, 세로 3 m인 직사각형 귀퉁이가 빠진 땅이에요. 넓이를 구하는 방법으로 잘못된 것은 어느 것인가요?","options":[{"t":"10 × 8 + 4 × 3","correct":true},{"t":"10 × 8 − 4 × 3","mis":"M5-1-u6-X17"},{"t":"6 × 8 + 4 × 5","mis":"M5-1-u6-X17"},{"t":"10 × 5 + 6 × 3","mis":"M5-1-u6-X17"}],"explanation":["빠진 귀퉁이는 빼야 해요 — 10 × 8 − 4 × 3 = 68이에요.","세로로 나누면 6 × 8 + 4 × 5 = 68, 가로로 나누면 10 × 5 + 6 × 3 = 68이에요.","10 × 8 + 4 × 3은 빠진 부분을 더해 틀렸어요."],"variant_rule":{"alt":[{"stem":"ㄱ자 모양 땅을 두 직사각형으로 나누어 구할 때 잘못된 것은 어느 것인가요?","options":[{"t":"두 직사각형이 겹치는 부분까지 두 번 넣어 더한다","correct":true},{"t":"겹치지 않게 나누어 더한다","mis":"M5-1-u6-X17"},{"t":"감싸는 직사각형에서 빈 부분을 뺀다","mis":"M5-1-u6-X17"},{"t":"세로로 나누든 가로로 나누든 같은 답을 얻는다","mis":"M5-1-u6-X17"}],"explanation":["겹친 부분을 두 번 넣으면 그만큼 넓게 셈해요.","겹치거나 빠뜨리지 않게 나누어야 해요.","그러면 어떤 방법이든 답이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_challenge#6','math',5,1,'u6','L11','g5_1_math_u6_L11_challenge','lesson_challenge','M5-1-u6-C11',3,'sa','auto','가로 8 cm, 세로 6 cm인 직사각형 위에 밑변 8 cm, 높이 3 cm인 삼각형 지붕을 얹은 집 모양 그림이에요. 그림의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":6,"concept":"M5-1-u6-C11","difficulty":3,"kind":"sa","stem":"가로 8 cm, 세로 6 cm인 직사각형 위에 밑변 8 cm, 높이 3 cm인 삼각형 지붕을 얹은 집 모양 그림이에요. 그림의 넓이는 몇 cm²인가요?","answer":["60"],"explanation":["직사각형은 8 × 6 = 48이에요.","삼각형 지붕은 8 × 3 ÷ 2 = 12예요.","48 + 12 = 60 — 그림은 60 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 10 cm, 세로 5 cm인 직사각형 위에 밑변 10 cm, 높이 4 cm인 삼각형 지붕을 얹은 집 모양 그림이에요. 그림의 넓이는 몇 cm²인가요?","answer":["70"],"explanation":["직사각형은 10 × 5 = 50이에요.","삼각형 지붕은 10 × 4 ÷ 2 = 20이에요.","50 + 20 = 70 — 그림은 70 cm²예요."]},{"stem":"가로 6 cm, 세로 7 cm인 직사각형 위에 밑변 6 cm, 높이 4 cm인 삼각형 지붕을 얹은 집 모양 그림이에요. 그림의 넓이는 몇 cm²인가요?","answer":["54"],"explanation":["직사각형은 6 × 7 = 42예요.","삼각형 지붕은 6 × 4 ÷ 2 = 12예요.","42 + 12 = 54 — 그림은 54 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_challenge#7','math',5,1,'u6','L11','g5_1_math_u6_L11_challenge','lesson_challenge','M5-1-u6-C11',3,'sa','auto','모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":7,"concept":"M5-1-u6-C11","difficulty":3,"kind":"sa","stem":"모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["28"],"explanation":["도형을 감싸는 직사각형은 가로 7칸, 세로 5칸 — 7 × 5 = 35예요.","빠진 부분은 밑변 7칸, 높이 2칸인 삼각형 — 7 × 2 ÷ 2 = 7이에요.","35 − 7 = 28 — 넓이는 28 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":105,"grid":15,"poly":[[[15,15],[120,15],[120,90],[60,60],[15,90]]],"show":[]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["28"],"explanation":["도형을 감싸는 직사각형은 가로 8칸, 세로 5칸 — 8 × 5 = 40이에요.","빠진 부분은 밑변 8칸, 높이 3칸인 삼각형 — 8 × 3 ÷ 2 = 12예요.","40 − 12 = 28 — 넓이는 28 cm²예요."],"asset":{"type":"geo","items":[{"w":150,"h":105,"grid":15,"poly":[[[15,90],[15,15],[75,60],[135,15],[135,90]]],"show":[]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["18"],"explanation":["도형을 감싸는 직사각형은 가로 6칸, 세로 4칸 — 6 × 4 = 24예요.","빠진 부분은 밑변 4칸, 높이 3칸인 삼각형 — 4 × 3 ÷ 2 = 6이에요.","24 − 6 = 18 — 넓이는 18 cm²예요."],"asset":{"type":"geo","items":[{"w":120,"h":105,"grid":15,"poly":[[[15,15],[105,15],[105,75],[15,75],[60,45]]],"show":[]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_challenge#8','math',5,1,'u6','L11','g5_1_math_u6_L11_challenge','lesson_challenge','M5-1-u6-C11',4,'sa','auto','가로 10 cm, 세로 8 cm인 직사각형 ㄱㄴㄷㄹ에서 변 ㄴㄷ 위의 아무 점 ㅁ을 골라 꼭짓점 ㄱ, ㄹ과 이어 삼각형 ㄱㅁㄹ을 만들었어요. 삼각형 ㄱㅁㄹ의 넓이는 몇 cm²인가요?','{}'::text[],true,'{"seq":8,"concept":"M5-1-u6-C11","difficulty":4,"kind":"sa","stem":"가로 10 cm, 세로 8 cm인 직사각형 ㄱㄴㄷㄹ에서 변 ㄴㄷ 위의 아무 점 ㅁ을 골라 꼭짓점 ㄱ, ㄹ과 이어 삼각형 ㄱㅁㄹ을 만들었어요. 삼각형 ㄱㅁㄹ의 넓이는 몇 cm²인가요?","answer":["40"],"explanation":["삼각형 ㄱㅁㄹ에서 변 ㄱㄹ을 밑변으로 하면 길이는 가로 10 cm예요.","점 ㅁ은 변 ㄴㄷ 위에 있어 어디에 있든 높이는 세로 8 cm예요.","10 × 8 ÷ 2 = 40 — 점 ㅁ이 어디에 있든 40 cm²예요."],"variant_rule":{"alt":[{"stem":"가로 12 cm, 세로 6 cm인 직사각형 ㄱㄴㄷㄹ에서 변 ㄴㄷ 위의 아무 점 ㅁ을 골라 꼭짓점 ㄱ, ㄹ과 이어 삼각형 ㄱㅁㄹ을 만들었어요. 삼각형 ㄱㅁㄹ의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["삼각형 ㄱㅁㄹ에서 변 ㄱㄹ을 밑변으로 하면 길이는 가로 12 cm예요.","점 ㅁ은 변 ㄴㄷ 위에 있어 어디에 있든 높이는 세로 6 cm예요.","12 × 6 ÷ 2 = 36 — 점 ㅁ이 어디에 있든 36 cm²예요."]},{"stem":"가로 14 cm, 세로 6 cm인 직사각형 ㄱㄴㄷㄹ에서 변 ㄴㄷ 위의 아무 점 ㅁ을 골라 꼭짓점 ㄱ, ㄹ과 이어 삼각형 ㄱㅁㄹ을 만들었어요. 삼각형 ㄱㅁㄹ의 넓이는 몇 cm²인가요?","answer":["42"],"explanation":["삼각형 ㄱㅁㄹ에서 변 ㄱㄹ을 밑변으로 하면 길이는 가로 14 cm예요.","점 ㅁ은 변 ㄴㄷ 위에 있어 어디에 있든 높이는 세로 6 cm예요.","14 × 6 ÷ 2 = 42 — 점 ㅁ이 어디에 있든 42 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_challenge#9','math',5,1,'u6','L11','g5_1_math_u6_L11_challenge','lesson_challenge','M5-1-u6-C11',4,'sa','auto','한 변이 9 m인 정사각형 마당 안쪽 가장자리를 따라 폭 1 m인 길을 빙 둘러 냈어요. 길의 넓이는 몇 m²인가요?','{}'::text[],true,'{"seq":9,"concept":"M5-1-u6-C11","difficulty":4,"kind":"sa","stem":"한 변이 9 m인 정사각형 마당 안쪽 가장자리를 따라 폭 1 m인 길을 빙 둘러 냈어요. 길의 넓이는 몇 m²인가요?","answer":["32"],"explanation":["마당 전체는 9 × 9 = 81이에요.","길 안쪽 정사각형은 한 변이 9 − 1 − 1 = 7 — 7 × 7 = 49예요.","81 − 49 = 32 — 길은 32 m²예요."],"mis":"M5-1-u6-X15","variant_rule":{"alt":[{"stem":"한 변이 10 m인 정사각형 마당 안쪽 가장자리를 따라 폭 1 m인 길을 빙 둘러 냈어요. 길의 넓이는 몇 m²인가요?","answer":["36"],"explanation":["마당 전체는 10 × 10 = 100이에요.","길 안쪽 정사각형은 한 변이 10 − 1 − 1 = 8 — 8 × 8 = 64예요.","100 − 64 = 36 — 길은 36 m²예요."]},{"stem":"한 변이 8 m인 정사각형 마당 안쪽 가장자리를 따라 폭 1 m인 길을 빙 둘러 냈어요. 길의 넓이는 몇 m²인가요?","answer":["28"],"explanation":["마당 전체는 8 × 8 = 64예요.","길 안쪽 정사각형은 한 변이 8 − 1 − 1 = 6 — 6 × 6 = 36이에요.","64 − 36 = 28 — 길은 28 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_L11_challenge#10','math',5,1,'u6','L11','g5_1_math_u6_L11_challenge','lesson_challenge','M5-1-u6-C11',4,'essay','teacher','반듯하지 않은 땅의 넓이를 두 가지 방법(나누어 더하기, 큰 도형에서 빼기)으로 구하면 답이 같은 까닭을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-1-u6-C11","difficulty":4,"kind":"essay","stem":"반듯하지 않은 땅의 넓이를 두 가지 방법(나누어 더하기, 큰 도형에서 빼기)으로 구하면 답이 같은 까닭을 설명하세요.","answer_guide":{"answer":"예: 넓이는 땅을 덮은 1 m² 칸의 수이다. 땅을 잘라 나누어도 칸이 사라지거나 새로 생기지 않으므로 나눈 넓이의 합은 처음 넓이와 같다. 큰 직사각형에서 빼는 방법도 땅이 아닌 칸만 덜어 내므로 남은 칸의 수가 땅의 칸 수와 같다. 그래서 겹치거나 빠뜨리지 않으면 두 방법의 답이 같다.","scoring_points":["넓이가 칸의 수라고 썼는가","자르거나 빼도 땅의 칸 수는 변하지 않는다고 썼는가","겹치거나 빠뜨리지 않아야 한다는 조건을 썼는가"]},"explanation":["넓이는 칸의 수예요.","나누거나 빼도 땅의 칸 수는 그대로예요.","겹침·빠짐이 없으면 답이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#1','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C1',1,'mc','auto','둘레는 무엇을 뜻하나요?',ARRAY['M5-1-u6-X01','M5-1-u6-X03','M5-1-u6-X16']::text[],false,'{"seq":1,"concept":"M5-1-u6-C1","difficulty":1,"kind":"mc","stem":"둘레는 무엇을 뜻하나요?","options":[{"t":"도형의 가장자리를 따라 잰 길이","correct":true},{"t":"도형 안쪽을 덮은 칸의 수","mis":"M5-1-u6-X01"},{"t":"가장 긴 변 하나의 길이","mis":"M5-1-u6-X03"},{"t":"변의 수","mis":"M5-1-u6-X16"}],"explanation":["게시판 가장자리에 두르는 색 띠지의 길이를 떠올려 봐요.","가장자리를 따라 한 바퀴 잰 길이가 둘레예요.","안쪽을 덮은 칸의 수는 넓이예요 — 둘은 다른 양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#2','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C1',2,'sa','auto','둘레가 20 cm인 직사각형의 가로가 9 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":2,"concept":"M5-1-u6-C1","difficulty":2,"kind":"sa","stem":"둘레가 20 cm인 직사각형의 가로가 9 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?","answer":["9"],"explanation":["가로 + 세로 = 20 ÷ 2 = 10이에요.","세로 = 10 − 9 = 1이에요.","넓이는 9 × 1 = 9 — 9 cm²예요."],"mis":"M5-1-u6-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#3','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C2',1,'sa','auto','가로 9 cm, 세로 4 cm인 직사각형의 둘레는 몇 cm인가요?','{}'::text[],false,'{"seq":3,"concept":"M5-1-u6-C2","difficulty":1,"kind":"sa","stem":"가로 9 cm, 세로 4 cm인 직사각형의 둘레는 몇 cm인가요?","answer":["26"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","9 + 4 + 9 + 4 = 26이에요.","(9 + 4) × 2 = 26으로 구해도 돼요 — 둘레는 26 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#4','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C2',2,'sa','auto','평행사변형의 밑변이 8 cm, 이웃한 변이 4 cm예요. 둘레는 몇 cm인가요?','{}'::text[],false,'{"seq":4,"concept":"M5-1-u6-C2","difficulty":2,"kind":"sa","stem":"평행사변형의 밑변이 8 cm, 이웃한 변이 4 cm예요. 둘레는 몇 cm인가요?","answer":["24"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","8 + 4 + 8 + 4 = 24예요.","(8 + 4) × 2 = 24 — 둘레는 24 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#5','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C3',1,'mc','auto','한 변의 길이가 6 cm인 정육각형의 둘레는 몇 cm인가요?',ARRAY['M5-1-u6-X05']::text[],false,'{"seq":5,"concept":"M5-1-u6-C3","difficulty":1,"kind":"mc","stem":"한 변의 길이가 6 cm인 정육각형의 둘레는 몇 cm인가요?","options":[{"t":"36 cm","correct":true},{"t":"24 cm","mis":"M5-1-u6-X05"},{"t":"42 cm","mis":"M5-1-u6-X05"},{"t":"30 cm","mis":"M5-1-u6-X05"}],"explanation":["정육각형은 변이 6개이고 길이가 모두 같아요.","6 cm를 6번 더하는 것과 같아요.","6 × 6 = 36 — 둘레는 36 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#6','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C3',3,'sa','auto','길이가 100 cm인 철사로 한 변이 7 cm인 정육각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?','{}'::text[],false,'{"seq":6,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"길이가 100 cm인 철사로 한 변이 7 cm인 정육각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?","answer":["58"],"explanation":["정육각형을 만드는 데 쓴 철사는 둘레만큼이에요.","7 × 6 = 42예요.","100 − 42 = 58 — 남은 철사는 58 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#7','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C4',1,'sa','auto','도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 5칸씩 4줄이었어요. 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":7,"concept":"M5-1-u6-C4","difficulty":1,"kind":"sa","stem":"도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 5칸씩 4줄이었어요. 넓이는 몇 cm²인가요?","answer":["20"],"explanation":["한 줄에 5칸, 그런 줄이 4줄이에요.","5 × 4 = 20 — 칸은 모두 20개예요.","한 칸이 1 cm²니 넓이는 20 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#8','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C4',2,'sa','auto','모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":8,"concept":"M5-1-u6-C4","difficulty":2,"kind":"sa","stem":"모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["14"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 14칸이에요.","한 칸이 1 cm²니 넓이는 14 cm²예요."],"asset":{"type":"geo","items":[{"w":105,"h":105,"grid":15,"poly":[[[15,15],[75,15],[75,45],[45,45],[45,90],[15,90]]],"show":[]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#9','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C5',1,'sa','auto','가로 9 cm, 세로 4 cm인 직사각형 카드의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":9,"concept":"M5-1-u6-C5","difficulty":1,"kind":"sa","stem":"가로 9 cm, 세로 4 cm인 직사각형 카드의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["한 줄에 9칸씩 4줄이라고 생각해요.","넓이는 (가로) × (세로)예요.","9 × 4 = 36 — 넓이는 36 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#10','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C5',2,'mc','auto','한 변의 길이가 7 cm인 정사각형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X07','M5-1-u6-X16']::text[],false,'{"seq":10,"concept":"M5-1-u6-C5","difficulty":2,"kind":"mc","stem":"한 변의 길이가 7 cm인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"49 cm²","correct":true},{"t":"28 cm²","mis":"M5-1-u6-X01"},{"t":"14 cm²","mis":"M5-1-u6-X07"},{"t":"35 cm²","mis":"M5-1-u6-X16"}],"explanation":["정사각형은 가로와 세로가 같아요.","넓이는 (한 변) × (한 변)이에요.","7 × 7 = 49 — 넓이는 49 cm²예요. 7 × 4 = 28은 둘레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#11','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C5',3,'sa','auto','넓이가 48 cm²인 직사각형의 가로가 8 cm예요. 세로는 몇 cm인가요?','{}'::text[],false,'{"seq":11,"concept":"M5-1-u6-C5","difficulty":3,"kind":"sa","stem":"넓이가 48 cm²인 직사각형의 가로가 8 cm예요. 세로는 몇 cm인가요?","answer":["6"],"explanation":["(가로) × (세로) = (넓이)예요.","8 × □ = 48이니 □ = 48 ÷ 8이에요.","48 ÷ 8 = 6 — 세로는 6 cm예요."],"mis":"M5-1-u6-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#12','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C6',1,'mc','auto','1 m²는 몇 cm²인가요?',ARRAY['M5-1-u6-X07','M5-1-u6-X16']::text[],false,'{"seq":12,"concept":"M5-1-u6-C6","difficulty":1,"kind":"mc","stem":"1 m²는 몇 cm²인가요?","options":[{"t":"10000 cm²","correct":true},{"t":"100 cm²","mis":"M5-1-u6-X07"},{"t":"1000 cm²","mis":"M5-1-u6-X07"},{"t":"1000000 cm²","mis":"M5-1-u6-X16"}],"explanation":["1 m = 100 cm예요.","한 변 1 m 정사각형은 가로 100 cm, 세로 100 cm예요.","100 × 100 = 10000 — 1 m² = 10000 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#13','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C6',3,'sa','auto','가로 800 cm, 세로 150 cm인 현수막이 있어요. 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":13,"concept":"M5-1-u6-C6","difficulty":3,"kind":"sa","stem":"가로 800 cm, 세로 150 cm인 현수막이 있어요. 넓이는 몇 m²인가요?","answer":["12"],"explanation":["cm로 곱하면 800 × 150 = 120000이에요 — 120000 cm²예요.","1 m² = 10000 cm²예요.","120000 ÷ 10000 = 12 — 넓이는 12 m²예요."],"mis":"M5-1-u6-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#14','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C7',1,'sa','auto','밑변이 9 cm, 높이가 4 cm인 평행사변형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":14,"concept":"M5-1-u6-C7","difficulty":1,"kind":"sa","stem":"밑변이 9 cm, 높이가 4 cm인 평행사변형의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 9, 높이 4를 곱해요.","9 × 4 = 36 — 넓이는 36 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#15','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C7',2,'mc','auto','밑변 7 cm, 이웃한 변 5 cm, 높이 4 cm인 평행사변형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X09','M5-1-u6-X10','M5-1-u6-X01']::text[],false,'{"seq":15,"concept":"M5-1-u6-C7","difficulty":2,"kind":"mc","stem":"밑변 7 cm, 이웃한 변 5 cm, 높이 4 cm인 평행사변형의 넓이는 몇 cm²인가요?","options":[{"t":"28 cm²","correct":true},{"t":"35 cm²","mis":"M5-1-u6-X09"},{"t":"14 cm²","mis":"M5-1-u6-X10"},{"t":"24 cm²","mis":"M5-1-u6-X01"}],"explanation":["넓이에는 이웃한 변이 아니라 높이를 써요.","잘라 옮긴 직사각형의 세로가 높이 4 cm이기 때문이에요.","7 × 4 = 28 — 넓이는 28 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#16','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C7',3,'sa','auto','밑변 12 cm, 높이 5 cm인 평행사변형이 있어요. 길이가 10 cm인 이웃한 변을 밑변으로 하면 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":16,"concept":"M5-1-u6-C7","difficulty":3,"kind":"sa","stem":"밑변 12 cm, 높이 5 cm인 평행사변형이 있어요. 길이가 10 cm인 이웃한 변을 밑변으로 하면 높이는 몇 cm인가요?","answer":["6"],"explanation":["넓이는 밑변을 어느 쪽으로 정해도 같아요 — 12 × 5 = 60이에요.","새 밑변 10 cm로 □ × 10 = 60이에요.","60 ÷ 10 = 6 — 높이는 6 cm예요."],"mis":"M5-1-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#17','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C8',1,'sa','auto','밑변이 7 cm, 높이가 6 cm인 삼각형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":17,"concept":"M5-1-u6-C8","difficulty":1,"kind":"sa","stem":"밑변이 7 cm, 높이가 6 cm인 삼각형의 넓이는 몇 cm²인가요?","answer":["21"],"explanation":["삼각형의 넓이는 (밑변의 길이) × (높이) ÷ 2예요.","7 × 6 = 42는 평행사변형 전체예요.","42 ÷ 2 = 21 — 넓이는 21 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#18','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C8',2,'mc','auto','삼각형 ㄱㄴㄷ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 것은 어느 것인가요?',ARRAY['M5-1-u6-X11','M5-1-u6-X17']::text[],false,'{"seq":18,"concept":"M5-1-u6-C8","difficulty":2,"kind":"mc","stem":"삼각형 ㄱㄴㄷ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 것은 어느 것인가요?","options":[{"t":"선분 ㄱㄹ","correct":true},{"t":"선분 ㄱㄴ","mis":"M5-1-u6-X11"},{"t":"선분 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"선분 ㄱㄷ","mis":"M5-1-u6-X11"}],"explanation":["밑변과 마주 보는 꼭짓점 ㄱ에서 밑변에 수직으로 그은 선분이 높이예요.","높이는 삼각형 안에 있어요.","그래서 높이는 선분 ㄱㄹ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[60,15],"ㄴ":[15,75],"ㄷ":[120,75],"ㄹ":[60,75]},"poly":[["ㄱ","ㄴ","ㄷ"]],"seg":[["ㄱ","ㄹ"]],"right":[["ㄱ","ㄹ","ㄷ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#19','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C8',4,'sa','auto','세 변이 15 cm, 20 cm, 25 cm인 직각삼각형에서 가장 긴 변 25 cm를 밑변으로 하면 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":19,"concept":"M5-1-u6-C8","difficulty":4,"kind":"sa","stem":"세 변이 15 cm, 20 cm, 25 cm인 직각삼각형에서 가장 긴 변 25 cm를 밑변으로 하면 높이는 몇 cm인가요?","answer":["12"],"explanation":["직각을 낀 두 변으로 넓이를 구하면 15 × 20 ÷ 2 = 150이에요.","밑변을 25 cm로 바꾸어도 넓이는 같으니 25 × □ ÷ 2 = 150이에요.","□ = 150 × 2 ÷ 25 = 12 — 높이는 12 cm예요."],"mis":"M5-1-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#20','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C9',2,'sa','auto','윗변 6 cm, 아랫변 10 cm, 높이 5 cm인 사다리꼴의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":20,"concept":"M5-1-u6-C9","difficulty":2,"kind":"sa","stem":"윗변 6 cm, 아랫변 10 cm, 높이 5 cm인 사다리꼴의 넓이는 몇 cm²인가요?","answer":["40"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","6 + 10 = 16이에요.","(6 + 10) × 5 ÷ 2 = 40 — 넓이는 40 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#21','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C9',3,'sa','auto','넓이가 42 m²인 사다리꼴의 윗변이 10 m, 아랫변이 4 m예요. 높이는 몇 m인가요?','{}'::text[],false,'{"seq":21,"concept":"M5-1-u6-C9","difficulty":3,"kind":"sa","stem":"넓이가 42 m²인 사다리꼴의 윗변이 10 m, 아랫변이 4 m예요. 높이는 몇 m인가요?","answer":["6"],"explanation":["(10 + 4) × □ ÷ 2 = 42예요.","14 × □ = 42 × 2 = 84예요.","□ = 84 ÷ 14 = 6 — 높이는 6 m예요."],"mis":"M5-1-u6-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#22','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C10',2,'sa','auto','두 대각선의 길이가 12 cm와 5 cm인 마름모의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":22,"concept":"M5-1-u6-C10","difficulty":2,"kind":"sa","stem":"두 대각선의 길이가 12 cm와 5 cm인 마름모의 넓이는 몇 cm²인가요?","answer":["30"],"explanation":["마름모를 감싸는 직사각형은 12 × 5 = 60이에요.","마름모는 그 절반이에요.","12 × 5 ÷ 2 = 30 — 넓이는 30 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#23','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C10',3,'sa','auto','넓이가 40 cm²인 마름모의 한 대각선이 10 cm예요. 다른 대각선은 몇 cm인가요?','{}'::text[],false,'{"seq":23,"concept":"M5-1-u6-C10","difficulty":3,"kind":"sa","stem":"넓이가 40 cm²인 마름모의 한 대각선이 10 cm예요. 다른 대각선은 몇 cm인가요?","answer":["8"],"explanation":["10 × □ ÷ 2 = 40이에요.","10 × □ = 40 × 2 = 80이에요.","□ = 80 ÷ 10 = 8 — 다른 대각선은 8 cm예요."],"mis":"M5-1-u6-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#24','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C11',4,'sa','auto','한 변이 9 m인 정사각형 마당 안쪽 가장자리를 따라 폭 1 m인 길을 빙 둘러 냈어요. 길의 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":24,"concept":"M5-1-u6-C11","difficulty":4,"kind":"sa","stem":"한 변이 9 m인 정사각형 마당 안쪽 가장자리를 따라 폭 1 m인 길을 빙 둘러 냈어요. 길의 넓이는 몇 m²인가요?","answer":["32"],"explanation":["마당 전체는 9 × 9 = 81이에요.","길 안쪽 정사각형은 한 변이 9 − 1 − 1 = 7 — 7 × 7 = 49예요.","81 − 49 = 32 — 길은 32 m²예요."],"mis":"M5-1-u6-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_a#25','math',5,1,'u6','','g5_1_math_u6_review_a','unit_review','M5-1-u6-C11',4,'sa','auto','가로 10 cm, 세로 8 cm인 직사각형 종이의 한 귀퉁이에서 가로 4 cm, 세로 3 cm인 직사각형을 잘라 냈어요. 남은 종이의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":25,"concept":"M5-1-u6-C11","difficulty":4,"kind":"sa","stem":"가로 10 cm, 세로 8 cm인 직사각형 종이의 한 귀퉁이에서 가로 4 cm, 세로 3 cm인 직사각형을 잘라 냈어요. 남은 종이의 넓이는 몇 cm²인가요?","answer":["68"],"explanation":["처음 종이의 넓이는 10 × 8 = 80이에요.","잘라 낸 부분의 넓이는 4 × 3 = 12예요.","80 − 12 = 68 — 남은 넓이는 68 cm²예요."],"mis":"M5-1-u6-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#1','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C1',1,'mc','auto','넓이는 무엇을 뜻하나요?',ARRAY['M5-1-u6-X01','M5-1-u6-X16']::text[],false,'{"seq":1,"concept":"M5-1-u6-C1","difficulty":1,"kind":"mc","stem":"넓이는 무엇을 뜻하나요?","options":[{"t":"같은 크기의 칸으로 안쪽을 덮은 칸의 수","correct":true},{"t":"가장자리를 따라 잰 길이","mis":"M5-1-u6-X01"},{"t":"가장 긴 변의 길이","mis":"M5-1-u6-X01"},{"t":"변의 수","mis":"M5-1-u6-X16"}],"explanation":["게시판 안쪽을 도화지로 덮는 것을 떠올려 봐요.","같은 크기의 칸으로 덮었을 때 칸이 몇 개인지가 넓이예요.","가장자리를 따라 잰 길이는 둘레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#2','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C1',2,'sa','auto','둘레가 24 cm인 직사각형의 가로가 10 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":2,"concept":"M5-1-u6-C1","difficulty":2,"kind":"sa","stem":"둘레가 24 cm인 직사각형의 가로가 10 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?","answer":["20"],"explanation":["가로 + 세로 = 24 ÷ 2 = 12예요.","세로 = 12 − 10 = 2예요.","넓이는 10 × 2 = 20 — 20 cm²예요."],"mis":"M5-1-u6-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#3','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C2',1,'sa','auto','가로 8 cm, 세로 6 cm인 직사각형의 둘레는 몇 cm인가요?','{}'::text[],false,'{"seq":3,"concept":"M5-1-u6-C2","difficulty":1,"kind":"sa","stem":"가로 8 cm, 세로 6 cm인 직사각형의 둘레는 몇 cm인가요?","answer":["28"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","8 + 6 + 8 + 6 = 28이에요.","(8 + 6) × 2 = 28로 구해도 돼요 — 둘레는 28 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#4','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C2',2,'sa','auto','평행사변형의 밑변이 9 cm, 이웃한 변이 5 cm예요. 둘레는 몇 cm인가요?','{}'::text[],false,'{"seq":4,"concept":"M5-1-u6-C2","difficulty":2,"kind":"sa","stem":"평행사변형의 밑변이 9 cm, 이웃한 변이 5 cm예요. 둘레는 몇 cm인가요?","answer":["28"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","9 + 5 + 9 + 5 = 28이에요.","(9 + 5) × 2 = 28 — 둘레는 28 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#5','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C3',1,'mc','auto','한 변의 길이가 7 cm인 정오각형의 둘레는 몇 cm인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X16']::text[],false,'{"seq":5,"concept":"M5-1-u6-C3","difficulty":1,"kind":"mc","stem":"한 변의 길이가 7 cm인 정오각형의 둘레는 몇 cm인가요?","options":[{"t":"35 cm","correct":true},{"t":"28 cm","mis":"M5-1-u6-X05"},{"t":"42 cm","mis":"M5-1-u6-X05"},{"t":"12 cm","mis":"M5-1-u6-X16"}],"explanation":["정오각형은 변이 5개이고 길이가 모두 같아요.","7 cm를 5번 더하는 것과 같아요.","7 × 5 = 35 — 둘레는 35 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#6','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C3',3,'sa','auto','길이가 90 cm인 철사로 한 변이 13 cm인 정오각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?','{}'::text[],false,'{"seq":6,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"길이가 90 cm인 철사로 한 변이 13 cm인 정오각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?","answer":["25"],"explanation":["정오각형을 만드는 데 쓴 철사는 둘레만큼이에요.","13 × 5 = 65예요.","90 − 65 = 25 — 남은 철사는 25 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#7','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C4',1,'sa','auto','도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 6칸씩 3줄이었어요. 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":7,"concept":"M5-1-u6-C4","difficulty":1,"kind":"sa","stem":"도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 6칸씩 3줄이었어요. 넓이는 몇 cm²인가요?","answer":["18"],"explanation":["한 줄에 6칸, 그런 줄이 3줄이에요.","6 × 3 = 18 — 칸은 모두 18개예요.","한 칸이 1 cm²니 넓이는 18 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#8','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C4',2,'sa','auto','모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":8,"concept":"M5-1-u6-C4","difficulty":2,"kind":"sa","stem":"모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["18"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 18칸이에요.","한 칸이 1 cm²니 넓이는 18 cm²예요."],"asset":{"type":"geo","items":[{"w":135,"h":90,"grid":15,"poly":[[[15,15],[105,15],[105,45],[60,45],[60,75],[15,75]]],"show":[]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#9','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C5',1,'sa','auto','가로 8 cm, 세로 7 cm인 직사각형 카드의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":9,"concept":"M5-1-u6-C5","difficulty":1,"kind":"sa","stem":"가로 8 cm, 세로 7 cm인 직사각형 카드의 넓이는 몇 cm²인가요?","answer":["56"],"explanation":["한 줄에 8칸씩 7줄이라고 생각해요.","넓이는 (가로) × (세로)예요.","8 × 7 = 56 — 넓이는 56 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#10','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C5',2,'mc','auto','한 변의 길이가 9 cm인 정사각형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X07','M5-1-u6-X16']::text[],false,'{"seq":10,"concept":"M5-1-u6-C5","difficulty":2,"kind":"mc","stem":"한 변의 길이가 9 cm인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"81 cm²","correct":true},{"t":"36 cm²","mis":"M5-1-u6-X01"},{"t":"18 cm²","mis":"M5-1-u6-X07"},{"t":"45 cm²","mis":"M5-1-u6-X16"}],"explanation":["정사각형은 가로와 세로가 같아요.","넓이는 (한 변) × (한 변)이에요.","9 × 9 = 81 — 넓이는 81 cm²예요. 9 × 4 = 36은 둘레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#11','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C5',3,'sa','auto','넓이가 63 cm²인 직사각형의 가로가 9 cm예요. 세로는 몇 cm인가요?','{}'::text[],false,'{"seq":11,"concept":"M5-1-u6-C5","difficulty":3,"kind":"sa","stem":"넓이가 63 cm²인 직사각형의 가로가 9 cm예요. 세로는 몇 cm인가요?","answer":["7"],"explanation":["(가로) × (세로) = (넓이)예요.","9 × □ = 63이니 □ = 63 ÷ 9예요.","63 ÷ 9 = 7 — 세로는 7 cm예요."],"mis":"M5-1-u6-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#12','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C6',1,'mc','auto','1 km²는 몇 m²인가요?',ARRAY['M5-1-u6-X07']::text[],false,'{"seq":12,"concept":"M5-1-u6-C6","difficulty":1,"kind":"mc","stem":"1 km²는 몇 m²인가요?","options":[{"t":"1000000 m²","correct":true},{"t":"1000 m²","mis":"M5-1-u6-X07"},{"t":"10000 m²","mis":"M5-1-u6-X07"},{"t":"100 m²","mis":"M5-1-u6-X07"}],"explanation":["1 km = 1000 m예요.","한 변 1 km 정사각형은 가로 1000 m, 세로 1000 m예요.","1000 × 1000 = 1000000 — 1 km² = 1000000 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#13','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C6',3,'sa','auto','가로 600 cm, 세로 200 cm인 현수막이 있어요. 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":13,"concept":"M5-1-u6-C6","difficulty":3,"kind":"sa","stem":"가로 600 cm, 세로 200 cm인 현수막이 있어요. 넓이는 몇 m²인가요?","answer":["12"],"explanation":["cm로 곱하면 600 × 200 = 120000이에요 — 120000 cm²예요.","1 m² = 10000 cm²니 120000 ÷ 10000 = 12예요.","m로 바꾸어 곱해도 6 × 2 = 12 — 넓이는 12 m²예요."],"mis":"M5-1-u6-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#14','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C7',1,'sa','auto','밑변이 7 cm, 높이가 6 cm인 평행사변형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":14,"concept":"M5-1-u6-C7","difficulty":1,"kind":"sa","stem":"밑변이 7 cm, 높이가 6 cm인 평행사변형의 넓이는 몇 cm²인가요?","answer":["42"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 7, 높이 6을 곱해요.","7 × 6 = 42 — 넓이는 42 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#15','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C7',2,'mc','auto','밑변 9 cm, 이웃한 변 6 cm, 높이 5 cm인 평행사변형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X09','M5-1-u6-X01','M5-1-u6-X16']::text[],false,'{"seq":15,"concept":"M5-1-u6-C7","difficulty":2,"kind":"mc","stem":"밑변 9 cm, 이웃한 변 6 cm, 높이 5 cm인 평행사변형의 넓이는 몇 cm²인가요?","options":[{"t":"45 cm²","correct":true},{"t":"54 cm²","mis":"M5-1-u6-X09"},{"t":"30 cm²","mis":"M5-1-u6-X01"},{"t":"50 cm²","mis":"M5-1-u6-X16"}],"explanation":["넓이에는 이웃한 변이 아니라 높이를 써요.","잘라 옮긴 직사각형의 세로가 높이 5 cm이기 때문이에요.","9 × 5 = 45 — 넓이는 45 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#16','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C7',3,'sa','auto','밑변 15 cm, 높이 4 cm인 평행사변형이 있어요. 길이가 12 cm인 이웃한 변을 밑변으로 하면 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":16,"concept":"M5-1-u6-C7","difficulty":3,"kind":"sa","stem":"밑변 15 cm, 높이 4 cm인 평행사변형이 있어요. 길이가 12 cm인 이웃한 변을 밑변으로 하면 높이는 몇 cm인가요?","answer":["5"],"explanation":["넓이는 밑변을 어느 쪽으로 정해도 같아요 — 15 × 4 = 60이에요.","새 밑변 12 cm로 □ × 12 = 60이에요.","60 ÷ 12 = 5 — 높이는 5 cm예요."],"mis":"M5-1-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#17','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C8',1,'sa','auto','밑변이 8 cm, 높이가 5 cm인 삼각형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":17,"concept":"M5-1-u6-C8","difficulty":1,"kind":"sa","stem":"밑변이 8 cm, 높이가 5 cm인 삼각형의 넓이는 몇 cm²인가요?","answer":["20"],"explanation":["삼각형의 넓이는 (밑변의 길이) × (높이) ÷ 2예요.","8 × 5 = 40은 평행사변형 전체예요.","40 ÷ 2 = 20 — 넓이는 20 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#18','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C8',2,'mc','auto','삼각형 ㄱㄴㄷ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 것은 어느 것인가요?',ARRAY['M5-1-u6-X11','M5-1-u6-X17']::text[],false,'{"seq":18,"concept":"M5-1-u6-C8","difficulty":2,"kind":"mc","stem":"삼각형 ㄱㄴㄷ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 것은 어느 것인가요?","options":[{"t":"선분 ㄱㄹ","correct":true},{"t":"선분 ㄱㄷ","mis":"M5-1-u6-X11"},{"t":"선분 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"선분 ㄱㄴ","mis":"M5-1-u6-X11"}],"explanation":["밑변과 마주 보는 꼭짓점 ㄱ에서 밑변에 수직으로 그은 선분이 높이예요.","꼭짓점 ㄱ이 밑변 바깥쪽 위에 있어 밑변을 늘인 선에 수직으로 내려요 — 높이가 삼각형 밖에 있어요.","그래서 높이는 선분 ㄱㄹ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[120,15],"ㄴ":[15,75],"ㄷ":[75,75],"ㄹ":[120,75]},"poly":[["ㄱ","ㄴ","ㄷ"]],"seg":[["ㄱ","ㄹ"],["ㄷ","ㄹ"]],"right":[["ㄱ","ㄹ","ㄴ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#19','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C8',4,'sa','auto','세 변이 30 cm, 40 cm, 50 cm인 직각삼각형에서 가장 긴 변 50 cm를 밑변으로 하면 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":19,"concept":"M5-1-u6-C8","difficulty":4,"kind":"sa","stem":"세 변이 30 cm, 40 cm, 50 cm인 직각삼각형에서 가장 긴 변 50 cm를 밑변으로 하면 높이는 몇 cm인가요?","answer":["24"],"explanation":["직각을 낀 두 변으로 넓이를 구하면 30 × 40 ÷ 2 = 600이에요.","밑변을 50 cm로 바꾸어도 넓이는 같으니 50 × □ ÷ 2 = 600이에요.","□ = 600 × 2 ÷ 50 = 24 — 높이는 24 cm예요."],"mis":"M5-1-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#20','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C9',2,'sa','auto','윗변 5 cm, 아랫변 7 cm, 높이 4 cm인 사다리꼴의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":20,"concept":"M5-1-u6-C9","difficulty":2,"kind":"sa","stem":"윗변 5 cm, 아랫변 7 cm, 높이 4 cm인 사다리꼴의 넓이는 몇 cm²인가요?","answer":["24"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","5 + 7 = 12예요.","(5 + 7) × 4 ÷ 2 = 24 — 넓이는 24 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#21','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C9',3,'sa','auto','넓이가 45 cm²인 사다리꼴의 윗변이 4 cm, 아랫변이 6 cm예요. 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":21,"concept":"M5-1-u6-C9","difficulty":3,"kind":"sa","stem":"넓이가 45 cm²인 사다리꼴의 윗변이 4 cm, 아랫변이 6 cm예요. 높이는 몇 cm인가요?","answer":["9"],"explanation":["(4 + 6) × □ ÷ 2 = 45예요.","10 × □ = 45 × 2 = 90이에요.","□ = 90 ÷ 10 = 9 — 높이는 9 cm예요."],"mis":"M5-1-u6-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#22','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C10',2,'sa','auto','두 대각선의 길이가 8 cm와 6 cm인 마름모의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":22,"concept":"M5-1-u6-C10","difficulty":2,"kind":"sa","stem":"두 대각선의 길이가 8 cm와 6 cm인 마름모의 넓이는 몇 cm²인가요?","answer":["24"],"explanation":["마름모를 감싸는 직사각형은 8 × 6 = 48이에요.","마름모는 그 절반이에요.","8 × 6 ÷ 2 = 24 — 넓이는 24 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#23','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C10',3,'sa','auto','넓이가 48 cm²인 마름모의 한 대각선이 12 cm예요. 다른 대각선은 몇 cm인가요?','{}'::text[],false,'{"seq":23,"concept":"M5-1-u6-C10","difficulty":3,"kind":"sa","stem":"넓이가 48 cm²인 마름모의 한 대각선이 12 cm예요. 다른 대각선은 몇 cm인가요?","answer":["8"],"explanation":["12 × □ ÷ 2 = 48이에요.","12 × □ = 48 × 2 = 96이에요.","□ = 96 ÷ 12 = 8 — 다른 대각선은 8 cm예요."],"mis":"M5-1-u6-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#24','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C11',4,'sa','auto','한 변이 10 m인 정사각형 마당 안쪽 가장자리를 따라 폭 1 m인 길을 빙 둘러 냈어요. 길의 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":24,"concept":"M5-1-u6-C11","difficulty":4,"kind":"sa","stem":"한 변이 10 m인 정사각형 마당 안쪽 가장자리를 따라 폭 1 m인 길을 빙 둘러 냈어요. 길의 넓이는 몇 m²인가요?","answer":["36"],"explanation":["마당 전체는 10 × 10 = 100이에요.","길 안쪽 정사각형은 한 변이 10 − 1 − 1 = 8 — 8 × 8 = 64예요.","100 − 64 = 36 — 길은 36 m²예요."],"mis":"M5-1-u6-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_b#25','math',5,1,'u6','','g5_1_math_u6_review_b','unit_review','M5-1-u6-C11',4,'sa','auto','가로 12 cm, 세로 7 cm인 직사각형 종이의 한 귀퉁이에서 가로 5 cm, 세로 2 cm인 직사각형을 잘라 냈어요. 남은 종이의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":25,"concept":"M5-1-u6-C11","difficulty":4,"kind":"sa","stem":"가로 12 cm, 세로 7 cm인 직사각형 종이의 한 귀퉁이에서 가로 5 cm, 세로 2 cm인 직사각형을 잘라 냈어요. 남은 종이의 넓이는 몇 cm²인가요?","answer":["74"],"explanation":["처음 종이의 넓이는 12 × 7 = 84예요.","잘라 낸 부분의 넓이는 5 × 2 = 10이에요.","84 − 10 = 74 — 남은 넓이는 74 cm²예요."],"mis":"M5-1-u6-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#1','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C1',1,'mc','auto','게시판 가장자리에 색 띠지를 두르려고 해요. 띠지가 얼마나 필요한지 알려면 무엇을 구해야 하나요?',ARRAY['M5-1-u6-X01','M5-1-u6-X03']::text[],false,'{"seq":1,"concept":"M5-1-u6-C1","difficulty":1,"kind":"mc","stem":"게시판 가장자리에 색 띠지를 두르려고 해요. 띠지가 얼마나 필요한지 알려면 무엇을 구해야 하나요?","options":[{"t":"게시판의 둘레","correct":true},{"t":"게시판의 넓이","mis":"M5-1-u6-X01"},{"t":"게시판 안쪽 칸의 수","mis":"M5-1-u6-X01"},{"t":"게시판 한 변의 길이","mis":"M5-1-u6-X03"}],"explanation":["띠지는 가장자리를 따라 둘러요.","가장자리를 따라 잰 길이가 둘레예요.","그래서 게시판의 둘레를 구해야 해요 — 넓이는 도화지로 덮을 때 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#2','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C1',2,'sa','auto','둘레가 18 cm인 직사각형의 가로가 7 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":2,"concept":"M5-1-u6-C1","difficulty":2,"kind":"sa","stem":"둘레가 18 cm인 직사각형의 가로가 7 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?","answer":["14"],"explanation":["가로 + 세로 = 18 ÷ 2 = 9예요.","세로 = 9 − 7 = 2예요.","넓이는 7 × 2 = 14 — 14 cm²예요."],"mis":"M5-1-u6-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#3','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C2',1,'sa','auto','가로 11 m, 세로 3 m인 직사각형의 둘레는 몇 m인가요?','{}'::text[],false,'{"seq":3,"concept":"M5-1-u6-C2","difficulty":1,"kind":"sa","stem":"가로 11 m, 세로 3 m인 직사각형의 둘레는 몇 m인가요?","answer":["28"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","11 + 3 + 11 + 3 = 28이에요.","(11 + 3) × 2 = 28로 구해도 돼요 — 둘레는 28 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#4','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C2',2,'sa','auto','평행사변형의 밑변이 12 m, 이웃한 변이 3 m예요. 둘레는 몇 m인가요?','{}'::text[],false,'{"seq":4,"concept":"M5-1-u6-C2","difficulty":2,"kind":"sa","stem":"평행사변형의 밑변이 12 m, 이웃한 변이 3 m예요. 둘레는 몇 m인가요?","answer":["30"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","12 + 3 + 12 + 3 = 30이에요.","(12 + 3) × 2 = 30 — 둘레는 30 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#5','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C3',1,'mc','auto','한 변의 길이가 4 cm인 정팔각형의 둘레는 몇 cm인가요?',ARRAY['M5-1-u6-X05']::text[],false,'{"seq":5,"concept":"M5-1-u6-C3","difficulty":1,"kind":"mc","stem":"한 변의 길이가 4 cm인 정팔각형의 둘레는 몇 cm인가요?","options":[{"t":"32 cm","correct":true},{"t":"16 cm","mis":"M5-1-u6-X05"},{"t":"36 cm","mis":"M5-1-u6-X05"},{"t":"28 cm","mis":"M5-1-u6-X05"}],"explanation":["정팔각형은 변이 8개이고 길이가 모두 같아요.","4 cm를 8번 더하는 것과 같아요.","4 × 8 = 32 — 둘레는 32 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#6','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C3',3,'sa','auto','길이가 80 cm인 철사로 한 변이 6 cm인 정팔각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?','{}'::text[],false,'{"seq":6,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"길이가 80 cm인 철사로 한 변이 6 cm인 정팔각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?","answer":["32"],"explanation":["정팔각형을 만드는 데 쓴 철사는 둘레만큼이에요.","6 × 8 = 48이에요.","80 − 48 = 32 — 남은 철사는 32 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#7','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C4',1,'sa','auto','도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 7칸씩 4줄이었어요. 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":7,"concept":"M5-1-u6-C4","difficulty":1,"kind":"sa","stem":"도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 7칸씩 4줄이었어요. 넓이는 몇 cm²인가요?","answer":["28"],"explanation":["한 줄에 7칸, 그런 줄이 4줄이에요.","7 × 4 = 28 — 칸은 모두 28개예요.","한 칸이 1 cm²니 넓이는 28 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#8','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C4',2,'sa','auto','모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":8,"concept":"M5-1-u6-C4","difficulty":2,"kind":"sa","stem":"모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["14"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 14칸이에요.","한 칸이 1 cm²니 넓이는 14 cm²예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[15,15],[45,15],[45,45],[90,45],[90,75],[15,75]]],"show":[]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#9','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C5',1,'sa','auto','가로 12 m, 세로 5 m인 직사각형 꽃밭의 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":9,"concept":"M5-1-u6-C5","difficulty":1,"kind":"sa","stem":"가로 12 m, 세로 5 m인 직사각형 꽃밭의 넓이는 몇 m²인가요?","answer":["60"],"explanation":["한 줄에 12칸씩 5줄이라고 생각해요.","넓이는 (가로) × (세로)예요.","12 × 5 = 60 — 넓이는 60 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#10','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C5',2,'mc','auto','한 변의 길이가 8 cm인 정사각형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X07','M5-1-u6-X16']::text[],false,'{"seq":10,"concept":"M5-1-u6-C5","difficulty":2,"kind":"mc","stem":"한 변의 길이가 8 cm인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"64 cm²","correct":true},{"t":"32 cm²","mis":"M5-1-u6-X01"},{"t":"16 cm²","mis":"M5-1-u6-X07"},{"t":"40 cm²","mis":"M5-1-u6-X16"}],"explanation":["정사각형은 가로와 세로가 같아요.","넓이는 (한 변) × (한 변)이에요.","8 × 8 = 64 — 넓이는 64 cm²예요. 8 × 4 = 32는 둘레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#11','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C5',3,'sa','auto','넓이가 72 cm²인 직사각형의 가로가 8 cm예요. 세로는 몇 cm인가요?','{}'::text[],false,'{"seq":11,"concept":"M5-1-u6-C5","difficulty":3,"kind":"sa","stem":"넓이가 72 cm²인 직사각형의 가로가 8 cm예요. 세로는 몇 cm인가요?","answer":["9"],"explanation":["(가로) × (세로) = (넓이)예요.","8 × □ = 72니 □ = 72 ÷ 8이에요.","72 ÷ 8 = 9 — 세로는 9 cm예요."],"mis":"M5-1-u6-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#12','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C6',1,'mc','auto','1 m²는 어떤 넓이인가요?',ARRAY['M5-1-u6-X06']::text[],false,'{"seq":12,"concept":"M5-1-u6-C6","difficulty":1,"kind":"mc","stem":"1 m²는 어떤 넓이인가요?","options":[{"t":"한 변의 길이가 1 m인 정사각형의 넓이","correct":true},{"t":"한 변의 길이가 1 cm인 정사각형의 넓이","mis":"M5-1-u6-X06"},{"t":"둘레가 1 m인 도형의 넓이","mis":"M5-1-u6-X06"},{"t":"가로가 1 m인 직사각형의 넓이","mis":"M5-1-u6-X06"}],"explanation":["1 cm²를 약속한 것처럼 더 큰 칸도 약속해요.","한 변이 1 m인 정사각형의 넓이가 1 m²(1 제곱미터)예요.","둘레나 가로 하나로는 칸이 정해지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#13','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C6',3,'sa','auto','가로 900 cm, 세로 200 cm인 현수막이 있어요. 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":13,"concept":"M5-1-u6-C6","difficulty":3,"kind":"sa","stem":"가로 900 cm, 세로 200 cm인 현수막이 있어요. 넓이는 몇 m²인가요?","answer":["18"],"explanation":["cm로 곱하면 900 × 200 = 180000이에요 — 180000 cm²예요.","1 m² = 10000 cm²니 180000 ÷ 10000 = 18이에요.","m로 바꾸어 곱해도 9 × 2 = 18 — 넓이는 18 m²예요."],"mis":"M5-1-u6-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#14','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C7',1,'sa','auto','밑변이 11 m, 높이가 8 m인 평행사변형의 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":14,"concept":"M5-1-u6-C7","difficulty":1,"kind":"sa","stem":"밑변이 11 m, 높이가 8 m인 평행사변형의 넓이는 몇 m²인가요?","answer":["88"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 11, 높이 8을 곱해요.","11 × 8 = 88 — 넓이는 88 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#15','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C7',2,'mc','auto','밑변 8 cm, 이웃한 변 7 cm, 높이 6 cm인 평행사변형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X09','M5-1-u6-X10','M5-1-u6-X01']::text[],false,'{"seq":15,"concept":"M5-1-u6-C7","difficulty":2,"kind":"mc","stem":"밑변 8 cm, 이웃한 변 7 cm, 높이 6 cm인 평행사변형의 넓이는 몇 cm²인가요?","options":[{"t":"48 cm²","correct":true},{"t":"56 cm²","mis":"M5-1-u6-X09"},{"t":"24 cm²","mis":"M5-1-u6-X10"},{"t":"30 cm²","mis":"M5-1-u6-X01"}],"explanation":["넓이에는 이웃한 변이 아니라 높이를 써요.","잘라 옮긴 직사각형의 세로가 높이 6 cm이기 때문이에요.","8 × 6 = 48 — 넓이는 48 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#16','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C7',3,'sa','auto','밑변 16 cm, 높이 6 cm인 평행사변형이 있어요. 길이가 12 cm인 이웃한 변을 밑변으로 하면 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":16,"concept":"M5-1-u6-C7","difficulty":3,"kind":"sa","stem":"밑변 16 cm, 높이 6 cm인 평행사변형이 있어요. 길이가 12 cm인 이웃한 변을 밑변으로 하면 높이는 몇 cm인가요?","answer":["8"],"explanation":["넓이는 밑변을 어느 쪽으로 정해도 같아요 — 16 × 6 = 96이에요.","새 밑변 12 cm로 □ × 12 = 96이에요.","96 ÷ 12 = 8 — 높이는 8 cm예요."],"mis":"M5-1-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#17','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C8',1,'sa','auto','밑변이 10 cm, 높이가 9 cm인 삼각형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":17,"concept":"M5-1-u6-C8","difficulty":1,"kind":"sa","stem":"밑변이 10 cm, 높이가 9 cm인 삼각형의 넓이는 몇 cm²인가요?","answer":["45"],"explanation":["삼각형의 넓이는 (밑변의 길이) × (높이) ÷ 2예요.","10 × 9 = 90은 평행사변형 전체예요.","90 ÷ 2 = 45 — 넓이는 45 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#18','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C8',2,'mc','auto','삼각형 ㄱㄴㄷ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 것은 어느 것인가요?',ARRAY['M5-1-u6-X11','M5-1-u6-X17']::text[],false,'{"seq":18,"concept":"M5-1-u6-C8","difficulty":2,"kind":"mc","stem":"삼각형 ㄱㄴㄷ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 것은 어느 것인가요?","options":[{"t":"변 ㄱㄴ","correct":true},{"t":"변 ㄱㄷ","mis":"M5-1-u6-X11"},{"t":"변 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"높이를 그릴 수 없다","mis":"M5-1-u6-X11"}],"explanation":["밑변과 마주 보는 꼭짓점 ㄱ에서 밑변에 수직으로 그은 선분이 높이예요.","직각삼각형은 직각을 낀 변 ㄱㄴ이 그대로 높이예요.","그래서 높이는 변 ㄱㄴ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[30,15],"ㄴ":[30,75],"ㄷ":[120,75]},"poly":[["ㄱ","ㄴ","ㄷ"]],"right":[["ㄱ","ㄴ","ㄷ"]],"show":["ㄱ","ㄴ","ㄷ"]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#19','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C8',4,'sa','auto','세 변이 45 cm, 60 cm, 75 cm인 직각삼각형에서 가장 긴 변 75 cm를 밑변으로 하면 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":19,"concept":"M5-1-u6-C8","difficulty":4,"kind":"sa","stem":"세 변이 45 cm, 60 cm, 75 cm인 직각삼각형에서 가장 긴 변 75 cm를 밑변으로 하면 높이는 몇 cm인가요?","answer":["36"],"explanation":["직각을 낀 두 변으로 넓이를 구하면 45 × 60 ÷ 2 = 1350이에요.","밑변을 75 cm로 바꾸어도 넓이는 같으니 75 × □ ÷ 2 = 1350이에요.","□ = 1350 × 2 ÷ 75 = 36 — 높이는 36 cm예요."],"mis":"M5-1-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#20','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C9',2,'sa','auto','윗변 4 m, 아랫변 8 m, 높이 5 m인 사다리꼴의 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":20,"concept":"M5-1-u6-C9","difficulty":2,"kind":"sa","stem":"윗변 4 m, 아랫변 8 m, 높이 5 m인 사다리꼴의 넓이는 몇 m²인가요?","answer":["30"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","4 + 8 = 12예요.","(4 + 8) × 5 ÷ 2 = 30 — 넓이는 30 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#21','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C9',3,'sa','auto','넓이가 40 cm²인 사다리꼴의 윗변이 3 cm, 아랫변이 7 cm예요. 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":21,"concept":"M5-1-u6-C9","difficulty":3,"kind":"sa","stem":"넓이가 40 cm²인 사다리꼴의 윗변이 3 cm, 아랫변이 7 cm예요. 높이는 몇 cm인가요?","answer":["8"],"explanation":["(3 + 7) × □ ÷ 2 = 40이에요.","10 × □ = 40 × 2 = 80이에요.","□ = 80 ÷ 10 = 8 — 높이는 8 cm예요."],"mis":"M5-1-u6-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#22','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C10',2,'sa','auto','두 대각선의 길이가 10 cm와 9 cm인 마름모의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":22,"concept":"M5-1-u6-C10","difficulty":2,"kind":"sa","stem":"두 대각선의 길이가 10 cm와 9 cm인 마름모의 넓이는 몇 cm²인가요?","answer":["45"],"explanation":["마름모를 감싸는 직사각형은 10 × 9 = 90이에요.","마름모는 그 절반이에요.","10 × 9 ÷ 2 = 45 — 넓이는 45 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#23','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C10',3,'sa','auto','넓이가 35 cm²인 마름모의 한 대각선이 7 cm예요. 다른 대각선은 몇 cm인가요?','{}'::text[],false,'{"seq":23,"concept":"M5-1-u6-C10","difficulty":3,"kind":"sa","stem":"넓이가 35 cm²인 마름모의 한 대각선이 7 cm예요. 다른 대각선은 몇 cm인가요?","answer":["10"],"explanation":["7 × □ ÷ 2 = 35예요.","7 × □ = 35 × 2 = 70이에요.","□ = 70 ÷ 7 = 10 — 다른 대각선은 10 cm예요."],"mis":"M5-1-u6-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#24','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C11',4,'sa','auto','한 변이 8 m인 정사각형 마당 안쪽 가장자리를 따라 폭 1 m인 길을 빙 둘러 냈어요. 길의 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":24,"concept":"M5-1-u6-C11","difficulty":4,"kind":"sa","stem":"한 변이 8 m인 정사각형 마당 안쪽 가장자리를 따라 폭 1 m인 길을 빙 둘러 냈어요. 길의 넓이는 몇 m²인가요?","answer":["28"],"explanation":["마당 전체는 8 × 8 = 64예요.","길 안쪽 정사각형은 한 변이 8 − 1 − 1 = 6 — 6 × 6 = 36이에요.","64 − 36 = 28 — 길은 28 m²예요."],"mis":"M5-1-u6-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_c#25','math',5,1,'u6','','g5_1_math_u6_review_c','unit_review','M5-1-u6-C11',4,'sa','auto','가로 9 cm, 세로 9 cm인 직사각형 종이의 한 귀퉁이에서 가로 3 cm, 세로 4 cm인 직사각형을 잘라 냈어요. 남은 종이의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":25,"concept":"M5-1-u6-C11","difficulty":4,"kind":"sa","stem":"가로 9 cm, 세로 9 cm인 직사각형 종이의 한 귀퉁이에서 가로 3 cm, 세로 4 cm인 직사각형을 잘라 냈어요. 남은 종이의 넓이는 몇 cm²인가요?","answer":["69"],"explanation":["처음 종이의 넓이는 9 × 9 = 81이에요.","잘라 낸 부분의 넓이는 3 × 4 = 12예요.","81 − 12 = 69 — 남은 넓이는 69 cm²예요."],"mis":"M5-1-u6-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#1','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C1',1,'mc','auto','게시판 안쪽을 도화지로 빈틈없이 덮으려고 해요. 도화지가 얼마나 필요한지 알려면 무엇을 구해야 하나요?',ARRAY['M5-1-u6-X01','M5-1-u6-X03']::text[],false,'{"seq":1,"concept":"M5-1-u6-C1","difficulty":1,"kind":"mc","stem":"게시판 안쪽을 도화지로 빈틈없이 덮으려고 해요. 도화지가 얼마나 필요한지 알려면 무엇을 구해야 하나요?","options":[{"t":"게시판의 넓이","correct":true},{"t":"게시판의 둘레","mis":"M5-1-u6-X01"},{"t":"게시판 가장자리의 길이","mis":"M5-1-u6-X01"},{"t":"게시판 한 변의 길이","mis":"M5-1-u6-X03"}],"explanation":["도화지는 게시판 안쪽을 덮어요.","안쪽을 덮은 칸의 수가 넓이예요.","그래서 게시판의 넓이를 구해야 해요 — 둘레는 띠지를 두를 때 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#2','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C1',2,'sa','auto','둘레가 22 cm인 직사각형의 가로가 8 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":2,"concept":"M5-1-u6-C1","difficulty":2,"kind":"sa","stem":"둘레가 22 cm인 직사각형의 가로가 8 cm예요. 이 직사각형의 넓이는 몇 cm²인가요?","answer":["24"],"explanation":["가로 + 세로 = 22 ÷ 2 = 11이에요.","세로 = 11 − 8 = 3이에요.","넓이는 8 × 3 = 24 — 24 cm²예요."],"mis":"M5-1-u6-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#3','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C2',1,'sa','auto','가로 7 cm, 세로 5 cm인 직사각형의 둘레는 몇 cm인가요?','{}'::text[],false,'{"seq":3,"concept":"M5-1-u6-C2","difficulty":1,"kind":"sa","stem":"가로 7 cm, 세로 5 cm인 직사각형의 둘레는 몇 cm인가요?","answer":["24"],"explanation":["직사각형은 마주 보는 두 변의 길이가 같아요.","7 + 5 + 7 + 5 = 24예요.","(7 + 5) × 2 = 24로 구해도 돼요 — 둘레는 24 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#4','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C2',2,'sa','auto','평행사변형의 밑변이 10 cm, 이웃한 변이 6 cm예요. 둘레는 몇 cm인가요?','{}'::text[],false,'{"seq":4,"concept":"M5-1-u6-C2","difficulty":2,"kind":"sa","stem":"평행사변형의 밑변이 10 cm, 이웃한 변이 6 cm예요. 둘레는 몇 cm인가요?","answer":["32"],"explanation":["평행사변형은 마주 보는 두 변의 길이가 같아요.","10 + 6 + 10 + 6 = 32예요.","(10 + 6) × 2 = 32 — 둘레는 32 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#5','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C3',1,'mc','auto','한 변의 길이가 9 cm인 정삼각형의 둘레는 몇 cm인가요?',ARRAY['M5-1-u6-X05','M5-1-u6-X16']::text[],false,'{"seq":5,"concept":"M5-1-u6-C3","difficulty":1,"kind":"mc","stem":"한 변의 길이가 9 cm인 정삼각형의 둘레는 몇 cm인가요?","options":[{"t":"27 cm","correct":true},{"t":"36 cm","mis":"M5-1-u6-X05"},{"t":"18 cm","mis":"M5-1-u6-X05"},{"t":"12 cm","mis":"M5-1-u6-X16"}],"explanation":["정삼각형은 변이 3개이고 길이가 모두 같아요.","9 cm를 3번 더하는 것과 같아요.","9 × 3 = 27 — 둘레는 27 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#6','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C3',3,'sa','auto','길이가 100 cm인 철사로 한 변이 8 cm인 정구각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?','{}'::text[],false,'{"seq":6,"concept":"M5-1-u6-C3","difficulty":3,"kind":"sa","stem":"길이가 100 cm인 철사로 한 변이 8 cm인 정구각형 하나를 만들었어요. 남은 철사는 몇 cm인가요?","answer":["28"],"explanation":["정구각형을 만드는 데 쓴 철사는 둘레만큼이에요.","8 × 9 = 72예요.","100 − 72 = 28 — 남은 철사는 28 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#7','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C4',1,'sa','auto','도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 8칸씩 3줄이었어요. 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":7,"concept":"M5-1-u6-C4","difficulty":1,"kind":"sa","stem":"도형을 1 cm² 칸으로 빈틈없이 덮었더니 한 줄에 8칸씩 3줄이었어요. 넓이는 몇 cm²인가요?","answer":["24"],"explanation":["한 줄에 8칸, 그런 줄이 3줄이에요.","8 × 3 = 24 — 칸은 모두 24개예요.","한 칸이 1 cm²니 넓이는 24 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#8','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C4',2,'sa','auto','모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":8,"concept":"M5-1-u6-C4","difficulty":2,"kind":"sa","stem":"모눈 한 칸은 1 cm²예요. 그림에서 색칠한 도형의 넓이는 몇 cm²인가요?","answer":["14"],"explanation":["도형을 직사각형 몇 개로 나누어 칸을 세어 봐요.","나눈 부분의 칸을 빠짐없이 모두 더하면 14칸이에요.","한 칸이 1 cm²니 넓이는 14 cm²예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"grid":15,"poly":[[[15,15],[90,15],[90,75],[60,75],[60,45],[15,45]]],"show":[]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#9','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C5',1,'sa','auto','가로 6 cm, 세로 9 cm인 직사각형 카드의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":9,"concept":"M5-1-u6-C5","difficulty":1,"kind":"sa","stem":"가로 6 cm, 세로 9 cm인 직사각형 카드의 넓이는 몇 cm²인가요?","answer":["54"],"explanation":["한 줄에 6칸씩 9줄이라고 생각해요.","넓이는 (가로) × (세로)예요.","6 × 9 = 54 — 넓이는 54 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#10','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C5',2,'mc','auto','한 변의 길이가 6 cm인 정사각형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X01','M5-1-u6-X07','M5-1-u6-X16']::text[],false,'{"seq":10,"concept":"M5-1-u6-C5","difficulty":2,"kind":"mc","stem":"한 변의 길이가 6 cm인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"36 cm²","correct":true},{"t":"24 cm²","mis":"M5-1-u6-X01"},{"t":"12 cm²","mis":"M5-1-u6-X07"},{"t":"30 cm²","mis":"M5-1-u6-X16"}],"explanation":["정사각형은 가로와 세로가 같아요.","넓이는 (한 변) × (한 변)이에요.","6 × 6 = 36 — 넓이는 36 cm²예요. 6 × 4 = 24는 둘레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#11','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C5',3,'sa','auto','넓이가 56 cm²인 직사각형의 가로가 7 cm예요. 세로는 몇 cm인가요?','{}'::text[],false,'{"seq":11,"concept":"M5-1-u6-C5","difficulty":3,"kind":"sa","stem":"넓이가 56 cm²인 직사각형의 가로가 7 cm예요. 세로는 몇 cm인가요?","answer":["8"],"explanation":["(가로) × (세로) = (넓이)예요.","7 × □ = 56이니 □ = 56 ÷ 7이에요.","56 ÷ 7 = 8 — 세로는 8 cm예요."],"mis":"M5-1-u6-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#12','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C6',1,'mc','auto','1 km²는 어떤 넓이인가요?',ARRAY['M5-1-u6-X06']::text[],false,'{"seq":12,"concept":"M5-1-u6-C6","difficulty":1,"kind":"mc","stem":"1 km²는 어떤 넓이인가요?","options":[{"t":"한 변의 길이가 1 km인 정사각형의 넓이","correct":true},{"t":"한 변의 길이가 1 m인 정사각형의 넓이","mis":"M5-1-u6-X06"},{"t":"둘레가 1 km인 도형의 넓이","mis":"M5-1-u6-X06"},{"t":"가로가 1 km인 직사각형의 넓이","mis":"M5-1-u6-X06"}],"explanation":["땅처럼 아주 넓은 곳은 더 큰 칸이 필요해요.","한 변이 1 km인 정사각형의 넓이를 1 km²(1 제곱킬로미터)라고 해요.","둘레나 가로 하나로는 칸이 정해지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#13','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C6',3,'sa','auto','가로 500 cm, 세로 400 cm인 현수막이 있어요. 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":13,"concept":"M5-1-u6-C6","difficulty":3,"kind":"sa","stem":"가로 500 cm, 세로 400 cm인 현수막이 있어요. 넓이는 몇 m²인가요?","answer":["20"],"explanation":["cm로 곱하면 500 × 400 = 200000이에요 — 200000 cm²예요.","1 m² = 10000 cm²니 200000 ÷ 10000 = 20이에요.","m로 바꾸어 곱해도 5 × 4 = 20 — 넓이는 20 m²예요."],"mis":"M5-1-u6-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#14','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C7',1,'sa','auto','밑변이 12 cm, 높이가 5 cm인 평행사변형의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":14,"concept":"M5-1-u6-C7","difficulty":1,"kind":"sa","stem":"밑변이 12 cm, 높이가 5 cm인 평행사변형의 넓이는 몇 cm²인가요?","answer":["60"],"explanation":["평행사변형의 넓이는 (밑변의 길이) × (높이)예요.","밑변 12, 높이 5를 곱해요.","12 × 5 = 60 — 넓이는 60 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#15','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C7',2,'mc','auto','밑변 10 cm, 이웃한 변 6 cm, 높이 4 cm인 평행사변형의 넓이는 몇 cm²인가요?',ARRAY['M5-1-u6-X09','M5-1-u6-X10','M5-1-u6-X01']::text[],false,'{"seq":15,"concept":"M5-1-u6-C7","difficulty":2,"kind":"mc","stem":"밑변 10 cm, 이웃한 변 6 cm, 높이 4 cm인 평행사변형의 넓이는 몇 cm²인가요?","options":[{"t":"40 cm²","correct":true},{"t":"60 cm²","mis":"M5-1-u6-X09"},{"t":"20 cm²","mis":"M5-1-u6-X10"},{"t":"32 cm²","mis":"M5-1-u6-X01"}],"explanation":["넓이에는 이웃한 변이 아니라 높이를 써요.","잘라 옮긴 직사각형의 세로가 높이 4 cm이기 때문이에요.","10 × 4 = 40 — 넓이는 40 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#16','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C7',3,'sa','auto','밑변 18 cm, 높이 4 cm인 평행사변형이 있어요. 길이가 9 cm인 이웃한 변을 밑변으로 하면 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":16,"concept":"M5-1-u6-C7","difficulty":3,"kind":"sa","stem":"밑변 18 cm, 높이 4 cm인 평행사변형이 있어요. 길이가 9 cm인 이웃한 변을 밑변으로 하면 높이는 몇 cm인가요?","answer":["8"],"explanation":["넓이는 밑변을 어느 쪽으로 정해도 같아요 — 18 × 4 = 72예요.","새 밑변 9 cm로 □ × 9 = 72예요.","72 ÷ 9 = 8 — 높이는 8 cm예요."],"mis":"M5-1-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#17','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C8',1,'sa','auto','밑변이 12 m, 높이가 7 m인 삼각형의 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":17,"concept":"M5-1-u6-C8","difficulty":1,"kind":"sa","stem":"밑변이 12 m, 높이가 7 m인 삼각형의 넓이는 몇 m²인가요?","answer":["42"],"explanation":["삼각형의 넓이는 (밑변의 길이) × (높이) ÷ 2예요.","12 × 7 = 84는 평행사변형 전체예요.","84 ÷ 2 = 42 — 넓이는 42 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#18','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C8',2,'mc','auto','삼각형 ㄱㄴㄷ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 것은 어느 것인가요?',ARRAY['M5-1-u6-X11','M5-1-u6-X17']::text[],false,'{"seq":18,"concept":"M5-1-u6-C8","difficulty":2,"kind":"mc","stem":"삼각형 ㄱㄴㄷ에서 변 ㄴㄷ을 밑변으로 할 때 높이를 나타내는 것은 어느 것인가요?","options":[{"t":"선분 ㄱㄹ","correct":true},{"t":"선분 ㄱㄴ","mis":"M5-1-u6-X11"},{"t":"선분 ㄴㄷ","mis":"M5-1-u6-X17"},{"t":"선분 ㄱㄷ","mis":"M5-1-u6-X11"}],"explanation":["밑변과 마주 보는 꼭짓점 ㄱ에서 밑변에 수직으로 그은 선분이 높이예요.","꼭짓점 ㄱ이 밑변 바깥쪽 위에 있어 밑변을 늘인 선에 수직으로 내려요 — 높이가 삼각형 밖에 있어요.","그래서 높이는 선분 ㄱㄹ이에요."],"asset":{"type":"geo","items":[{"w":150,"h":90,"pts":{"ㄱ":[15,15],"ㄴ":[60,75],"ㄷ":[135,75],"ㄹ":[15,75]},"poly":[["ㄱ","ㄴ","ㄷ"]],"seg":[["ㄱ","ㄹ"],["ㄴ","ㄹ"]],"right":[["ㄱ","ㄹ","ㄷ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#19','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C8',4,'sa','auto','세 변이 20 cm, 15 cm, 25 cm인 직각삼각형에서 가장 긴 변 25 cm를 밑변으로 하면 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":19,"concept":"M5-1-u6-C8","difficulty":4,"kind":"sa","stem":"세 변이 20 cm, 15 cm, 25 cm인 직각삼각형에서 가장 긴 변 25 cm를 밑변으로 하면 높이는 몇 cm인가요?","answer":["12"],"explanation":["직각을 낀 두 변으로 넓이를 구하면 20 × 15 ÷ 2 = 150이에요.","밑변을 25 cm로 바꾸어도 넓이는 같으니 25 × □ ÷ 2 = 150이에요.","□ = 150 × 2 ÷ 25 = 12 — 높이는 12 cm예요."],"mis":"M5-1-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#20','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C9',2,'sa','auto','윗변 3 cm, 아랫변 9 cm, 높이 6 cm인 사다리꼴의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":20,"concept":"M5-1-u6-C9","difficulty":2,"kind":"sa","stem":"윗변 3 cm, 아랫변 9 cm, 높이 6 cm인 사다리꼴의 넓이는 몇 cm²인가요?","answer":["36"],"explanation":["사다리꼴의 넓이는 ((윗변) + (아랫변)) × (높이) ÷ 2예요.","3 + 9 = 12예요.","(3 + 9) × 6 ÷ 2 = 36 — 넓이는 36 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#21','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C9',3,'sa','auto','넓이가 48 cm²인 사다리꼴의 윗변이 5 cm, 아랫변이 7 cm예요. 높이는 몇 cm인가요?','{}'::text[],false,'{"seq":21,"concept":"M5-1-u6-C9","difficulty":3,"kind":"sa","stem":"넓이가 48 cm²인 사다리꼴의 윗변이 5 cm, 아랫변이 7 cm예요. 높이는 몇 cm인가요?","answer":["8"],"explanation":["(5 + 7) × □ ÷ 2 = 48이에요.","12 × □ = 48 × 2 = 96이에요.","□ = 96 ÷ 12 = 8 — 높이는 8 cm예요."],"mis":"M5-1-u6-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#22','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C10',2,'sa','auto','두 대각선의 길이가 14 m와 6 m인 마름모의 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":22,"concept":"M5-1-u6-C10","difficulty":2,"kind":"sa","stem":"두 대각선의 길이가 14 m와 6 m인 마름모의 넓이는 몇 m²인가요?","answer":["42"],"explanation":["마름모를 감싸는 직사각형은 14 × 6 = 84예요.","마름모는 그 절반이에요.","14 × 6 ÷ 2 = 42 — 넓이는 42 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#23','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C10',3,'sa','auto','넓이가 54 cm²인 마름모의 한 대각선이 9 cm예요. 다른 대각선은 몇 cm인가요?','{}'::text[],false,'{"seq":23,"concept":"M5-1-u6-C10","difficulty":3,"kind":"sa","stem":"넓이가 54 cm²인 마름모의 한 대각선이 9 cm예요. 다른 대각선은 몇 cm인가요?","answer":["12"],"explanation":["9 × □ ÷ 2 = 54예요.","9 × □ = 54 × 2 = 108이에요.","□ = 108 ÷ 9 = 12 — 다른 대각선은 12 cm예요."],"mis":"M5-1-u6-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#24','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C11',4,'sa','auto','한 변이 11 m인 정사각형 마당 안쪽 가장자리를 따라 폭 1 m인 길을 빙 둘러 냈어요. 길의 넓이는 몇 m²인가요?','{}'::text[],false,'{"seq":24,"concept":"M5-1-u6-C11","difficulty":4,"kind":"sa","stem":"한 변이 11 m인 정사각형 마당 안쪽 가장자리를 따라 폭 1 m인 길을 빙 둘러 냈어요. 길의 넓이는 몇 m²인가요?","answer":["40"],"explanation":["마당 전체는 11 × 11 = 121이에요.","길 안쪽 정사각형은 한 변이 11 − 1 − 1 = 9 — 9 × 9 = 81이에요.","121 − 81 = 40 — 길은 40 m²예요."],"mis":"M5-1-u6-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_math_u6_review_d#25','math',5,1,'u6','','g5_1_math_u6_review_d','unit_review','M5-1-u6-C11',4,'sa','auto','가로 11 cm, 세로 8 cm인 직사각형 종이의 한 귀퉁이에서 가로 4 cm, 세로 5 cm인 직사각형을 잘라 냈어요. 남은 종이의 넓이는 몇 cm²인가요?','{}'::text[],false,'{"seq":25,"concept":"M5-1-u6-C11","difficulty":4,"kind":"sa","stem":"가로 11 cm, 세로 8 cm인 직사각형 종이의 한 귀퉁이에서 가로 4 cm, 세로 5 cm인 직사각형을 잘라 냈어요. 남은 종이의 넓이는 몇 cm²인가요?","answer":["68"],"explanation":["처음 종이의 넓이는 11 × 8 = 88이에요.","잘라 낸 부분의 넓이는 4 × 5 = 20이에요.","88 − 20 = 68 — 남은 넓이는 68 cm²예요."],"mis":"M5-1-u6-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
